// ===========================================================================
// [UPERF3-GG] U-PERF3 round 5, lane GG — STAGE A INTEGRATION: the descent
// replacement in the real pass (spec: U_PERF3_OPENING_LAYER_DESIGN.md §2;
// engine side: ring/stage_a.rs; components reused read-only:
// ring/zc_range.rs [UPERF3-S]+[UPERF3-EE], ring/ec_kernel.rs [UPERF3-DD]).
// The frozen BK full-statement path (bk_pass_run) is the ORACLE; everything
// here is additive and selector-gated — the default path stays
// byte-identical (the frozen digests are the floor).
//
// `uperf-a` dispatch (lane GG owns the dispatch line): the Stage-A arms
// below; the legacy [UPERF2-A] subcommands (descent-bench /
// descent-battery) delegate to uperf_a_main verbatim.
//
//   uperf-a map [layers] [t]  — rung 1: THE OBJECT MAP (no proving) — every
//     descent-pair family of the real pass at the shape, its instance
//     count / depth / served claims, and its Stage-A replacement instance.

fn uperf_a_gg_main(args: &[String]) {
    let geti = |i: usize, d: usize| args.get(i).and_then(|s| s.parse::<usize>().ok()).unwrap_or(d);
    match args.first().map(String::as_str) {
        Some("map") => uperf_a_gg_map(geti(1, bf_model().layers), geti(2, bf_model().t)),
        Some("diff") => {
            let pair = args.get(1).cloned().unwrap_or_else(|| "rem-w6".to_string());
            uperf_a_gg_diff(&pair, geti(2, 3), geti(3, 16), geti(4, 205) as u8);
        }
        Some("pass") => {
            let mode = match args.get(3).map(String::as_str) {
                // [UPERF3-SS] rung V3: `full` IS the committed-h routing at
                // kappa 4 (the compact helper; V2's counted pick); the S2
                // form GG built stays reachable as `full-s2` (byte-identical
                // to the pre-V3 `full`, V1 leg 1).
                Some("full") => GgMode::FullSs(SsCfg { kappa_silu: 4, route_nrw: None, tamper_sum: false }),
                Some("full-s2") => GgMode::Full,
                Some("masked") => GgMode::Masked,
                // [UPERF3-SS] `full-ss [k<kappa_silu>] [r<kappa_route>|noroute] [ss-sum]`.
                Some("full-ss") => {
                    let mut cfg = SsCfg { kappa_silu: 0, route_nrw: Some(0), tamper_sum: false };
                    for a in args.iter().skip(4) {
                        if let Some(k) = a.strip_prefix('k').and_then(|s| s.parse::<u8>().ok()) {
                            cfg.kappa_silu = k;
                        } else if let Some(k) = a.strip_prefix('r').and_then(|s| s.parse::<u8>().ok()) {
                            cfg.route_nrw = Some(k);
                        } else if a == "noroute" {
                            cfg.route_nrw = None;
                        } else if a == "ss-sum" {
                            cfg.tamper_sum = true;
                        }
                    }
                    GgMode::FullSs(cfg)
                }
                _ => GgMode::Range,
            };
            if let GgMode::FullSs(cfg) = mode {
                let accept = uperf_a_gg_pass(geti(1, 3), geti(2, 16), mode, false, GgTamper::None);
                if cfg.tamper_sum {
                    assert!(!accept, "ss-sum tamper leg must reject");
                    println!("[UPERF3-SS] tamper ss-sum REJECTED as required");
                } else {
                    assert!(accept, "full-ss honest pass must accept");
                }
                return;
            }
            let t4 = args.get(4).map(String::as_str);
            let tamper = match t4 {
                Some("mask-commit") => GgTamper::MaskCommit,
                Some("mask-served") => GgTamper::MaskServed,
                Some("claim") => GgTamper::Claim,
                Some("round") => GgTamper::Round,
                _ => GgTamper::None,
            };
            let with_oracle = t4 != Some("nooracle") && tamper == GgTamper::None;
            let accept = uperf_a_gg_pass(geti(1, 3), geti(2, 16), mode, with_oracle, tamper);
            if tamper != GgTamper::None {
                assert!(!accept, "tamper leg must reject");
                println!("[UPERF3-GG] tamper leg REJECTED as required");
            }
        }
        Some("pass-battery") => {
            let (l, t) = (geti(1, 3), geti(2, 16));
            assert!(uperf_a_gg_pass(l, t, GgMode::Masked, false, GgTamper::None), "masked honest must accept");
            for (name, tam) in [
                ("mask-served", GgTamper::MaskServed),
                ("mask-commit", GgTamper::MaskCommit),
                ("claim", GgTamper::Claim),
                ("round", GgTamper::Round),
            ] {
                assert!(!uperf_a_gg_pass(l, t, GgMode::Masked, false, tam), "tamper {name} must reject");
                println!("[UPERF3-GG] pass-battery: tamper {name} REJECTED as required");
            }
            println!("[UPERF3-GG] pass-battery: masked honest ACCEPT + 4 tamper legs REJECT — all green");
        }
        Some("descent-bench") | Some("descent-battery") => uperf_a_main(args),
        // [UPERF3-SS] round 10 — the full-mode (committed-h) arms; ADDITIVE.
        Some("full-plan") => uperf_a_ss_plan(),
        Some("ss-diff") => uperf_a_ss_diff(geti(1, 1), geti(2, 16)),
        Some("full-count") => uperf_a_ss_count(geti(1, 12), geti(2, 512)),
        _ => {
            println!(
                "uperf-a map [layers] [t] | diff [pair] [layers] [t] [seed] | pass [layers] [t] [range|full|masked] [nooracle|mask-commit|mask-served|claim|round] | pass-battery [layers] [t]   ([UPERF3-GG] Stage-A integration, round 5)"
            );
            println!("uperf-a full-plan | full-count [layers] [t] | ss-diff [layers] [t] | pass [layers] [t] full (= full-ss k4 noroute) | full-s2 (the S2 form) | full-ss [k<kappa_silu>] [r<kappa_route>|noroute] [ss-sum]   ([UPERF3-SS] the committed-h rungs V1-V4, round 10)");
            uperf_a_main(args);
        }
    }
}

// ---------------------------------------------------------------------------
// [UPERF3-SS] round 10, lane SS — the committed-h encoding (rungs V1-V4;
// engine side: ring/stage_a_full.rs, reached through ring::stage_a::full).
// Rung 0: the plan printer + the ring arithmetic sanity against lane GG's
// measured act-h rows.
fn uperf_a_ss_plan() {
    use ring::stage_a::full as ssf;
    println!("[UPERF3-SS] the committed-h encoding — rung plan (spec U_PERF3_COMMITTED_H.md §3):");
    for (i, l) in ssf::plan_lines().iter().enumerate() {
        println!("  {}. {l}", i + 1);
    }
    let f_pad = bf_f().next_power_of_two();
    let l0_q = ring::digits::derive_l0(-((ring::Q8 / 2) as i64), (ring::Q8 / 2) as i64, 2);
    println!(
        "[UPERF3-SS] what the act-h group is: the S2 LogUp helper h_i = 1/(alpha - key_i) of the SiLU pairs — {} K coords x l0_q {} digits = {} digit rings per element",
        ring::kfield::K_DEG,
        l0_q,
        ssf::helper_rings(1 << 20, ring::kfield::K_DEG, l0_q) as f64 / (1u64 << 20) as f64
    );
    for (layers, t, measured) in [(3usize, 16usize, 196_608usize), (12, 128, 6_291_456)] {
        let counted = ssf::gg_act_h_rings(layers, t, f_pad, l0_q);
        println!(
            "  {layers}x{t}: act-h rings COUNTED {counted} vs GG MEASURED {measured} ({}); planes (w = 8) over the same elements {} rings; kappa-level pf helper kappa 3 {} / kappa 4 {} rings (degree {} / {})",
            if counted == measured { "MATCH" } else { "MISMATCH" },
            ssf::planes_rings(layers * t * f_pad, 8),
            ssf::pf_helper_rings(layers * t * f_pad, 3, l0_q),
            ssf::pf_helper_rings(layers * t * f_pad, 4, l0_q),
            ssf::pf_degree(3),
            ssf::pf_degree(4),
        );
    }
}

/// [UPERF3-SS] rung V2 — `uperf-a full-count [layers] [t]`: the
/// helper/multiplicity commit bill, (a) from the REAL registries of the
/// loaded m125 layers at the shape (gg_build_groups in range / full /
/// full-ss kappa 0,3,4,5 — engine structures, no proving), (b) the same
/// arithmetic at the 8B shapes (32x512 and 32x16 at d 4096 / f 14336 ->
/// f_pad 16384) with the MVP8B/OO memory law [MODEL].
fn uperf_a_ss_count(layers_n: usize, t: usize) {
    use ring::stage_a::full as ssf;
    let q = ring::Q8;
    let l0_q = ring::digits::derive_l0(-((q / 2) as i64), (q / 2) as i64, 2);
    println!(
        "[UPERF3-SS] full-count: the committed-h bill at {layers_n}x{t} (m125 d {} f {}) from the engine registries [COUNTED]:",
        bf_d(),
        bf_f()
    );
    let lays: Vec<BfLayer> = (0..layers_n).map(|l| bf_load_layer(l, t, true)).collect();
    let specs = bk_pair_specs(&lays, t);
    let modes: Vec<(&str, GgMode)> = vec![
        ("range (planes; silu descents)", GgMode::Range),
        ("full (S2 K-helper, as built)", GgMode::Full),
        ("full-ss kappa 3, no route", GgMode::FullSs(SsCfg { kappa_silu: 3, route_nrw: None, tamper_sum: false })),
        ("full-ss kappa 4, no route", GgMode::FullSs(SsCfg { kappa_silu: 4, route_nrw: None, tamper_sum: false })),
        ("full-ss kappa 5, no route", GgMode::FullSs(SsCfg { kappa_silu: 5, route_nrw: None, tamper_sum: false })),
        ("full-ss kappa 0 + nrw-88 l0 h8 routed (V1)", GgMode::FullSs(SsCfg { kappa_silu: 0, route_nrw: Some(0), tamper_sum: false })),
    ];
    let reg_o = bk_build_groups(&lays, t, &specs, q);
    println!(
        "  {:<44} weight n_0 {:>11} act n_0 {:>11} (the frozen BK registry, descents for every family)",
        "oracle (bk_pass_run)", reg_o.gw.n_digit_rings, reg_o.ga.n_digit_rings
    );
    for (label, mode) in modes {
        let (reg, gh, plans) = gg_build_groups(&lays, t, &specs, q, mode);
        let planes: usize = plans
            .iter()
            .flat_map(|p| p.classes.iter().map(|c| reg.ga.tensors[c.ti].n_digit_rings()))
            .sum();
        let mults: usize = plans
            .iter()
            .filter_map(|p| p.logup.map(|(ti_m, _, _)| reg.ga.tensors[ti_m].n_digit_rings()))
            .sum::<usize>()
            + plans.iter().flat_map(|p| p.ss_routes.iter().map(|r| reg.ga.tensors[r.ti_m].n_digit_rings())).sum::<usize>();
        let h_rings = gh.as_ref().map(|g| g.n_digit_rings).unwrap_or(0);
        println!(
            "  {:<44} weight n_0 {:>11} act n_0 {:>11} (planes {:>9}, mults {:>6}) act-h n_0 {:>11} | act-h / act {:.2}x | store act-h {:.3} GB",
            label,
            reg.gw.n_digit_rings,
            reg.ga.n_digit_rings,
            planes,
            mults,
            h_rings,
            h_rings as f64 / reg.ga.n_digit_rings as f64,
            h_rings as f64 * 128.0 / 1e9,
        );
    }
    let f_pad = bf_f().next_power_of_two();
    let n_el = layers_n * t * f_pad;
    println!("  arithmetic cross-check at this shape (silu elements {n_el} = {layers_n} x {t} x {f_pad}; cap {} rings/group at e0 = 2):", ssf::act_group_cap(q));
    for r in ssf::count_rows(n_el, l0_q, q, false) {
        println!("    {:<40} {:>12} rings  groups {}  store {:.3} GB", r.label, r.rings, r.groups, r.store_gb);
    }
    for (l8, t8) in [(32usize, 512usize), (32, 16)] {
        let (d8, f8) = (4096usize, 14336usize);
        let f8_pad = f8.next_power_of_two();
        let n8 = l8 * t8 * f8_pad;
        println!(
            "[UPERF3-SS] full-count at the 8B shape {l8}x{t8} (d {d8} f {f8} -> f_pad {f8_pad}; silu elements {n8}; range-form baseline [OO 2026-08-31]: weight n_0 352,321,536, act n_0 145,475,764 -> commit ~61 GB, pass peak lvl-0 ~72 GB):"
        );
        for r in ssf::count_rows(n8, l0_q, q, t8 == 512) {
            if t8 == 512 {
                println!(
                    "    {:<40} {:>12} rings  groups {}  store {:>6.1} GB  pass peak [MODEL] {:>6.1} GB",
                    r.label, r.rings, r.groups, r.store_gb, r.peak_8b_gb
                );
            } else {
                println!("    {:<40} {:>12} rings  groups {}  store {:>6.2} GB", r.label, r.rings, r.groups, r.store_gb);
            }
        }
        // The C2-literal bill: every range fact of the pass as a K-helper
        // lookup (the planes it would replace, for the same elements).
        let n_range = l8 * t8 * (3 * f8_pad + d8.next_power_of_two()) + l8 * t8 * (2 * f8_pad + d8.next_power_of_two());
        println!(
            "    C2-literal (ALL range facts as K-helper lookups): {} elements -> {} rings (vs their w~8 planes {} rings) [COUNTED, w = 8 for every remainder = MODEL]",
            n_range,
            ssf::helper_rings(n_range, ring::kfield::K_DEG, l0_q),
            ssf::planes_rings(n_range, 8)
        );
    }
}

/// [UPERF3-SS] one SiLU member's fused lookup column over the strided
/// grid (built twice per pass — for the helper, then for the sumcheck —
/// so the boxed keys of one column at a time are live).
fn ss_silu_col(
    kf: &ring::kfield::KField,
    sp: &BkPairSpec,
    m: &BkMember,
    lays: &[BfLayer],
    table: &[ring::kfield::KElem],
) -> ring::stage_a::full::LookupCol {
    use ring::lookup::{silu_v2_member, silu_v2_rows};
    use std::collections::HashMap;
    let zq = &kf.zq;
    let (eg, ea) = sp.silu.expect("silu pair");
    let (bytes, _) = silu_v2_member(eg, ea).expect("frozen member");
    let rows = silu_v2_rows(bytes);
    let idx: HashMap<(u64, u64), usize> =
        rows.iter().enumerate().map(|(j, &(v, s))| ((zq.to_mod(v), zq.to_mod(s)), j)).collect();
    let prim = bf_entry_values(m.entry, &lays[m.li]);
    let img = bf_entry_values(m.pair_entry.expect("silu image"), &lays[m.li]);
    ring::stage_a::full::fused_lookup_col(kf, &prim, &img, m.shape.rows, m.shape.cols, m.shape.cols_pad(), table, &idx)
}

/// [UPERF3-SS] the served objects of one routed lookup column, absorbed
/// (prover and verifier alike) after its sumcheck.
fn ss_absorb_served(kf: &ring::kfield::KField, tr: &mut ring::sumcheck::LkpTranscript, out: &ring::stage_a::full::LookupOut) {
    tr.absorb_k(kf, "gg-lu-final", &out.proof.final_evals);
    let mut served = vec![out.h_sum.clone(), out.table_sum.clone(), out.h_at_point.clone()];
    served.extend(out.keys_at_point.iter().cloned());
    tr.absorb_k(kf, "gg-lu-served", &served);
}

/// [UPERF3-SS] the claim builder of one routed lookup column (shared by
/// prover and verifier): (i) h_sum and h(x*) over the helper block
/// [h_block * n_h, +n_h) of the act-h tensor (ones / eq row kernels x
/// ypow); (ii) per leaf position b < 2^kappa the key claim key_b(x*)
/// over the member tensor — the fused (prim + Y * img) pair for a SiLU
/// member, or value + offset for an identity-table member (served as
/// key_b(x*) - offset * S_eq over the real grid, the gg_zc_claims link);
/// the row kernel eq over the rows, the column kernel eq over the column
/// nodes gated on the low kappa bits == b; (iii) the table_sum claim
/// over the multiplicity block [m_block * t_rows, +t_rows).
#[allow(clippy::too_many_arguments)]
fn ss_lookup_claims(
    kf: &ring::kfield::KField,
    reg: &BkRegistry,
    sp: &BkPairSpec,
    m: &BkMember,
    ti_m: usize,
    m_block: usize,
    ti_h: usize,
    gh_rows: usize,
    h_block: usize,
    alpha: &ring::kfield::KElem,
    table_k: &[ring::kfield::KElem],
    out: &ring::stage_a::full::LookupOut,
    claims: &mut Vec<BkClaim>,
    claims_h: &mut Vec<(ring::kfield::KElem, Vec<(usize, ring::kfield::KElem, std::rc::Rc<Vec<ring::kfield::KElem>>, std::rc::Rc<Vec<ring::kfield::KElem>>)>)>,
) {
    use ring::gkr::eq_table;
    use std::rc::Rc;
    let one = kf.one();
    let ypow = bk_ypow_col(kf);
    let kappa = out.kappa;
    let n_h = 1usize << out.point.len();
    let mut ones_row = vec![kf.zero(); gh_rows];
    ones_row[h_block * n_h..(h_block + 1) * n_h].fill(kf.one());
    claims_h.push((out.h_sum.clone(), vec![(ti_h, one.clone(), Rc::new(ones_row), ypow.clone())]));
    let eq_pt = eq_table(kf, &out.point);
    let mut h_row = vec![kf.zero(); gh_rows];
    h_row[h_block * n_h..(h_block + 1) * n_h].clone_from_slice(&eq_pt);
    claims_h.push((out.h_at_point.clone(), vec![(ti_h, one.clone(), Rc::new(h_row), ypow.clone())]));
    let cols_pad = m.shape.cols_pad();
    let lcp = cols_pad.trailing_zeros() as usize;
    assert!(kappa <= lcp, "the leaf position rides the column bits");
    let eq_lo_node = eq_table(kf, &out.point[..lcp - kappa]);
    let eq_hi = Rc::new(eq_table(kf, &out.point[lcp - kappa..]));
    let hi_sum = eq_hi.iter().fold(kf.zero(), |a, e| kf.add(&a, e));
    let (_, ti_prim) = reg.map[m.li][m.entry];
    let leaves = 1usize << kappa;
    for b in 0..leaves {
        // The column kernel over the padded grid, split at the real
        // column count: the member tensor sees [0, cols); the pads
        // [cols, cols_pad) carry the table's row-0 key (subtracted below).
        let mut kcol = vec![kf.zero(); m.shape.cols];
        let mut pad_sum = kf.zero();
        for c in 0..cols_pad {
            if c & (leaves - 1) == b {
                let e = &eq_lo_node[c >> kappa];
                if c < m.shape.cols {
                    kcol[c] = e.clone();
                } else {
                    pad_sum = kf.add(&pad_sum, e);
                }
            }
        }
        let lo_sum = kcol.iter().fold(kf.zero(), |a, e| kf.add(&a, e));
        let s_pad = kf.mul(&hi_sum, &pad_sum);
        let value = kf.sub(&out.keys_at_point[b], &kf.mul(&table_k[0], &s_pad));
        let kcol = Rc::new(kcol);
        match m.pair_entry {
            Some(pe) => {
                let (_, ti_img) = reg.map[m.li][pe];
                let y_one = ring::lookup::mul_y(kf, &kf.one());
                claims.push(BkClaim {
                    in_weight: false,
                    value,
                    parts: vec![(ti_prim, one.clone(), eq_hi.clone(), kcol.clone()), (ti_img, y_one, eq_hi.clone(), kcol)],
                });
            }
            None => {
                let s_eq = kf.mul(&hi_sum, &lo_sum);
                let value = kf.sub(&value, &kf.scale(kf.zq.to_mod(m.offset), &s_eq));
                claims.push(BkClaim { in_weight: false, value, parts: vec![(ti_prim, one.clone(), eq_hi.clone(), kcol)] });
            }
        }
    }
    let m_cols = reg.ga.tensors[ti_m].cols;
    let mut m_col = vec![kf.zero(); m_cols];
    for (row_j, t_row) in table_k.iter().enumerate() {
        m_col[m_block * sp.t_rows + row_j] = kf.inv(&kf.sub(alpha, t_row));
    }
    claims.push(BkClaim {
        in_weight: false,
        value: out.table_sum.clone(),
        parts: vec![(ti_m, one, Rc::new(vec![kf.one()]), Rc::new(m_col))],
    });
}

/// [UPERF3-SS] `uperf-a ss-diff [layers] [t]`: the routed identity lookup
/// STANDALONE on the real layer-0 h8 column (the R2 discipline): the
/// honest column at kappa 0 (the S2 form) and kappa 3/4 (the partial-
/// fraction form) — accept, every served value grounded directly, the
/// three forms' h_sum identical (the same rational identity); then the
/// two tamper legs — an OFF-TABLE code (the BK RangeViolation shape,
/// the prover honest about its own inverse) must fail the SUM gate with
/// the chain intact, and a corrupted served key must fail the CHAIN.
fn uperf_a_ss_diff(layers_n: usize, t: usize) {
    use ring::kfield::{KElem, KField};
    use ring::stage_a::full::{
        h_at_point_direct, identity_lookup_col, key_at_point_direct, lookup_helper, lookup_prove, lookup_verify,
        lookup_wire_bytes, pf_degree, planes_rings, table_sum, LookupCol,
    };
    use ring::sumcheck::LkpTranscript;
    println!("[UPERF3-SS] ss-diff: the layer-0 h8 narrowing fact as a 256-row identity lookup, {layers_n} layers loaded, T = {t} [WSL-BOX NOISY-SHARED]");
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let zq = ctxr.zq;
    let lays: Vec<BfLayer> = (0..layers_n).map(|l| bf_load_layer(l, t, true)).collect();
    let specs = bk_pair_specs(&lays, t);
    let sp = specs.iter().find(|s| s.name() == "nrw-88").expect("nrw-88 present");
    let mi = sp.members.iter().position(|m| m.li == 0 && BF_ENTRIES[m.entry] == "h8").expect("layer-0 h8");
    let m = &sp.members[mi];
    let vals: Vec<i64> = bf_entry_values(m.entry, &lays[0]).to_vec();
    let table_k = sp.table_k(&kf);
    let w = sp.t_rows.trailing_zeros() as usize;
    let mut ok_all = true;
    let mut h_sums: Vec<KElem> = Vec::new();
    let run = |vals: &[i64], kappa: usize, corrupt_key: bool, label: &str, _ok_all: &mut bool, h_sums: &mut Vec<KElem>| {
        let col: LookupCol = identity_lookup_col(&kf, vals, m.offset, m.shape.rows, m.shape.cols, m.shape.cols_pad(), sp.t_rows);
        let off_table = col.row_of.iter().filter(|r| r.is_none()).count();
        // One alpha for every form (the sums are compared across kappa).
        let alpha = LkpTranscript::fixed_coins("uperf3-ss-diff-alpha", &[]).challenge_k(&kf);
        let mut tr = LkpTranscript::fixed_coins("uperf3-ss-diff", &[kappa as u8, corrupt_key as u8]);
        let (h, h_sum) = lookup_helper(&kf, &col, &table_k, &alpha, kappa);
        let n = col.n_log2 - kappa;
        let rho: Vec<KElem> = (0..n).map(|_| tr.challenge_k(&kf)).collect();
        let t0 = Instant::now();
        let mut out = lookup_prove(&kf, &col, &table_k, &alpha, &rho, kappa, &h, &mut tr);
        let secs = t0.elapsed().as_secs_f64();
        let leaves = 1usize << kappa;
        let keys_ok = (0..leaves).all(|b| key_at_point_direct(&kf, &col, &out.point, kappa, b) == out.keys_at_point[b]);
        let h_ok = h_at_point_direct(&kf, &h, &out.point) == out.h_at_point;
        let ts = table_sum(&kf, &table_k, &col.mult, &alpha);
        let sums_ok = out.h_sum == h_sum && out.table_sum == ts;
        if corrupt_key {
            out.keys_at_point[0] = kf.add(&out.keys_at_point[0], &kf.one());
        }
        let alpha_v = LkpTranscript::fixed_coins("uperf3-ss-diff-alpha", &[]).challenge_k(&kf);
        let mut tv = LkpTranscript::fixed_coins("uperf3-ss-diff", &[kappa as u8, corrupt_key as u8]);
        let rho_v: Vec<KElem> = (0..n).map(|_| tv.challenge_k(&kf)).collect();
        let (chain_ok, sum_ok) = lookup_verify(&kf, col.n_log2, &alpha_v, &rho_v, &out, &mut tv);
        let rings_h = ring::stage_a::full::helper_rings(h.len(), ring::kfield::K_DEG, 16);
        println!(
            "  {label}: kappa {kappa} (degree {}, {} rounds) | off-table codes {off_table} | chain {} sum {} | key_b(x*) grounded {}/{} h(x*) grounded {} sums {} | helper {} K elems = {} rings vs planes {} rings | wire {} B | prove {:.2}s",
            pf_degree(kappa),
            n,
            chain_ok,
            sum_ok,
            (0..leaves).filter(|&b| key_at_point_direct(&kf, &col, &out.point, kappa, b) == out.keys_at_point[b]).count(),
            leaves,
            h_ok,
            sums_ok,
            h.len(),
            rings_h,
            planes_rings(1usize << col.n_log2, w),
            lookup_wire_bytes(&out),
            secs,
        );
        h_sums.push(out.h_sum.clone());
        (chain_ok, sum_ok, keys_ok && h_ok && sums_ok)
    };
    for kappa in [0usize, 3, 4] {
        let (c, s, g) = run(&vals, kappa, false, "honest", &mut ok_all, &mut h_sums);
        ok_all &= c && s && g;
    }
    let same_sum = h_sums.iter().all(|s| *s == h_sums[0]);
    println!("  the three forms' h_sum identical (same alpha, same rational identity): {same_sum}");
    ok_all &= same_sum;
    // Tamper 1: one code off the table (value 300 -> code 428 >= 256; the
    // committed class l0 = 5 at e0 = 2 represents it, as the BK
    // RangeViolation leg's values do).
    let mut bad = vals.clone();
    bad[0] = 300;
    for kappa in [0usize, 3] {
        let (c, s, _g) = run(&bad, kappa, false, "TAMPER off-table", &mut ok_all, &mut h_sums);
        assert!(c && !s, "off-table code must fail the sum gate with the chain intact (kappa {kappa})");
        println!("    -> REJECTED at the sum gate, chain intact (kappa {kappa})");
    }
    // Tamper 2: a corrupted served key claim — the chain's final identity.
    for kappa in [0usize, 3] {
        let (c, _s, _g) = run(&vals, kappa, true, "TAMPER served key", &mut ok_all, &mut h_sums);
        assert!(!c, "a corrupted served key must fail the chain (kappa {kappa})");
        println!("    -> REJECTED at the chain gate (kappa {kappa})");
    }
    assert!(ok_all, "ss-diff honest legs must all be green");
    let _ = zq;
    println!("[UPERF3-SS] ss-diff: ALL LEGS GREEN (peak RSS {:.0} MiB)", uperf_a_peak_rss_mib());
}

// [UPERF3-GG] rung 3 — THE COMPOSED PASS behind the selector: bk_pass_run's
// full-statement composition with the DESCENT PHASE replaced by the Stage-A
// components. bk_pass_run itself is READ-ONLY (the oracle); this driver is
// a separate additive arm (`uperf-a pass`), so the default path stays
// byte-identical by construction. Two selector modes:
//
//   Range (default): the 8 range/narrowing pair families replaced by
//     aggregate zero-checks over committed width-w bit planes (one zc_agg
//     per pair x shape class, [UPERF3-EE]); the 2 SiLU pairs keep the
//     frozen masked descents. NO stand-ins: every served claim is grounded
//     by the group openings.
//   Full: the SiLU pairs replaced too (LogUp-as-one-sumcheck, [UPERF3-S]).
//     The helper h depends on alpha, and u_0 is NONLINEAR in the witness
//     (that0 is a digit decomposition), so h CANNOT ride u_0(T_act) drawn
//     before alpha (the memo §2.1/§2.4 ordering is circular — recorded as
//     a finding). Resolution: a THIRD commitment group "act-h" committed
//     mid-transcript (u_0(T_h) absorbed AFTER alpha, BEFORE rho), served by
//     its own single opening — E-O2-BB (one opening per group) preserved;
//     the pass gains a third group.
//
// Transcript layout (selector path, own domain "uperf3-gg-pass"): h0 =
// SHA(domain, statement digest, gg map bytes incl. the act-h inventory,
// u_0(W), u_0(act)); then the 8-instance claim layer verbatim; then the
// Stage-A phase in spec order (silu alphas first in Full mode, u_0(T_h),
// then per-column LogUp sumchecks; zc_agg per range pair class with
// rho/betas from the transcript and the stacked claims absorbed); publics;
// nu per claim; the 2 (Range) or 3 (Full) group eval proofs.

#[derive(Clone, Copy, PartialEq)]
enum GgMode {
    Range,
    Full,
    /// Range mode with the O-4 MASKED aggregates: per class a private
    /// ZcAggMask (M1 g-mask shape in E_4) drawn from ProverRng, its
    /// coefficients COMMITTED as an act tensor before any challenge
    /// (mask-then-fold via u_0(T_act) inside h0 — the wm/tm idiom), the
    /// hypersum + final-eval openings served and ground by claims.
    Masked,
    /// [UPERF3-SS] Full mode under the committed-h routing (ring/
    /// stage_a_full.rs): the SiLU helpers at kappa levels (kappa 0 = the
    /// S2 form of `Full`), optionally one nrw-88 member routed through a
    /// 256-row identity lookup over its EXISTING commitment (rung V1).
    FullSs(SsCfg),
}

/// [UPERF3-SS] the full-mode routing configuration.
#[derive(Clone, Copy, PartialEq, Debug)]
struct SsCfg {
    /// kappa of the SiLU pairs' partial-fraction helper (0 = S2 as built).
    kappa_silu: u8,
    /// Route the nrw-88 member (layer 0, h8) through the identity lookup
    /// at this kappa (None = the planes form, as in range mode).
    route_nrw: Option<u8>,
    /// Tamper: flip the routed column's served h_sum — must REJECT at the
    /// lookup's sum gate.
    tamper_sum: bool,
}

/// [UPERF3-SS] one member routed through the identity lookup (rung V1).
#[derive(Clone, Copy)]
struct SsRoute {
    /// Member index into sp.members.
    mi: usize,
    /// The multiplicity tensor (act) and the helper tensor (act-h).
    ti_m: usize,
    ti_h: usize,
    n_log2: usize,
    kappa: usize,
}

fn gg_is_full(mode: GgMode) -> bool {
    matches!(mode, GgMode::Full | GgMode::FullSs(_))
}

/// Rung-4 tamper legs (each must REJECT at a named gate).
#[derive(Clone, Copy, PartialEq)]
enum GgTamper {
    None,
    /// Flip one COMMITTED mask coefficient (witness side) while proving
    /// with the true mask; ct rows forced (the BD WrongC pattern) —
    /// REJECT lands in the act group's floor chain.
    MaskCommit,
    /// Flip the SERVED mask final evaluation — REJECT at the masked
    /// aggregate's final identity (zc-agg gate).
    MaskServed,
    /// Flip one served stacked claim — REJECT at the aggregate's
    /// recombination / final identity (zc-agg gate).
    Claim,
    /// Flip one round-poly node — REJECT in the aggregate's round chain
    /// (zc-agg gate).
    Round,
}

const GG_MASK_A: [&str; 10] = [
    "zca-mk-a-silu-m3", "zca-mk-a-silu-m4", "zca-mk-a-nrw-88", "zca-mk-a-nrw-z", "zca-mk-a-rem-w5",
    "zca-mk-a-rem-w6", "zca-mk-a-rem-w7", "zca-mk-a-rem-w8", "zca-mk-a-rem-w9", "zca-mk-a-rem-w10",
];
const GG_MASK_B: [&str; 10] = [
    "zca-mk-b-silu-m3", "zca-mk-b-silu-m4", "zca-mk-b-nrw-88", "zca-mk-b-nrw-z", "zca-mk-b-rem-w5",
    "zca-mk-b-rem-w6", "zca-mk-b-rem-w7", "zca-mk-b-rem-w8", "zca-mk-b-rem-w9", "zca-mk-b-rem-w10",
];

const GG_PLANES_A: [&str; 10] = [
    "zca-a-silu-m3", "zca-a-silu-m4", "zca-a-nrw-88", "zca-a-nrw-z", "zca-a-rem-w5",
    "zca-a-rem-w6", "zca-a-rem-w7", "zca-a-rem-w8", "zca-a-rem-w9", "zca-a-rem-w10",
];
const GG_PLANES_B: [&str; 10] = [
    "zca-b-silu-m3", "zca-b-silu-m4", "zca-b-nrw-88", "zca-b-nrw-z", "zca-b-rem-w5",
    "zca-b-rem-w6", "zca-b-rem-w7", "zca-b-rem-w8", "zca-b-rem-w9", "zca-b-rem-w10",
];
const GG_M: [&str; 10] = [
    "zca-m-silu-m3", "zca-m-silu-m4", "zca-m-nrw-88", "zca-m-nrw-z", "zca-m-rem-w5",
    "zca-m-rem-w6", "zca-m-rem-w7", "zca-m-rem-w8", "zca-m-rem-w9", "zca-m-rem-w10",
];
const GG_H: [&str; 10] = [
    "zca-h-silu-m3", "zca-h-silu-m4", "zca-h-nrw-88", "zca-h-nrw-z", "zca-h-rem-w5",
    "zca-h-rem-w6", "zca-h-rem-w7", "zca-h-rem-w8", "zca-h-rem-w9", "zca-h-rem-w10",
];

/// One range pair's shape class under the selector: the planes tensor grid
/// is (m * w * rows) x cols_pad, row-major, column i's plane k occupying
/// the row block [(i*w + k)*rows, +rows); the zc hypercube index within a
/// column is x = r * cols_pad + c (low bits c — the descent tree's own
/// alignment), n_log2 = log2(rows * cols_pad).
struct GgClass {
    rows: usize,
    cols: usize,
    cols_pad: usize,
    n_log2: usize,
    w: usize,
    /// Member indices (into sp.members) of this class.
    members: Vec<usize>,
    /// The planes tensor index in the act group.
    ti: usize,
    /// Masked mode: the mask-coefficient tensor index in the act group.
    ti_mask: usize,
}

struct GgPairPlan {
    classes: Vec<GgClass>,
    /// SiLU pair in Full mode: (m tensor idx in act, h tensor idx in act-h,
    /// n_log2 per column).
    logup: Option<(usize, usize, usize)>,
    /// [UPERF3-SS] FullSs: the SiLU helper's kappa (0 elsewhere) and the
    /// members of a range pair routed through the identity lookup.
    ss_kappa: usize,
    ss_routes: Vec<SsRoute>,
}

/// The selector registry: BG's two-group layout with the Stage-A aux
/// tensors — silu pairs keep m/bl/wm/tm in Range mode (aux_base/aux_shape
/// live only for them); range pairs commit their planes tensors; Full mode
/// moves silu to (per-column m in act) + (h in the act-h group).
fn gg_build_groups(
    lays: &[BfLayer],
    t: usize,
    specs: &[BkPairSpec],
    q: u64,
    mode: GgMode,
) -> (BkRegistry, Option<ring::eval_proof::AggGroup>, Vec<GgPairPlan>) {
    use ring::gkr_masked::mask_coeff_counts;
    let mut gw = ring::eval_proof::AggGroup::new("weight");
    let mut ga = ring::eval_proof::AggGroup::new("act");
    let mut gh = ring::eval_proof::AggGroup::new("act-h");
    let mut map = vec![[(false, 0usize); 17]; lays.len()];
    for (li, lay) in lays.iter().enumerate() {
        for e in 0..BF_ENTRIES.len() {
            let (rows, cols) = bf_entry_shape(e, t);
            let (e0, l0) = bg_entry_class(e, lay);
            let to_weight = bg_is_weight_entry(e);
            let g = if to_weight { &mut gw } else { &mut ga };
            map[li][e] = (to_weight, g.tensors.len());
            g.add_tensor(BF_ENTRIES[e], rows, cols, e0, l0);
        }
    }
    let l0_q = ring::digits::derive_l0(-((q / 2) as i64), (q / 2) as i64, 2);
    let mut aux_base = Vec::with_capacity(specs.len());
    let mut aux_shape = Vec::with_capacity(specs.len());
    let mut plans = Vec::with_capacity(specs.len());
    for sp in specs {
        if sp.silu.is_some() {
            match mode {
                GgMode::Range | GgMode::Masked => {
                    // Verbatim bk_build_groups aux block for this pair.
                    let plan = &sp.plan;
                    let m_cols = bk_pad_to(plan.n_real * sp.t_rows, D);
                    let mut tree_used = vec![0usize; plan.n_real];
                    for b in &plan.blocks {
                        tree_used[b.tree] += sp.members[b.member].shape.n_el();
                    }
                    let max_used = tree_used.iter().copied().max().unwrap();
                    let l0_m = ring::digits::derive_l0(0, max_used as i64, 2);
                    let (gw_c, rw_c) = mask_coeff_counts(plan.depth, plan.e_bits);
                    let (gt_c, rt_c) = mask_coeff_counts(sp.dt, plan.e_bits);
                    let bl_kel = plan.n_real * 16;
                    let wm_kel = bk_pad_to(gw_c + rw_c, 8);
                    let tm_kel = bk_pad_to(gt_c + rt_c, 8);
                    let base = [
                        ga.tensors.len(),
                        ga.tensors.len() + 1,
                        ga.tensors.len() + 2,
                        ga.tensors.len() + 3,
                    ];
                    ga.add_tensor(BK_AUX_M[sp.pid], 1, m_cols, 2, l0_m);
                    ga.add_tensor(BK_AUX_BL[sp.pid], bl_kel, ring::kfield::K_DEG, 2, l0_q);
                    ga.add_tensor(BK_AUX_WM[sp.pid], wm_kel, ring::kfield::K_DEG, 2, l0_q);
                    ga.add_tensor(BK_AUX_TM[sp.pid], tm_kel, ring::kfield::K_DEG, 2, l0_q);
                    aux_base.push(base);
                    aux_shape.push([m_cols, bl_kel, wm_kel, tm_kel]);
                    plans.push(GgPairPlan { classes: Vec::new(), logup: None, ss_kappa: 0, ss_routes: Vec::new() });
                }
                GgMode::Full | GgMode::FullSs(_) => {
                    let m_mem = sp.members.len();
                    let shape = sp.members[0].shape;
                    let n_el = shape.rows * shape.cols_pad();
                    assert!(n_el.is_power_of_two(), "silu member hypercube must be exact");
                    let n_log2 = ring::stage_a::clog2(n_el);
                    let m_cols = bk_pad_to(m_mem * sp.t_rows, D);
                    let l0_m = ring::digits::derive_l0(0, n_el as i64, 2);
                    let ti_m = ga.tensors.len();
                    ga.add_tensor(GG_M[sp.pid], 1, m_cols, 2, l0_m);
                    let ti_h = gh.tensors.len();
                    // [UPERF3-SS] FullSs: the helper at node granularity
                    // (one K element per 2^kappa keys).
                    let kappa = match mode {
                        GgMode::FullSs(cfg) => cfg.kappa_silu as usize,
                        _ => 0,
                    };
                    gh.add_tensor(GG_H[sp.pid], (m_mem * n_el) >> kappa, ring::kfield::K_DEG, 2, l0_q);
                    aux_base.push([usize::MAX; 4]);
                    aux_shape.push([m_cols, 0, 0, 0]);
                    plans.push(GgPairPlan {
                        classes: Vec::new(),
                        logup: Some((ti_m, ti_h, n_log2)),
                        ss_kappa: kappa,
                        ss_routes: Vec::new(),
                    });
                }
            }
        } else {
            let w = sp.t_rows.trailing_zeros() as usize;
            let mut classes: Vec<GgClass> = Vec::new();
            for (mi, m) in sp.members.iter().enumerate() {
                let key = (m.shape.rows, m.shape.cols);
                match classes.iter_mut().find(|c| (c.rows, c.cols) == key) {
                    Some(c) => c.members.push(mi),
                    None => {
                        let cols_pad = m.shape.cols_pad();
                        let n_log2 = ring::stage_a::clog2(m.shape.rows * cols_pad);
                        classes.push(GgClass {
                            rows: m.shape.rows,
                            cols: m.shape.cols,
                            cols_pad,
                            n_log2,
                            w,
                            members: vec![mi],
                            ti: usize::MAX,
                            ti_mask: usize::MAX,
                        });
                    }
                }
            }
            assert!(classes.len() <= 2, "at most two shape classes per pair");
            // [UPERF3-SS] rung V1: the nrw-88 member (layer 0, h8) leaves
            // its planes class and rides the identity lookup over its
            // EXISTING commitment (multiplicities in act, helper in act-h).
            let mut ss_routes: Vec<SsRoute> = Vec::new();
            if let GgMode::FullSs(SsCfg { route_nrw: Some(kappa), .. }) = mode {
                if sp.pid == 2 {
                    let mi = sp
                        .members
                        .iter()
                        .position(|m| m.li == 0 && BF_ENTRIES[m.entry] == "h8")
                        .expect("the layer-0 h8 narrowing member");
                    for c in classes.iter_mut() {
                        c.members.retain(|&x| x != mi);
                    }
                    classes.retain(|c| !c.members.is_empty());
                    let shape = sp.members[mi].shape;
                    let n_el = shape.rows * shape.cols_pad();
                    let n_log2 = ring::stage_a::clog2(n_el);
                    let l0_m = ring::digits::derive_l0(0, n_el as i64, 2);
                    let ti_m = ga.tensors.len();
                    ga.add_tensor("zca-ss-m-nrw-88", 1, bk_pad_to(sp.t_rows, D), 2, l0_m);
                    let ti_h = gh.tensors.len();
                    gh.add_tensor("zca-ss-h-nrw-88", n_el >> (kappa as usize), ring::kfield::K_DEG, 2, l0_q);
                    ss_routes.push(SsRoute { mi, ti_m, ti_h, n_log2, kappa: kappa as usize });
                }
            }
            for (ci, c) in classes.iter_mut().enumerate() {
                let name = if ci == 0 { GG_PLANES_A[sp.pid] } else { GG_PLANES_B[sp.pid] };
                c.ti = ga.tensors.len();
                ga.add_tensor(name, c.members.len() * c.w * c.rows, c.cols_pad, 1, 1);
                if mode == GgMode::Masked {
                    // The mask-coefficient tensor: 1 + (n_log2 + a) * deg
                    // E_4 coefficients, one K-elem row each (deg = deg_f+1
                    // = 4 at e0 = 1), committed at the blinder class.
                    let n_tot = c.n_log2 + ring::zc_range::zc_agg_axis(c.members.len());
                    let n_coeff = bk_pad_to(1 + n_tot * 4, 8);
                    let mname = if ci == 0 { GG_MASK_A[sp.pid] } else { GG_MASK_B[sp.pid] };
                    c.ti_mask = ga.tensors.len();
                    ga.add_tensor(mname, n_coeff, ring::kfield::K_DEG, 2, l0_q);
                }
            }
            aux_base.push([usize::MAX; 4]);
            aux_shape.push([0; 4]);
            plans.push(GgPairPlan { classes, logup: None, ss_kappa: 0, ss_routes });
        }
    }
    let reg = BkRegistry { gw, ga, map, aux_base, aux_shape, l0_q };
    let gh_opt = if gg_is_full(mode) { Some(gh) } else { None };
    (reg, gh_opt, plans)
}

/// The selector map bytes (own domain; binds ALL three inventories —
/// the act-h shapes are statement-derived and alpha-independent, so they
/// ride h0 while u_0(T_h) itself rides the rolling transcript).
fn gg_map_bytes(reg: &BkRegistry, gh: Option<&ring::eval_proof::AggGroup>) -> Vec<u8> {
    let mut b: Vec<u8> = b"uperf3-gg-group-map-v1".to_vec();
    let mut one = |gname: &str, g: &ring::eval_proof::AggGroup| {
        b.extend(gname.as_bytes());
        b.extend((g.tensors.len() as u64).to_le_bytes());
        for t in &g.tensors {
            b.extend(t.name.as_bytes());
            for v in [t.rows, t.cols, t.e0 as usize, t.l0, t.digit_ring_base] {
                b.extend((v as u64).to_le_bytes());
            }
        }
    };
    one("weight", &reg.gw);
    one("act", &reg.ga);
    if let Some(g) = gh {
        one("act-h", g);
    }
    b
}

/// A range pair class's committed data: the strided planes values (the
/// tensor grid, i64 0/1) and, per member column, the strided (planes, rem)
/// tables the zc instance reads — BOTH built from the same bf_entry_values
/// arrays.
struct GgClassData {
    /// The committed planes tensor values (freed after the pre-commit —
    /// the digit witness carries them from there; ~6 GB at 12x512).
    planes_vals: Vec<i64>,
    /// Masked mode: the private mask + its committed coefficient values
    /// (flat() order, K coords centered).
    mask: Option<ring::zc_range::ZcAggMask>,
    mask_vals: Vec<i64>,
}

/// The zc instance's (planes, rem) u32 tables for one class — built
/// per-pair inside the Stage-A phase and dropped after (transient; the
/// same bf_entry_values bits as the committed planes).
fn gg_build_class_tabs(sp: &BkPairSpec, cls: &GgClass, lays: &[BfLayer]) -> Vec<(Vec<Vec<u32>>, Vec<u32>)> {
    // [UPERF3-RR] rung 3: one member per task (values identical; the
    // scalar loop was 0.3 s of the 12x128 Stage-A phase).
    use rayon::prelude::*;
    let size = 1usize << cls.n_log2;
    cls.members
        .par_iter()
        .map(|&mi| {
            let m = &sp.members[mi];
            let vals = bf_entry_values(m.entry, &lays[m.li]);
            let mut planes = vec![vec![0u32; size]; cls.w];
            let mut rem = vec![0u32; size];
            for r in 0..cls.rows {
                for c in 0..cls.cols {
                    let code = vals[r * cls.cols + c] + m.offset;
                    let x = r * cls.cols_pad + c;
                    for (k, plane) in planes.iter_mut().enumerate() {
                        plane[x] = ((code >> k) & 1) as u32;
                    }
                    rem[x] = code as u32;
                }
            }
            (planes, rem)
        })
        .collect()
}

/// Draw the class's O-4 mask (Masked mode) and lay its coefficients out as
/// the committed tensor values.
fn gg_draw_class_mask(
    zq: &ring::Zq,
    ext: &ring::zc_range::SubExt,
    cls: &GgClass,
    cd: &mut GgClassData,
    rng: &mut ring::ProverRng,
) {
    let n_tot = cls.n_log2 + ring::zc_range::zc_agg_axis(cls.members.len());
    let mask = ring::zc_range::ZcAggMask::draw(ext, rng, n_tot, 4);
    let flat = mask.flat();
    let mut vals = vec![0i64; bk_pad_to(flat.len(), 8) * ring::kfield::K_DEG];
    for (r, e) in flat.iter().enumerate() {
        let k = ext.to_k(e);
        for c in 0..ring::kfield::K_DEG {
            vals[r * ring::kfield::K_DEG + c] = zq.center(k[c]);
        }
    }
    cd.mask = Some(mask);
    cd.mask_vals = vals;
}

/// The two mask-opening claims (Masked mode, shared by prover and
/// verifier): the served hypersum G = 2^n a0 + 2^(n-1) sum_t u_t(1) and
/// the served final g_m(x*) = a0 + sum_t sum_d coeff[t][d] x*_t^(d+1),
/// both LINEAR functionals of the committed mask coefficients — ground by
/// the act opening (the bk mask_claims idiom carried to the aggregate).
fn gg_mask_claims(
    kf: &ring::kfield::KField,
    ext: &ring::zc_range::SubExt,
    cls: &GgClass,
    proof: &ring::zc_range::ZcAggProof,
    point: &[ring::zc_range::EElem],
    claims: &mut Vec<BkClaim>,
) {
    use std::rc::Rc;
    let ypow = bk_ypow_col(kf);
    let one = kf.one();
    let n_tot = cls.n_log2 + ring::zc_range::zc_agg_axis(cls.members.len());
    let deg = 4usize;
    let n_rows = bk_pad_to(1 + n_tot * deg, 8);
    let q = ext.q as u128;
    let p_full = kf.embed(((1u128 << n_tot) % q) as u64);
    let p_half = kf.embed(((1u128 << (n_tot - 1)) % q) as u64);
    let mut hrow = vec![kf.zero(); n_rows];
    hrow[0] = p_full;
    for r in hrow.iter_mut().take(1 + n_tot * deg).skip(1) {
        *r = p_half.clone();
    }
    claims.push(BkClaim {
        in_weight: false,
        value: ext.to_k(proof.mask_hyper.as_ref().expect("masked proof")),
        parts: vec![(cls.ti_mask, one.clone(), Rc::new(hrow), ypow.clone())],
    });
    let mut frow = vec![kf.zero(); n_rows];
    frow[0] = kf.one();
    for t in 0..n_tot {
        let mut p = point[t].clone();
        for d in 0..deg {
            frow[1 + t * deg + d] = ext.to_k(&p);
            p = ext.mul(&p, &point[t]);
        }
    }
    claims.push(BkClaim {
        in_weight: false,
        value: ext.to_k(proof.mask_final.as_ref().expect("masked proof")),
        parts: vec![(cls.ti_mask, one, Rc::new(frow), ypow)],
    });
}

fn gg_build_class_data(sp: &BkPairSpec, cls: &GgClass, lays: &[BfLayer]) -> GgClassData {
    // [UPERF3-RR] rung 3: one member per task over its disjoint slice of
    // the planes grid (values identical; this loop was ~1 s of the 12x128
    // Stage-A commit phase).
    use rayon::prelude::*;
    let per_member = cls.w * cls.rows * cls.cols_pad;
    let mut planes_vals = vec![0i64; cls.members.len() * per_member];
    planes_vals.par_chunks_mut(per_member).zip(cls.members.par_iter()).for_each(|(slot, &mi)| {
        let m = &sp.members[mi];
        let vals = bf_entry_values(m.entry, &lays[m.li]);
        assert_eq!(vals.len(), cls.rows * cls.cols);
        for r in 0..cls.rows {
            for c in 0..cls.cols {
                let code = vals[r * cls.cols + c] + m.offset;
                assert!(code >= 0 && (code as u128) < (1u128 << cls.w), "honest range fact");
                for k in 0..cls.w {
                    slot[(k * cls.rows + r) * cls.cols_pad + c] = (code >> k) & 1;
                }
            }
        }
    });
    GgClassData { planes_vals, mask: None, mask_vals: Vec::new() }
}

/// The range-class claim builder (shared verbatim by prover and verifier):
/// from the aggregate's stacked claims at r_col = point[..n_log2], push (i)
/// per (column, plane) the planes-tensor MLE claim (block row kernel x
/// eq_lo) and (ii) per column the MEMBER-tensor claim value
/// to_k(cc[i][w]) - offset * S_eq (the strided-rem <-> member-grid link;
/// S_eq = sum of eq over the real positions). Every value is grounded by
/// the act opening.
#[allow(clippy::too_many_arguments)]
fn gg_zc_claims(
    kf: &ring::kfield::KField,
    ext: &ring::zc_range::SubExt,
    reg: &BkRegistry,
    sp: &BkPairSpec,
    cls: &GgClass,
    proof: &ring::zc_range::ZcAggProof,
    point: &[ring::zc_range::EElem],
    claims: &mut Vec<BkClaim>,
) {
    use ring::gkr::eq_table;
    use std::rc::Rc;
    let zq = &kf.zq;
    let one = kf.one();
    let r_k: Vec<ring::kfield::KElem> = point[..cls.n_log2].iter().map(|e| ext.to_k(e)).collect();
    let lcp = cls.cols_pad.trailing_zeros() as usize;
    let lr = cls.rows.trailing_zeros() as usize;
    assert_eq!(lcp + lr, cls.n_log2);
    let eq_lo = Rc::new(eq_table(kf, &r_k[..lcp]));
    let eq_hi = eq_table(kf, &r_k[lcp..]);
    let rows_tot = cls.members.len() * cls.w * cls.rows;
    for (i, &mi) in cls.members.iter().enumerate() {
        for k in 0..cls.w {
            let mut row = vec![kf.zero(); rows_tot];
            row[(i * cls.w + k) * cls.rows..(i * cls.w + k + 1) * cls.rows].clone_from_slice(&eq_hi);
            claims.push(BkClaim {
                in_weight: false,
                value: ext.to_k(&proof.col_claims[i][k]),
                parts: vec![(cls.ti, one.clone(), Rc::new(row), eq_lo.clone())],
            });
        }
        let m = &sp.members[mi];
        let (_, ti_mem) = reg.map[m.li][m.entry];
        let eq_lo_trunc = Rc::new(eq_lo[..cls.cols].to_vec());
        let hi_sum = eq_hi.iter().fold(kf.zero(), |a, e| kf.add(&a, e));
        let lo_sum = eq_lo_trunc.iter().fold(kf.zero(), |a, e| kf.add(&a, e));
        let s_eq = kf.mul(&hi_sum, &lo_sum);
        let value = kf.sub(&ext.to_k(&proof.col_claims[i][cls.w]), &kf.scale(zq.to_mod(m.offset), &s_eq));
        claims.push(BkClaim {
            in_weight: false,
            value,
            parts: vec![(ti_mem, one.clone(), Rc::new(eq_hi.clone()), eq_lo_trunc)],
        });
    }
}

/// [UPERF3-RR] rung 3 — the BATCHED planes transport (opt-in:
/// ZK_RR_ZC_CLAIMS=batched). The m x w per-column plane claims of a class
/// recombine LINEARLY along the instance axis into w claims, T_k(x*) =
/// sum_i eq(r_inst, i) claim[i][k] — the recombination zc_agg_verify
/// already performs for the final identity — so the opening serves ONE
/// claim per plane per class: row kernel = the eq(r_inst, i)-weighted
/// block concatenation over the members (the same planes tensor `cls.ti`),
/// col kernel eq_lo unchanged. The m rem claims (per-member tensors) are
/// gg_zc_claims's verbatim. The SERVED values and their absorption
/// ("gg-zc-claims") are untouched; what changes is the opening's claim
/// structure (m x w + m -> w + m contribs per class) and hence the nu
/// count — a Stage-A transcript variant (selector-only path), measured
/// behind the knob and posted for the ruling; the default stays GG's form.
#[allow(clippy::too_many_arguments)]
fn gg_zc_claims_batched(
    kf: &ring::kfield::KField,
    ext: &ring::zc_range::SubExt,
    reg: &BkRegistry,
    sp: &BkPairSpec,
    cls: &GgClass,
    proof: &ring::zc_range::ZcAggProof,
    point: &[ring::zc_range::EElem],
    claims: &mut Vec<BkClaim>,
) {
    use ring::gkr::eq_table;
    use ring::zc_range::zc_agg_eq_bool;
    use std::rc::Rc;
    let zq = &kf.zq;
    let one = kf.one();
    let r_k: Vec<ring::kfield::KElem> = point[..cls.n_log2].iter().map(|e| ext.to_k(e)).collect();
    let lcp = cls.cols_pad.trailing_zeros() as usize;
    let lr = cls.rows.trailing_zeros() as usize;
    assert_eq!(lcp + lr, cls.n_log2);
    let eq_lo = Rc::new(eq_table(kf, &r_k[..lcp]));
    let eq_hi = eq_table(kf, &r_k[lcp..]);
    let m = cls.members.len();
    let r_inst = &point[cls.n_log2..];
    let wts: Vec<ring::kfield::KElem> = (0..m).map(|i| ext.to_k(&zc_agg_eq_bool(ext, r_inst, i))).collect();
    let rows_tot = m * cls.w * cls.rows;
    for k in 0..cls.w {
        let mut row = vec![kf.zero(); rows_tot];
        let mut value = kf.zero();
        for i in 0..m {
            let base = (i * cls.w + k) * cls.rows;
            for r in 0..cls.rows {
                row[base + r] = kf.mul(&wts[i], &eq_hi[r]);
            }
            value = kf.add(&value, &kf.mul(&wts[i], &ext.to_k(&proof.col_claims[i][k])));
        }
        claims.push(BkClaim { in_weight: false, value, parts: vec![(cls.ti, one.clone(), Rc::new(row), eq_lo.clone())] });
    }
    for (i, &mi) in cls.members.iter().enumerate() {
        let mm = &sp.members[mi];
        let (_, ti_mem) = reg.map[mm.li][mm.entry];
        let eq_lo_trunc = Rc::new(eq_lo[..cls.cols].to_vec());
        let hi_sum = eq_hi.iter().fold(kf.zero(), |a, e| kf.add(&a, e));
        let lo_sum = eq_lo_trunc.iter().fold(kf.zero(), |a, e| kf.add(&a, e));
        let s_eq = kf.mul(&hi_sum, &lo_sum);
        let value = kf.sub(&ext.to_k(&proof.col_claims[i][cls.w]), &kf.scale(zq.to_mod(mm.offset), &s_eq));
        claims.push(BkClaim {
            in_weight: false,
            value,
            parts: vec![(ti_mem, one.clone(), Rc::new(eq_hi.clone()), eq_lo_trunc)],
        });
    }
}

/// [UPERF3-RR] the transport knob (read once): ZK_RR_ZC_CLAIMS=batched.
fn rr_zc_claims_batched() -> bool {
    static V: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *V.get_or_init(|| std::env::var("ZK_RR_ZC_CLAIMS").map(|v| v == "batched").unwrap_or(false))
}

/// [UPERF3-RR] the zc claim transport, selected by the knob (prover and
/// verifier call the same function — the structure is shared).
#[allow(clippy::too_many_arguments)]
fn gg_zc_claims_sel(
    kf: &ring::kfield::KField,
    ext: &ring::zc_range::SubExt,
    reg: &BkRegistry,
    sp: &BkPairSpec,
    cls: &GgClass,
    proof: &ring::zc_range::ZcAggProof,
    point: &[ring::zc_range::EElem],
    claims: &mut Vec<BkClaim>,
) {
    if rr_zc_claims_batched() {
        gg_zc_claims_batched(kf, ext, reg, sp, cls, proof, point, claims)
    } else {
        gg_zc_claims(kf, ext, reg, sp, cls, proof, point, claims)
    }
}

/// The LogUp claim builder (Full mode, shared by prover and verifier): per
/// column j of a silu pair, (i) the h_sum claim and the h(x*) claim over
/// the act-h tensor block, pushed into `claims_h`; (ii) the key(x*) claim
/// over the member tensors (prim + Y-scaled image at the point's
/// (cols_pad | rows) split) and (iii) the table_sum claim over the
/// per-column m block, pushed into `claims` (act).
#[allow(clippy::too_many_arguments)]
fn gg_logup_claims(
    kf: &ring::kfield::KField,
    reg: &BkRegistry,
    sp: &BkPairSpec,
    plan: &GgPairPlan,
    gh_rows: usize,
    j: usize,
    alpha: &ring::kfield::KElem,
    table_k: &[ring::kfield::KElem],
    out: &ring::zc_range::LogupSumcheckOut,
    claims: &mut Vec<BkClaim>,
    claims_h: &mut Vec<(ring::kfield::KElem, Vec<(usize, ring::kfield::KElem, std::rc::Rc<Vec<ring::kfield::KElem>>, std::rc::Rc<Vec<ring::kfield::KElem>>)>)>,
) {
    use ring::gkr::eq_table;
    use std::rc::Rc;
    let one = kf.one();
    let (ti_m, ti_h, n_log2) = plan.logup.expect("logup plan");
    let n_el = 1usize << n_log2;
    let ypow = bk_ypow_col(kf);
    // (i) act-h claims.
    let mut ones_row = vec![kf.zero(); gh_rows];
    ones_row[j * n_el..(j + 1) * n_el].fill(kf.one());
    claims_h.push((out.h_sum.clone(), vec![(ti_h, one.clone(), Rc::new(ones_row), ypow.clone())]));
    let eq_pt = eq_table(kf, &out.point);
    let mut h_row = vec![kf.zero(); gh_rows];
    h_row[j * n_el..(j + 1) * n_el].clone_from_slice(&eq_pt);
    claims_h.push((out.h_at_point.clone(), vec![(ti_h, one.clone(), Rc::new(h_row), ypow.clone())]));
    // (ii) the key claim over the member tensors.
    let m = &sp.members[j];
    let lcp = m.shape.cols_pad().trailing_zeros() as usize;
    let eq_lo = Rc::new(eq_table(kf, &out.point[..lcp]));
    let eq_hi = Rc::new(eq_table(kf, &out.point[lcp..]));
    let (_, ti_prim) = reg.map[m.li][m.entry];
    let (_, ti_img) = reg.map[m.li][m.pair_entry.expect("silu image")];
    let y_one = ring::lookup::mul_y(kf, &kf.one());
    claims.push(BkClaim {
        in_weight: false,
        value: out.key_at_point.clone(),
        parts: vec![
            (ti_prim, one.clone(), eq_hi.clone(), eq_lo.clone()),
            (ti_img, y_one, eq_hi, eq_lo),
        ],
    });
    // (iii) the table_sum claim over the per-column m block.
    let m_cols = reg.ga.tensors[ti_m].cols;
    let mut m_col = vec![kf.zero(); m_cols];
    for (row_j, t_row) in table_k.iter().enumerate() {
        m_col[j * sp.t_rows + row_j] = kf.inv(&kf.sub(alpha, t_row));
    }
    claims.push(BkClaim {
        in_weight: false,
        value: out.table_sum.clone(),
        parts: vec![(ti_m, one.clone(), Rc::new(vec![kf.one()]), Rc::new(m_col))],
    });
}

/// The full act-group digit witness under the selector: pass tensors, then
/// per pair its Stage-A aux values in registry order.
fn gg_witness_act(
    reg: &BkRegistry,
    lays: &[BfLayer],
    specs: &[BkPairSpec],
    plans: &[GgPairPlan],
    bk_aux: &[Option<BkAuxMat>],
    class_data: &[Vec<GgClassData>],
    m_vals: &[Option<Vec<i64>>],
    ss_m: &[Vec<Vec<i64>>],
) -> ring::eval_proof::DigitCols {
    // [UPERF3-OO] BF entries per-tensor through the guard (same order as
    // the old slice vector); the aux/plane extras stay borrowed slices.
    let mut srcs: Vec<(usize, usize)> = Vec::with_capacity(reg.ga.tensors.len());
    for (li, _lay) in lays.iter().enumerate() {
        for e in 0..BF_ENTRIES.len() {
            let (w, _) = reg.map[li][e];
            if !w {
                srcs.push((li, e));
            }
        }
    }
    let mut extra: Vec<&[i64]> = Vec::new();
    for (pi, _sp) in specs.iter().enumerate() {
        if let Some(a) = &bk_aux[pi] {
            extra.push(&a.vals_m);
            extra.push(&a.vals_bl);
            extra.push(&a.vals_wm);
            extra.push(&a.vals_tm);
        } else if plans[pi].logup.is_some() {
            extra.push(m_vals[pi].as_ref().expect("logup m values"));
        } else {
            // [UPERF3-SS] the routed members' multiplicity tensors sit
            // BEFORE the pair's planes tensors in the registry.
            for (ri, _) in plans[pi].ss_routes.iter().enumerate() {
                extra.push(&ss_m[pi][ri]);
            }
            for cd in &class_data[pi] {
                extra.push(&cd.planes_vals);
                if !cd.mask_vals.is_empty() {
                    extra.push(&cd.mask_vals);
                }
            }
        }
    }
    let n_bf = srcs.len();
    agg_digit_witness_cols_src(&reg.ga, &|ti| {
        if ti < n_bf {
            let (li, e) = srcs[ti];
            bf_entry_values(e, &lays[li])
        } else {
            BfVals::B(extra[ti - n_bf])
        }
    })
}

/// One silu pair's Full-mode prover material (alpha-dependent; built after
/// the alphas are drawn, before u_0(T_h)).
struct GgLogupMat {
    keys: Vec<Vec<ring::kfield::KElem>>,
    row_of: Vec<Vec<Option<usize>>>,
    mult: Vec<Vec<u64>>,
    table_k: Vec<ring::kfield::KElem>,
    h_vals: Vec<i64>,
}

/// The shipped Stage-A objects per pair (the wire face).
enum GgShip {
    Descent(BkPairTranscript),
    Logup(Vec<ring::zc_range::LogupSumcheckOut>),
    Zc(Vec<ring::zc_range::ZcAggProof>),
    /// [UPERF3-SS] the SiLU pair under the committed-h routing (FullSs).
    SsLookup(Vec<ring::stage_a::full::LookupOut>),
}

/// [UPERF3-GG] rung 3/4 — the composed pass under the selector. Returns
/// accept.
fn uperf_a_gg_pass(layers_n: usize, t: usize, mode: GgMode, with_oracle: bool, tamper: GgTamper) -> bool {
    use ring::descent_fold::{aligned_witness_tree, neutral_tree};
    use ring::fold::{
        expand_layer_table, ixf_layout, ixf_sumcheck_prove_kind, ixf_sumcheck_verify,
        matmul_degree_schedule, zerocheck_degree_schedule, IxfCombine,
    };
    use ring::gkr::{eq_eval, eq_table, root_cross_check};
    use ring::gkr_masked::{blinded_table_tree, masked_gkr_prove, masked_gkr_verify, zero_masks};
    use ring::kfield::{KElem, KField};
    use ring::lookup::{fuse_pair, silu_v2_member, silu_v2_rows};
    use ring::pass_agg::{ClaimContrib, GroupClaims};
    use ring::stage_a::clog2;
    use ring::sumcheck::LkpTranscript;
    use ring::zc_range::{logup_sumcheck_prove, logup_sumcheck_verify, zc_agg_prove, zc_agg_verify, SubExt, ZcAggInstance, ZcRangeInstance};
    use std::collections::HashMap;
    use std::rc::Rc;
    use ring::ct_engine::prof; // [UPERF3-RR]
    let mode_name = match mode {
        GgMode::Full => "full",
        GgMode::Masked => "masked",
        GgMode::Range => "range",
        GgMode::FullSs(_) => "full-ss",
    };
    let ss_cfg = match mode {
        GgMode::FullSs(c) => Some(c),
        _ => None,
    };
    if let Some(c) = ss_cfg {
        println!("[UPERF3-SS] full-mode routing: {c:?}");
    }
    let tamper_name = match tamper {
        GgTamper::None => "",
        GgTamper::MaskCommit => " TAMPER=mask-commit",
        GgTamper::MaskServed => " TAMPER=mask-served",
        GgTamper::Claim => " TAMPER=claim",
        GgTamper::Round => " TAMPER=round",
    };
    assert!(tamper == GgTamper::None || mode == GgMode::Masked, "tamper legs run on the masked mode");
    println!(
        "[UPERF3-GG] STAGE-A composed pass: {layers_n} layers, T = {t}, mode {mode_name}{tamper_name} [WSL-BOX NOISY-SHARED]"
    );
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let ext = SubExt::new(&kf, 4);
    let zq = ctxr.zq;
    let q = zq.q;
    let il = ixf_layout(layers_n);
    let lambda = il.lambda;
    let lr = t.trailing_zeros() as usize;
    let mut accept = true;
    let mut first_fail: Option<String> = None;
    let mut fail = |acc: &mut bool, ff: &mut Option<String>, what: String| {
        *acc = false;
        if ff.is_none() {
            *ff = Some(what);
        }
    };

    // ---- Witness + registry + Stage-A committed aux. ----
    // [UPERF3-RR] the process-global phase timers (observation only; the
    // digest flag stays off) — the opening's per-function split.
    prof::enable(true, false);
    prof::reset();
    let t_commit = Instant::now();
    let lays: Vec<BfLayer> = (0..layers_n).map(|l| bf_load_layer(l, t, true)).collect();
    let specs = bk_pair_specs(&lays, t);
    let (mut reg, gh_opt, plans) = gg_build_groups(&lays, t, &specs, q, mode);
    let rr_t_groups = t_commit.elapsed().as_secs_f64(); // [UPERF3-RR] attribution
    reg.gw.begin_opening().expect("first weight-group opening (E-O2-BB)");
    reg.ga.begin_opening().expect("first act-group opening (E-O2-BB)");
    let mut gh = gh_opt;
    if let Some(g) = gh.as_mut() {
        g.begin_opening().expect("first act-h-group opening (E-O2-BB)");
    }
    let mut aux_rng = ring::ProverRng::from_test_seed(
        "uperf3-gg-session",
        &[(layers_n as u64).to_le_bytes(), (t as u64).to_le_bytes()].concat(),
    );
    let mut bk_aux: Vec<Option<BkAuxMat>> = Vec::with_capacity(specs.len());
    let mut class_data: Vec<Vec<GgClassData>> = Vec::with_capacity(specs.len());
    let mut m_vals: Vec<Option<Vec<i64>>> = Vec::with_capacity(specs.len());
    let mut ss_m: Vec<Vec<Vec<i64>>> = Vec::with_capacity(specs.len());
    let mut zc_mask_rng = ring::ProverRng::from_test_seed("uperf3-gg-zc-masks", &[0xA4]);
    for (pi, sp) in specs.iter().enumerate() {
        if sp.silu.is_some() && matches!(mode, GgMode::Range | GgMode::Masked) {
            bk_aux.push(Some(bk_build_aux(sp, &lays, &reg, pi, &kf, &mut aux_rng)));
            class_data.push(Vec::new());
            m_vals.push(None);
        } else if sp.silu.is_some() {
            // Full: per-column multiplicities (alpha-independent, committed
            // in the act group).
            let (eg, ea) = sp.silu.unwrap();
            let (bytes, _) = silu_v2_member(eg, ea).expect("frozen member");
            let rows = silu_v2_rows(bytes);
            let idx: HashMap<(u64, u64), usize> =
                rows.iter().enumerate().map(|(j, &(v, s))| ((zq.to_mod(v), zq.to_mod(s)), j)).collect();
            let (ti_m, _, _) = plans[pi].logup.unwrap();
            let m_cols = reg.ga.tensors[ti_m].cols;
            let mut mv = vec![0i64; m_cols];
            for (j, m) in sp.members.iter().enumerate() {
                let prim = bf_entry_values(m.entry, &lays[m.li]);
                let img = bf_entry_values(m.pair_entry.unwrap(), &lays[m.li]);
                for (x, y) in prim.iter().zip(img.iter()) {
                    if let Some(&r) = idx.get(&(zq.to_mod(*x), zq.to_mod(*y))) {
                        mv[j * sp.t_rows + r] += 1;
                    }
                }
            }
            bk_aux.push(None);
            class_data.push(Vec::new());
            m_vals.push(Some(mv));
        } else {
            let mut cds: Vec<GgClassData> =
                plans[pi].classes.iter().map(|c| gg_build_class_data(sp, c, &lays)).collect();
            if mode == GgMode::Masked {
                for (ci, cls) in plans[pi].classes.iter().enumerate() {
                    gg_draw_class_mask(&zq, &ext, cls, &mut cds[ci], &mut zc_mask_rng);
                }
            }
            bk_aux.push(None);
            class_data.push(cds);
            m_vals.push(None);
        }
        // [UPERF3-SS] the routed members' multiplicities (alpha-independent,
        // committed in the act group before any challenge).
        let mut sm: Vec<Vec<i64>> = Vec::new();
        for r in &plans[pi].ss_routes {
            let m = &sp.members[r.mi];
            let vals = bf_entry_values(m.entry, &lays[m.li]);
            let col = ring::stage_a::full::identity_lookup_col(
                &kf, &vals, m.offset, m.shape.rows, m.shape.cols, m.shape.cols_pad(), sp.t_rows,
            );
            let mut mv = vec![0i64; reg.ga.tensors[r.ti_m].cols];
            for (j, &c) in col.mult.iter().enumerate() {
                mv[j] = c as i64;
            }
            sm.push(mv);
        }
        ss_m.push(sm);
    }
    if tamper == GgTamper::MaskCommit {
        // Flip one COMMITTED mask coefficient value; the prover proves
        // with the TRUE mask (ct rows forced below) — the BD WrongC shape.
        let cd = class_data
            .iter_mut()
            .find(|cds| !cds.is_empty())
            .and_then(|cds| cds.first_mut())
            .expect("a range class exists");
        assert!(!cd.mask_vals.is_empty(), "masked mode has committed mask values");
        cd.mask_vals[0] += 1;
    }
    let sched_w = ring::eval_proof::plan_schedule(reg.gw.n_digit_rings, 1, q, None);
    let sched_a = ring::eval_proof::plan_schedule(reg.ga.n_digit_rings, 2, q, None);
    let sched_h = gh.as_ref().map(|g| ring::eval_proof::plan_schedule(g.n_digit_rings, 2, q, None));
    let mut w0_w = bk_witness_weight(&reg, &lays);
    let mut w0_a = gg_witness_act(&reg, &lays, &specs, &plans, &bk_aux, &class_data, &m_vals, &ss_m);
    let rr_t_wit = t_commit.elapsed().as_secs_f64(); // [UPERF3-RR]
    // The committed planes now live in the digit witness — free the i64
    // staging vectors (~6 GB at 12x512) before the pre-commit peak.
    for cds in class_data.iter_mut() {
        for cd in cds.iter_mut() {
            cd.planes_vals = Vec::new();
        }
    }
    uf_trim();
    let crs_seed = 0xB6_C0DEu64;
    let pre_w = bg_precommit(&ctxr, &reg.gw, &sched_w, &mut w0_w, crs_seed);
    let rr_t_pre_w = t_commit.elapsed().as_secs_f64(); // [UPERF3-RR]
    let pre_a = bg_precommit(&ctxr, &reg.ga, &sched_a, &mut w0_a, crs_seed);
    let rr_t_pre_a = t_commit.elapsed().as_secs_f64(); // [UPERF3-RR]

    // ---- Statement + h0 (all inventories bound; u_0(T_h) rides the
    // ---- rolling transcript in Full mode). ----
    let u0_digests: Vec<Vec<u8>> = [&pre_w.u0, &pre_a.u0]
        .iter()
        .map(|u| uk8_sha(&[b"gg-u0", &polys_bytes(u)]).to_vec())
        .collect();
    let commit_digests: Vec<Vec<Vec<u8>>> = (0..layers_n)
        .map(|li| {
            (0..BF_ENTRIES.len())
                .map(|e| {
                    let (w, _) = reg.map[li][e];
                    uk8_sha(&[
                        b"gg-entry",
                        &u0_digests[if w { 0 } else { 1 }],
                        &(li as u64).to_le_bytes(),
                        &(e as u64).to_le_bytes(),
                    ])
                    .to_vec()
                })
                .collect()
        })
        .collect();
    let mut statement = m125_build_statement(t, &lays, &commit_digests, b"gg-stage-a-crs-v1");
    statement.mode = Some(manifest::ModeDecl { mode: manifest::MODE_P0, private_entries: Vec::new() });
    let ctx_digest = match statement.validate() {
        Ok(()) => statement.digest().expect("prover statement digests"),
        Err(e) => panic!("prover statement invalid: {e}"),
    };
    let bytes_statement = statement.encode().len();
    let map_bytes = gg_map_bytes(&reg, gh.as_ref());
    let h0 = uk8_sha(&[
        b"uperf3-gg-h0",
        &ctx_digest,
        &map_bytes,
        &polys_bytes(&pre_w.u0),
        &polys_bytes(&pre_a.u0),
    ]);
    let commit_s = t_commit.elapsed().as_secs_f64();

    // ---- PROVER. ----
    let t_prove = Instant::now();
    let mut tr = LkpTranscript::new("uperf3-gg-pass", &h0);
    let product3 = |kf: &KField, v: &[KElem]| kf.mul(&kf.mul(&v[0], &v[1]), &v[2]);
    let had_comb = |kf: &KField, v: &[KElem]| kf.mul(&v[0], &kf.sub(&kf.mul(&v[1], &v[2]), &v[3]));
    let rq_comb = |kf: &KField, v: &[KElem]| {
        kf.mul(&v[0], &kf.sub(&kf.sub(&v[1], &kf.mul(&v[4], &v[2])), &v[3]))
    };
    let mut claims: Vec<BkClaim> = Vec::new();
    let mut claims_h: Vec<(KElem, Vec<(usize, KElem, Rc<Vec<KElem>>, Rc<Vec<KElem>>)>)> = Vec::new();
    let mut v_cs: Vec<KElem> = Vec::new();
    let mut sc_proofs: Vec<ring::sumcheck::SumcheckProof> = Vec::new();
    let mut inst_kel = 0usize;
    let to_parts = |parts: Vec<(usize, usize, KElem, Rc<Vec<KElem>>, Rc<Vec<KElem>>)>,
                    reg: &BkRegistry|
     -> Vec<(usize, KElem, Rc<Vec<KElem>>, Rc<Vec<KElem>>)> {
        parts
            .into_iter()
            .map(|(li, e, s, r, c)| {
                let (_, ti) = reg.map[li][e];
                (ti, s, r, c)
            })
            .collect()
    };
    for (name, a_e, b_e, c_e) in BG_MM_INSTS {
        let (_ar, a_cols) = bf_entry_shape(a_e, t);
        let (_br, b_cols) = bf_entry_shape(b_e, t);
        let (inner, cols) = (a_cols, b_cols);
        let lk = usize::BITS as usize - (inner - 1).leading_zeros() as usize;
        let lc = usize::BITS as usize - (cols - 1).leading_zeros() as usize;
        let nk = 1usize << lk;
        let r_l: Vec<KElem> = (0..lambda).map(|_| tr.challenge_k(&kf)).collect();
        let rx: Vec<KElem> = (0..lr).map(|_| tr.challenge_k(&kf)).collect();
        let ry: Vec<KElem> = (0..lc).map(|_| tr.challenge_k(&kf)).collect();
        let eq_rl = eq_table(&kf, &r_l);
        let eq_rx = Rc::new(eq_table(&kf, &rx));
        let eq_ry = Rc::new(eq_table(&kf, &ry));
        let (ta, tb) = bg_mm_tables(&kf, &lays, a_e, b_e, t, il.slots, nk, &eq_rx, &eq_ry);
        let v_c = {
            let mut s = kf.zero();
            for (li, lay) in lays.iter().enumerate() {
                let m = bg_mle(&kf, &bf_entry_values(c_e, lay), cols, &eq_rx, &eq_ry);
                s = kf.add(&s, &kf.mul(&eq_rl[li], &m));
            }
            s
        };
        tr.absorb_k(&kf, &format!("gg-claim-{name}"), std::slice::from_ref(&v_c));
        let eq_exp = expand_layer_table(&kf, &eq_rl, nk);
        let sched = matmul_degree_schedule(lk, lambda);
        let (scp, point) =
            ixf_sumcheck_prove_kind(&kf, vec![eq_exp, ta, tb], &sched, IxfCombine::Prod3, &mut tr);
        tr.absorb_k(&kf, &format!("gg-final-{name}"), &scp.final_evals);
        inst_kel += 1 + scp.rounds.iter().map(|r| r.len()).sum::<usize>() + scp.final_evals.len();
        let k_star = &point[..lk];
        let l_star = &point[lk..];
        let eq_ks = Rc::new(eq_table(&kf, k_star));
        let eq_ls = eq_table(&kf, l_star);
        claims.push(BkClaim {
            in_weight: false,
            value: scp.final_evals[1].clone(),
            parts: to_parts(
                (0..layers_n).map(|li| (li, a_e, eq_ls[li].clone(), eq_rx.clone(), eq_ks.clone())).collect(),
                &reg,
            ),
        });
        claims.push(BkClaim {
            in_weight: true,
            value: scp.final_evals[2].clone(),
            parts: to_parts(
                (0..layers_n).map(|li| (li, b_e, eq_ls[li].clone(), eq_ks.clone(), eq_ry.clone())).collect(),
                &reg,
            ),
        });
        claims.push(BkClaim {
            in_weight: false,
            value: v_c.clone(),
            parts: to_parts(
                (0..layers_n).map(|li| (li, c_e, eq_rl[li].clone(), eq_rx.clone(), eq_ry.clone())).collect(),
                &reg,
            ),
        });
        v_cs.push(v_c);
        sc_proofs.push(scp);
    }
    let zc_insts: Vec<(&'static str, usize, usize, usize, bool)> = {
        let mut v = vec![("had", 7usize, 10usize, 11usize, false)];
        for (name, acc_e, y_e, r_e) in BG_RQ_INSTS {
            v.push((name, acc_e, y_e, r_e, true));
        }
        v
    };
    let ixf_pool_scope = ring::fold::IxfPoolScope::open();
    for (name, e1, e2, e3, is_rq) in &zc_insts {
        let shape_e = if *is_rq { *e1 } else { *e3 };
        let (_rows, cols_real) = bf_entry_shape(shape_e, t);
        let lcp = usize::BITS as usize - (cols_real - 1).leading_zeros() as usize;
        let cols_pad = 1usize << lcp;
        let n_pos = lr + lcp;
        let r_q: Vec<KElem> = (0..n_pos + lambda).map(|_| tr.challenge_k(&kf)).collect();
        let zero = kf.zero();
        tr.absorb_k(&kf, &format!("gg-claim-{name}"), std::slice::from_ref(&zero));
        let sched = if *is_rq {
            let mut d = vec![2usize; n_pos];
            d.extend(std::iter::repeat_n(3usize, lambda));
            d
        } else {
            zerocheck_degree_schedule(n_pos, lambda)
        };
        let sh_layer: Vec<KElem> = if *is_rq {
            (0..il.slots)
                .map(|li| {
                    if li < layers_n {
                        kf.scale(zq.to_mod(1i64 << bg_rq_shift(name, &lays[li])), &kf.one())
                    } else {
                        kf.zero()
                    }
                })
                .collect()
        } else {
            Vec::new()
        };
        let (scp, point) = bg_zc_prove(
            &kf, &lays, [*e1, *e2, *e3], *is_rq, &sh_layer, &r_q, il.slots, n_pos, cols_real, cols_pad,
            &sched, &mut tr,
        );
        tr.absorb_k(&kf, &format!("gg-final-{name}"), &scp.final_evals);
        inst_kel += 1 + scp.rounds.iter().map(|r| r.len()).sum::<usize>() + scp.final_evals.len();
        let eq_pc = Rc::new(eq_table(&kf, &point[..lcp]));
        let eq_pr = Rc::new(eq_table(&kf, &point[lcp..n_pos]));
        let eq_pl = eq_table(&kf, &point[n_pos..]);
        for (fe, e) in [(1usize, *e1), (2, *e2), (3, *e3)] {
            claims.push(BkClaim {
                in_weight: false,
                value: scp.final_evals[fe].clone(),
                parts: to_parts(
                    (0..layers_n).map(|li| (li, e, eq_pl[li].clone(), eq_pr.clone(), eq_pc.clone())).collect(),
                    &reg,
                ),
            });
        }
        sc_proofs.push(scp);
    }
    drop(ixf_pool_scope);

    // [UPERF3-RR] attribution timers (round 10, rung 1): the Stage-A path
    // split per function so the device port targets the measured top.
    let rr_t_claim = t_prove.elapsed().as_secs_f64();
    let (mut rr_s_desc, mut rr_s_logup, mut rr_s_tabs, mut rr_s_zc, mut rr_s_zc_claims) = (0f64, 0f64, 0f64, 0f64, 0f64);
    let (mut rr_s_zc_eq, mut rr_s_zc_round, mut rr_s_zc_fold) = (0f64, 0f64, 0f64);
    let (mut rr_zc_rounds, mut rr_zc_macs) = (0usize, 0u64);
    let mut rr_zc_lines: Vec<String> = Vec::new();
    // ---- STAGE-A PHASE (replacing bk's descent phase). ----
    // Full mode phase A/B: silu alphas, then h + u_0(T_h) before any rho.
    let mut silu_alphas: Vec<Option<KElem>> = vec![None; specs.len()];
    let mut logup_mat: Vec<Option<GgLogupMat>> = (0..specs.len()).map(|_| None).collect();
    let mut w0_h = ring::eval_proof::DigitCols::zeros(0);
    let mut pre_h = None;
    let mut u0_h_bytes: Vec<u8> = Vec::new();
    if mode == GgMode::Full {
        for (pi, sp) in specs.iter().enumerate() {
            if sp.silu.is_some() {
                silu_alphas[pi] = Some(tr.challenge_k(&kf));
            }
        }
        let mut h_tensor_vals: Vec<Vec<i64>> = Vec::new();
        for (pi, sp) in specs.iter().enumerate() {
            let Some(alpha) = &silu_alphas[pi] else { continue };
            let (eg, ea) = sp.silu.unwrap();
            let (bytes, _) = silu_v2_member(eg, ea).expect("frozen member");
            let rows = silu_v2_rows(bytes);
            let idx: HashMap<(u64, u64), usize> =
                rows.iter().enumerate().map(|(j, &(v, s))| ((zq.to_mod(v), zq.to_mod(s)), j)).collect();
            let table_k = sp.table_k(&kf);
            let inv_rows: Vec<KElem> = table_k.iter().map(|tk| kf.inv(&kf.sub(alpha, tk))).collect();
            let (_, _, n_log2) = plans[pi].logup.unwrap();
            let n_el = 1usize << n_log2;
            let mut keys = Vec::new();
            let mut row_of = Vec::new();
            let mut mult = Vec::new();
            let mut h_vals = vec![0i64; sp.members.len() * n_el * ring::kfield::K_DEG];
            for (j, m) in sp.members.iter().enumerate() {
                let prim = bf_entry_values(m.entry, &lays[m.li]);
                let img = bf_entry_values(m.pair_entry.unwrap(), &lays[m.li]);
                assert_eq!(prim.len(), n_el, "silu member hypercube exact");
                let mut kcol = Vec::with_capacity(n_el);
                let mut rcol = Vec::with_capacity(n_el);
                let mut mcol = vec![0u64; sp.t_rows];
                for (i, (x, y)) in prim.iter().zip(img.iter()).enumerate() {
                    let key = fuse_pair(&kf, zq.to_mod(*x), zq.to_mod(*y));
                    let r = idx.get(&(zq.to_mod(*x), zq.to_mod(*y))).copied();
                    let hv = match r {
                        Some(rj) => {
                            mcol[rj] += 1;
                            inv_rows[rj].clone()
                        }
                        None => kf.inv(&kf.sub(alpha, &key)),
                    };
                    for c in 0..ring::kfield::K_DEG {
                        h_vals[(j * n_el + i) * ring::kfield::K_DEG + c] = zq.center(hv[c]);
                    }
                    kcol.push(key);
                    rcol.push(r);
                }
                keys.push(kcol);
                row_of.push(rcol);
                mult.push(mcol.iter().map(|&c| c).collect());
            }
            logup_mat[pi] = Some(GgLogupMat { keys, row_of, mult, table_k, h_vals: h_vals.clone() });
            h_tensor_vals.push(h_vals);
        }
        let gh_ref = gh.as_ref().unwrap();
        let vals: Vec<&[i64]> = h_tensor_vals.iter().map(|v| v.as_slice()).collect();
        w0_h = agg_digit_witness_cols(gh_ref, &vals);
        let p = bg_precommit(&ctxr, gh_ref, sched_h.as_ref().unwrap(), &mut w0_h, crs_seed);
        u0_h_bytes = polys_bytes(&p.u0);
        tr.absorb("gg-u0h", &u0_h_bytes);
        pre_h = Some(p);
    }
    // [UPERF3-SS] FullSs phase A/B: one alpha per lookup-carrying pair in
    // spec order (the SiLU pairs, then any pair with a routed member), the
    // helpers at their kappa levels (ring/stage_a_full.rs), u_0(T_h)
    // absorbed before any rho — the F2 ordering kept.
    let mut ss_alphas: Vec<Option<KElem>> = vec![None; specs.len()];
    let mut ss_cols: Vec<Vec<ring::stage_a::full::LookupCol>> = (0..specs.len()).map(|_| Vec::new()).collect();
    let mut ss_hs: Vec<Vec<Vec<KElem>>> = (0..specs.len()).map(|_| Vec::new()).collect();
    let mut ss_route_cols: Vec<Vec<ring::stage_a::full::LookupCol>> = (0..specs.len()).map(|_| Vec::new()).collect();
    let mut ss_route_hs: Vec<Vec<Vec<KElem>>> = (0..specs.len()).map(|_| Vec::new()).collect();
    let mut ss_tables: Vec<Vec<KElem>> = (0..specs.len()).map(|_| Vec::new()).collect();
    let mut ss_secs_helper = 0.0f64;
    if ss_cfg.is_some() {
        use ring::stage_a::full::{helper_vals_i64, identity_lookup_col, lookup_helper, LookupCol};
        let _ = fuse_pair; // (the fused keys are built strided in stage_a_full)
        let t_h = Instant::now();
        for (pi, sp) in specs.iter().enumerate() {
            if sp.silu.is_some() || !plans[pi].ss_routes.is_empty() {
                ss_alphas[pi] = Some(tr.challenge_k(&kf));
            }
        }
        let mut h_tensor_vals: Vec<Vec<i64>> = Vec::new();
        for (pi, sp) in specs.iter().enumerate() {
            let Some(alpha) = &ss_alphas[pi] else { continue };
            ss_tables[pi] = sp.table_k(&kf);
            if sp.silu.is_some() {
                let (_, _, n_log2) = plans[pi].logup.unwrap();
                let kappa = plans[pi].ss_kappa;
                let n_el = 1usize << n_log2;
                let mut h_vals: Vec<i64> = Vec::with_capacity(sp.members.len() * (n_el >> kappa) * ring::kfield::K_DEG);
                for m in sp.members.iter() {
                    // Strided (shape-general) keys: pads carry the row-0 key.
                    // The column is built per member and DROPPED after its
                    // helper — only the helper (2^-kappa the size) is held
                    // across the commit; phase C rebuilds the keys per
                    // column (the keys diet: ~150 B per boxed K element).
                    let col: LookupCol = ss_silu_col(&kf, sp, m, &lays, &ss_tables[pi]);
                    assert_eq!(col.n_log2, n_log2);
                    let (h, _) = lookup_helper(&kf, &col, &ss_tables[pi], alpha, kappa);
                    h_vals.extend(helper_vals_i64(&kf, &h));
                    ss_hs[pi].push(h);
                }
                h_tensor_vals.push(h_vals);
            }
            for r in &plans[pi].ss_routes {
                let m = &sp.members[r.mi];
                let vals = bf_entry_values(m.entry, &lays[m.li]);
                let col = identity_lookup_col(
                    &kf, &vals, m.offset, m.shape.rows, m.shape.cols, m.shape.cols_pad(), sp.t_rows,
                );
                let (h, _) = lookup_helper(&kf, &col, &ss_tables[pi], alpha, r.kappa);
                h_tensor_vals.push(helper_vals_i64(&kf, &h));
                ss_route_hs[pi].push(h);
                ss_route_cols[pi].push(col);
            }
        }
        ss_secs_helper = t_h.elapsed().as_secs_f64();
        let gh_ref = gh.as_ref().unwrap();
        let vals: Vec<&[i64]> = h_tensor_vals.iter().map(|v| v.as_slice()).collect();
        w0_h = agg_digit_witness_cols(gh_ref, &vals);
        let p = bg_precommit(&ctxr, gh_ref, sched_h.as_ref().unwrap(), &mut w0_h, crs_seed);
        u0_h_bytes = polys_bytes(&p.u0);
        tr.absorb("gg-u0h", &u0_h_bytes);
        pre_h = Some(p);
        println!("  [UPERF3-SS] RSS high-water after the act-h commit (phase B): {:.0} MiB", uperf_a_peak_rss_mib());
    }
    let mut ss_ships: Vec<Vec<ring::stage_a::full::LookupOut>> = (0..specs.len()).map(|_| Vec::new()).collect();
    let mut ss_secs_prove = 0.0f64;
    // Phase C: per pair in spec order.
    let mut ships: Vec<GgShip> = Vec::new();
    let mut stage_a_bytes = 0usize;
    let ypow = bk_ypow_col(&kf);
    for (pi, sp) in specs.iter().enumerate() {
        if sp.silu.is_some() && matches!(mode, GgMode::Range | GgMode::Masked) {
            let rr_t0 = Instant::now();
            let plan = &sp.plan;
            let alpha = tr.challenge_k(&kf);
            let aux = bk_aux[pi].as_mut().unwrap();
            let mut wtrees: Vec<ring::gkr::FracTree> = Vec::with_capacity(plan.l);
            for i in 0..plan.n_real {
                let slots = bk_tree_slots(&kf, sp, &lays, i);
                let slot_refs: Vec<(ring::descent_fold::MemberShape, usize, &[KElem])> =
                    slots.iter().map(|(s, b, c)| (*s, *b, c.as_slice())).collect();
                wtrees.push(aligned_witness_tree(&kf, &alpha, &slot_refs, plan.depth, &aux.bl_w[i]));
            }
            for _ in plan.n_real..plan.l {
                wtrees.push(neutral_tree(&kf, plan.depth));
            }
            let masks_w = aux.masks_w.take().expect("witness masks drawn once");
            let (pw, endw) = masked_gkr_prove(&kf, &wtrees, masks_w, &mut tr);
            drop(wtrees);
            let tab_k = sp.table_k(&kf);
            let mut ttrees: Vec<ring::gkr::FracTree> = Vec::with_capacity(plan.l);
            for i in 0..plan.n_real {
                let m_k: Vec<KElem> = aux.m_counts[i].iter().map(|&c| kf.embed(zq.to_mod(c))).collect();
                ttrees.push(blinded_table_tree(&kf, &alpha, &tab_k, &m_k, sp.dt, &aux.bl_t[i]));
            }
            for _ in plan.n_real..plan.l {
                ttrees.push(neutral_tree(&kf, sp.dt));
            }
            let masks_t = aux.masks_t.take().expect("table masks drawn once");
            let (pt, endt) = masked_gkr_prove(&kf, &ttrees, masks_t, &mut tr);
            drop(ttrees);
            stage_a_bytes += (bk_proof_kel(&pw) + bk_proof_kel(&pt)) * 64;
            let tpx = BkPairTranscript { alpha, pw, endw, pt, endt };
            {
                let view = BkPairView {
                    alpha: &tpx.alpha,
                    pw: &tpx.pw,
                    endw: &tpx.endw,
                    pt: &tpx.pt,
                    endt: &tpx.endt,
                };
                bk_pair_claims(&kf, sp, &reg, pi, &view, &ypow, &mut claims);
            }
            ships.push(GgShip::Descent(tpx));
            rr_s_desc += rr_t0.elapsed().as_secs_f64();
        } else if sp.silu.is_some() && ss_cfg.is_some() {
            // [UPERF3-SS] the SiLU pair under the committed-h routing.
            let alpha = ss_alphas[pi].clone().unwrap();
            let kappa = plans[pi].ss_kappa;
            let (ti_m, ti_h, n_log2) = plans[pi].logup.unwrap();
            let gh_rows = gh.as_ref().unwrap().tensors[ti_h].rows;
            let mut outs = Vec::new();
            let t_p = Instant::now();
            for (j, m) in sp.members.iter().enumerate() {
                let rho: Vec<KElem> = (0..n_log2 - kappa).map(|_| tr.challenge_k(&kf)).collect();
                let col = ss_silu_col(&kf, sp, m, &lays, &ss_tables[pi]);
                let out = ring::stage_a::full::lookup_prove(
                    &kf, &col, &ss_tables[pi], &alpha, &rho, kappa, &ss_hs[pi][j], &mut tr,
                );
                drop(col);
                ss_absorb_served(&kf, &mut tr, &out);
                stage_a_bytes += ring::stage_a::full::lookup_wire_bytes(&out);
                ss_lookup_claims(
                    &kf, &reg, sp, m, ti_m, j, ti_h, gh_rows, j, &alpha, &ss_tables[pi], &out, &mut claims,
                    &mut claims_h,
                );
                outs.push(out);
            }
            ss_secs_prove += t_p.elapsed().as_secs_f64();
            ships.push(GgShip::SsLookup(outs));
        } else if sp.silu.is_some() {
            let rr_t0 = Instant::now();
            let alpha = silu_alphas[pi].clone().unwrap();
            let mat = logup_mat[pi].as_ref().unwrap();
            let (_, _, n_log2) = plans[pi].logup.unwrap();
            let gh_rows = gh.as_ref().unwrap().tensors[plans[pi].logup.unwrap().1].rows;
            let mut outs = Vec::new();
            for j in 0..sp.members.len() {
                let rho: Vec<KElem> = (0..n_log2).map(|_| tr.challenge_k(&kf)).collect();
                let out = logup_sumcheck_prove(
                    &kf, &mat.keys[j], &mat.row_of[j], &mat.table_k, &mat.mult[j], &alpha, &rho, &mut tr,
                );
                tr.absorb_k(&kf, "gg-lu-final", &out.proof.final_evals);
                tr.absorb_k(
                    &kf,
                    "gg-lu-served",
                    &[out.h_sum.clone(), out.table_sum.clone(), out.h_at_point.clone(), out.key_at_point.clone()],
                );
                stage_a_bytes +=
                    (out.proof.rounds.iter().map(|r| r.len()).sum::<usize>() + out.proof.final_evals.len() + 4) * 64;
                gg_logup_claims(&kf, &reg, sp, &plans[pi], gh_rows, j, &alpha, &mat.table_k, &out, &mut claims, &mut claims_h);
                outs.push(out);
            }
            ships.push(GgShip::Logup(outs));
            rr_s_logup += rr_t0.elapsed().as_secs_f64();
        } else {
            let mut proofs = Vec::new();
            for (ci, cls) in plans[pi].classes.iter().enumerate() {
                let cd = &class_data[pi][ci];
                // Transient per class: the u32 zc tables (dropped at the
                // end of the class — the memory the descent trees used to
                // hold is gone; this is the replacement's own residency).
                let rr_t0 = Instant::now();
                let cols_tabs = gg_build_class_tabs(sp, cls, &lays);
                let rr_c_tabs = rr_t0.elapsed().as_secs_f64();
                rr_s_tabs += rr_c_tabs;
                let cols_inst: Vec<ZcRangeInstance> = cols_tabs
                    .iter()
                    .map(|(p, r)| ZcRangeInstance { n_log2: cls.n_log2, e0: 1, planes: p, rem: r })
                    .collect();
                let inst = ZcAggInstance { n_log2: cls.n_log2, e0: 1, cols: cols_inst };
                let n_tot = cls.n_log2 + inst.a();
                let rho: Vec<_> = (0..n_tot).map(|_| ext.challenge(&kf, &mut tr)).collect();
                let betas: Vec<_> = (0..cls.w + 1).map(|_| ext.challenge(&kf, &mut tr)).collect();
                let rr_t1 = Instant::now();
                let (proof, point, stats) = if let Some(mask) = &cd.mask {
                    // O-4: the mask commitment binds via u_0(T_act) inside
                    // h0 (mask-then-fold — every challenge above descends
                    // from h0); the prover serves G + g_m(x*).
                    let (p, pt, st, _ev) =
                        ring::zc_range::zc_agg_prove_masked(&kf, &ext, &inst, &rho, &betas, Some(mask), &mut tr);
                    (p, pt, st)
                } else {
                    zc_agg_prove(&kf, &ext, &inst, &rho, &betas, &mut tr)
                };
                let rr_c_zc = rr_t1.elapsed().as_secs_f64();
                rr_s_zc += rr_c_zc;
                rr_s_zc_eq += stats.secs_eq;
                rr_s_zc_round += stats.secs_round;
                rr_s_zc_fold += stats.secs_fold;
                rr_zc_rounds += stats.rounds;
                rr_zc_macs += stats.macs_total();
                let mut flat: Vec<KElem> =
                    proof.col_claims.iter().flat_map(|cl| cl.iter().map(|e| ext.to_k(e))).collect();
                if let Some(mf) = &proof.mask_final {
                    flat.push(ext.to_k(mf));
                }
                tr.absorb_k(&kf, "gg-zc-claims", &flat);
                stage_a_bytes += stats.wire_bytes;
                let rr_t2 = Instant::now();
                gg_zc_claims_sel(&kf, &ext, &reg, sp, cls, &proof, &point, &mut claims);
                let rr_c_claims = rr_t2.elapsed().as_secs_f64();
                rr_s_zc_claims += rr_c_claims;
                rr_zc_lines.push(format!(
                    "zc {:<8} class {ci}: m {:>2} x 2^{:<2} w {:>2} (n_tot {:>2}): tabs {:.2}s | prove {:.2}s (eq {:.2} rounds {:.2} folds {:.2}; {} rounds, {:.2} G MACs) | claims {:.2}s",
                    sp.name(), cls.members.len(), cls.n_log2, cls.w, n_tot, rr_c_tabs, rr_c_zc, stats.secs_eq, stats.secs_round, stats.secs_fold, stats.rounds, stats.macs_total() as f64 / 1e9, rr_c_claims
                ));
                if cd.mask.is_some() {
                    gg_mask_claims(&kf, &ext, cls, &proof, &point, &mut claims);
                }
                proofs.push(proof);
            }
            ships.push(GgShip::Zc(proofs));
            // [UPERF3-SS] rung V1: the routed members, after the pair's
            // classes (transcript order shared with the verifier).
            for (ri, r) in plans[pi].ss_routes.iter().enumerate() {
                let alpha = ss_alphas[pi].clone().unwrap();
                let gh_rows = gh.as_ref().unwrap().tensors[r.ti_h].rows;
                let t_p = Instant::now();
                let rho: Vec<KElem> = (0..r.n_log2 - r.kappa).map(|_| tr.challenge_k(&kf)).collect();
                let out = ring::stage_a::full::lookup_prove(
                    &kf, &ss_route_cols[pi][ri], &ss_tables[pi], &alpha, &rho, r.kappa, &ss_route_hs[pi][ri], &mut tr,
                );
                ss_absorb_served(&kf, &mut tr, &out);
                stage_a_bytes += ring::stage_a::full::lookup_wire_bytes(&out);
                ss_lookup_claims(
                    &kf, &reg, sp, &sp.members[r.mi], r.ti_m, 0, r.ti_h, gh_rows, 0, &alpha, &ss_tables[pi], &out,
                    &mut claims, &mut claims_h,
                );
                ss_secs_prove += t_p.elapsed().as_secs_f64();
                // The differential's contract: every served value grounded
                // directly on the raw column (exact K equality).
                let col = &ss_route_cols[pi][ri];
                let leaves = 1usize << r.kappa;
                let keys_ok = (0..leaves)
                    .all(|b| ring::stage_a::full::key_at_point_direct(&kf, col, &out.point, r.kappa, b) == out.keys_at_point[b]);
                let h_ok = ring::stage_a::full::h_at_point_direct(&kf, &ss_route_hs[pi][ri], &out.point) == out.h_at_point;
                println!(
                    "  [UPERF3-SS] V1 route {} member (layer {}, {}) kappa {}: key_b(x*) direct == served {}/{} {}; h(x*) direct == served {}; h_sum == table_sum {}; helper rows {} (act-h rings {}) vs the planes it left ({} rings); sumcheck {:.2}s",
                    sp.name(),
                    sp.members[r.mi].li,
                    BF_ENTRIES[sp.members[r.mi].entry],
                    r.kappa,
                    (0..leaves).filter(|&b| ring::stage_a::full::key_at_point_direct(&kf, col, &out.point, r.kappa, b) == out.keys_at_point[b]).count(),
                    leaves,
                    if keys_ok { "OK" } else { "MISMATCH" },
                    if h_ok { "OK" } else { "MISMATCH" },
                    if out.h_sum == out.table_sum { "OK" } else { "MISMATCH" },
                    gh_rows,
                    gh.as_ref().unwrap().tensors[r.ti_h].n_digit_rings(),
                    ring::stage_a::full::planes_rings(1usize << r.n_log2, sp.t_rows.trailing_zeros() as usize),
                    out.secs_sumcheck,
                );
                assert!(keys_ok && h_ok, "V1 grounding must hold on the honest witness");
                ss_ships[pi].push(out);
            }
        }
        uf_trim(); // per-pair transient tables back to the OS
    }
    if ss_cfg.is_some() {
        ss_hs = Vec::new();
        println!("  [UPERF3-SS] RSS high-water after the Stage-A phase (phase C): {:.0} MiB", uperf_a_peak_rss_mib());
    }
    // [UPERF3-SS] tamper: flip the first routed column's served h_sum.
    if matches!(ss_cfg, Some(SsCfg { tamper_sum: true, .. })) {
        let out = ss_ships.iter_mut().find_map(|v| v.first_mut()).expect("a routed column exists");
        out.h_sum = kf.add(&out.h_sum, &kf.one());
    }
    let rr_t_stagea = t_prove.elapsed().as_secs_f64(); // [UPERF3-RR]
    // Rung-4 tamper injection on the SHIPPED objects (the prover's own
    // transcript/claims stay honest; the verifier consumes the flip).
    if matches!(tamper, GgTamper::Claim | GgTamper::Round | GgTamper::MaskServed) {
        let p = ships
            .iter_mut()
            .find_map(|s| match s {
                GgShip::Zc(ps) => ps.first_mut(),
                _ => None,
            })
            .expect("a zc proof exists");
        let q32 = q as u32;
        let bump = |v: &mut u32| {
            *v = if *v + 1 >= q32 { 0 } else { *v + 1 };
        };
        match tamper {
            GgTamper::Claim => bump(&mut p.col_claims[0][0][0]),
            GgTamper::Round => bump(&mut p.rounds[2][0][0]),
            GgTamper::MaskServed => bump(&mut p.mask_final.as_mut().expect("masked proof")[0]),
            _ => unreachable!(),
        }
    }

    // ---- Publics + nus + group proofs. ----
    let lcx = 10usize;
    let r_out: Vec<KElem> = (0..lr + lcx).map(|_| tr.challenge_k(&kf)).collect();
    let eq_oc = Rc::new(eq_table(&kf, &r_out[..lcx]));
    let eq_or = Rc::new(eq_table(&kf, &r_out[lcx..]));
    let mut public_vals: Vec<KElem> = Vec::new();
    for (e, _tag) in [(0usize, "X"), (16usize, "z")] {
        for (li, lay) in lays.iter().enumerate() {
            let v = bg_mle(&kf, &bf_entry_values(e, lay), bf_d(), &eq_or, &eq_oc);
            public_vals.push(v.clone());
            claims.push(BkClaim {
                in_weight: false,
                value: v,
                parts: to_parts(vec![(li, e, kf.one(), eq_or.clone(), eq_oc.clone())], &reg),
            });
        }
    }
    tr.absorb_k(&kf, "gg-public", &public_vals);
    let assemble = |claims: &[BkClaim], nus: &[KElem]| -> (KElem, KElem, GroupClaims, GroupClaims) {
        let mut vb_w = kf.zero();
        let mut vb_a = kf.zero();
        let mut gc_w = GroupClaims::new(reg.gw.tensors.len());
        let mut gc_a = GroupClaims::new(reg.ga.tensors.len());
        for (claim, nu) in claims.iter().zip(nus.iter()) {
            if claim.in_weight {
                vb_w = kf.add(&vb_w, &kf.mul(nu, &claim.value));
            } else {
                vb_a = kf.add(&vb_a, &kf.mul(nu, &claim.value));
            }
            for (ti, scale, row, col) in &claim.parts {
                let contrib = ClaimContrib {
                    tensor_idx: *ti,
                    scale: kf.mul(nu, scale),
                    row: row.clone(),
                    col: col.clone(),
                };
                if claim.in_weight {
                    gc_w.push(contrib);
                } else {
                    gc_a.push(contrib);
                }
            }
        }
        (vb_w, vb_a, gc_w, gc_a)
    };
    let nus: Vec<KElem> = (0..claims.len()).map(|_| tr.challenge_k(&kf)).collect();
    let nus_h: Vec<KElem> = (0..claims_h.len()).map(|_| tr.challenge_k(&kf)).collect();
    let (vb_w, vb_a, gc_w, gc_a) = assemble(&claims, &nus);
    let mut mask_rng = ring::ProverRng::from_test_seed("uperf3-gg-tz", &[0xB8]);
    let rr_t_pub = t_prove.elapsed().as_secs_f64(); // [UPERF3-RR]
    let (proof_w, _tzw) = bg_prove_group(
        &ctxr, &kf, &reg.gw, &sched_w, &mut w0_w, &gc_w, &vb_w, pre_w, &mut tr, crs_seed, false, false,
        &mut mask_rng,
    );
    let rr_t_gw = t_prove.elapsed().as_secs_f64(); // [UPERF3-RR]
    let (proof_a, _tza) = bg_prove_group(
        &ctxr, &kf, &reg.ga, &sched_a, &mut w0_a, &gc_a, &vb_a, pre_a, &mut tr, crs_seed,
        tamper == GgTamper::MaskCommit, false, &mut mask_rng,
    );
    let rr_t_ga = t_prove.elapsed().as_secs_f64(); // [UPERF3-RR]
    let proof_h = if let (Some(g), Some(sh), Some(p)) = (gh.as_ref(), sched_h.as_ref(), pre_h) {
        let mut vb_h = kf.zero();
        let mut gc_h = GroupClaims::new(g.tensors.len());
        for ((value, parts), nu) in claims_h.iter().zip(nus_h.iter()) {
            vb_h = kf.add(&vb_h, &kf.mul(nu, value));
            for (ti, scale, row, col) in parts {
                gc_h.push(ClaimContrib {
                    tensor_idx: *ti,
                    scale: kf.mul(nu, scale),
                    row: row.clone(),
                    col: col.clone(),
                });
            }
        }
        let (p_h, _) = bg_prove_group(
            &ctxr, &kf, g, sh, &mut w0_h, &gc_h, &vb_h, p, &mut tr, crs_seed, false, false, &mut mask_rng,
        );
        Some(p_h)
    } else {
        None
    };
    let prove_s = t_prove.elapsed().as_secs_f64();
    // [UPERF3-SS] the pass digest: the prover transcript state after the
    // last group proof binds every shipped object (deterministic seeds) —
    // the byte-identity floor for the mode-routing rungs.
    println!("  [UPERF3-SS] PASS TRANSCRIPT DIGEST {}", hex_full(&tr.state()));
    if ss_cfg.is_some() {
        println!("  [UPERF3-SS] RSS high-water after the group proofs (prover done): {:.0} MiB", uperf_a_peak_rss_mib());
    }
    // [UPERF3-RR] the identity handle: the prover's transcript state binds
    // every absorbed object (claims, round polys, served values, the group
    // openings' rows) — the pass's EVAL-PROOF DIGEST analogue.
    let rr_tr_state = tr.state();

    // ---- VERIFIER (fresh transcript, own claim layer + stage-a). ----
    let t_verify = Instant::now();
    let (mut rr_tv_claim, mut rr_tv_stagea, mut rr_tv_pub) = (0f64, 0f64, 0f64);
    let mut rr_tv_state = [0u8; 32];
    let ctx_v = statement.digest().expect("verifier statement digests");
    let h0_v = uk8_sha(&[
        b"uperf3-gg-h0",
        &ctx_v,
        &gg_map_bytes(&reg, gh.as_ref()),
        &polys_bytes(&proof_w.u0),
        &polys_bytes(&proof_a.u0),
    ]);
    if h0_v != h0 {
        fail(&mut accept, &mut first_fail, "h0-map-binding".to_string());
    }
    if accept {
        let mut tv = LkpTranscript::new("uperf3-gg-pass", &h0_v);
        let mut claims_v: Vec<BkClaim> = Vec::new();
        let mut claims_h_v: Vec<(KElem, Vec<(usize, KElem, Rc<Vec<KElem>>, Rc<Vec<KElem>>)>)> = Vec::new();
        let mut sci = 0usize;
        'verify: {
            for (name, a_e, b_e, c_e) in BG_MM_INSTS {
                let (_ar, a_cols) = bf_entry_shape(a_e, t);
                let (_br, b_cols) = bf_entry_shape(b_e, t);
                let (inner, cols) = (a_cols, b_cols);
                let lk = usize::BITS as usize - (inner - 1).leading_zeros() as usize;
                let lc = usize::BITS as usize - (cols - 1).leading_zeros() as usize;
                let r_l: Vec<KElem> = (0..lambda).map(|_| tv.challenge_k(&kf)).collect();
                let rx: Vec<KElem> = (0..lr).map(|_| tv.challenge_k(&kf)).collect();
                let ry: Vec<KElem> = (0..lc).map(|_| tv.challenge_k(&kf)).collect();
                let v_c = &v_cs[sci];
                tv.absorb_k(&kf, &format!("gg-claim-{name}"), std::slice::from_ref(v_c));
                let sched = matmul_degree_schedule(lk, lambda);
                let scp = &sc_proofs[sci];
                let Some((point, _red)) = ixf_sumcheck_verify(&kf, &sched, v_c, scp, &product3, &mut tv)
                else {
                    fail(&mut accept, &mut first_fail, "sc-matmul".to_string());
                    break 'verify;
                };
                if scp.final_evals[0] != eq_eval(&kf, &r_l, &point[lk..]) {
                    fail(&mut accept, &mut first_fail, "eq-final".to_string());
                    break 'verify;
                }
                tv.absorb_k(&kf, &format!("gg-final-{name}"), &scp.final_evals);
                let eq_rx = Rc::new(eq_table(&kf, &rx));
                let eq_ry = Rc::new(eq_table(&kf, &ry));
                let eq_rl = eq_table(&kf, &r_l);
                let eq_ks = Rc::new(eq_table(&kf, &point[..lk]));
                let eq_ls = eq_table(&kf, &point[lk..]);
                claims_v.push(BkClaim {
                    in_weight: false,
                    value: scp.final_evals[1].clone(),
                    parts: to_parts(
                        (0..layers_n).map(|li| (li, a_e, eq_ls[li].clone(), eq_rx.clone(), eq_ks.clone())).collect(),
                        &reg,
                    ),
                });
                claims_v.push(BkClaim {
                    in_weight: true,
                    value: scp.final_evals[2].clone(),
                    parts: to_parts(
                        (0..layers_n).map(|li| (li, b_e, eq_ls[li].clone(), eq_ks.clone(), eq_ry.clone())).collect(),
                        &reg,
                    ),
                });
                claims_v.push(BkClaim {
                    in_weight: false,
                    value: v_c.clone(),
                    parts: to_parts(
                        (0..layers_n).map(|li| (li, c_e, eq_rl[li].clone(), eq_rx.clone(), eq_ry.clone())).collect(),
                        &reg,
                    ),
                });
                sci += 1;
            }
            for (name, e1, e2, e3, is_rq) in &zc_insts {
                let shape_e = if *is_rq { *e1 } else { *e3 };
                let (_rows, cols_real) = bf_entry_shape(shape_e, t);
                let lcp = usize::BITS as usize - (cols_real - 1).leading_zeros() as usize;
                let n_pos = lr + lcp;
                let r_q: Vec<KElem> = (0..n_pos + lambda).map(|_| tv.challenge_k(&kf)).collect();
                let zero = kf.zero();
                tv.absorb_k(&kf, &format!("gg-claim-{name}"), std::slice::from_ref(&zero));
                let sched = if *is_rq {
                    let mut d = vec![2usize; n_pos];
                    d.extend(std::iter::repeat_n(3usize, lambda));
                    d
                } else {
                    zerocheck_degree_schedule(n_pos, lambda)
                };
                let scp = &sc_proofs[sci];
                let res = if *is_rq {
                    ixf_sumcheck_verify(&kf, &sched, &zero, scp, &rq_comb, &mut tv)
                } else {
                    ixf_sumcheck_verify(&kf, &sched, &zero, scp, &had_comb, &mut tv)
                };
                let Some((point, _red)) = res else {
                    fail(&mut accept, &mut first_fail, "sc-zerocheck".to_string());
                    break 'verify;
                };
                if scp.final_evals[0] != eq_eval(&kf, &r_q, &point) {
                    fail(&mut accept, &mut first_fail, "eq-final".to_string());
                    break 'verify;
                }
                if *is_rq {
                    let eq_pl = eq_table(&kf, &point[n_pos..]);
                    let mut sh_star = kf.zero();
                    for (li, lay) in lays.iter().enumerate() {
                        sh_star = kf.add(&sh_star, &kf.scale(zq.to_mod(1i64 << bg_rq_shift(name, lay)), &eq_pl[li]));
                    }
                    if scp.final_evals[4] != sh_star {
                        fail(&mut accept, &mut first_fail, "sh-final".to_string());
                        break 'verify;
                    }
                }
                tv.absorb_k(&kf, &format!("gg-final-{name}"), &scp.final_evals);
                let eq_pc = Rc::new(eq_table(&kf, &point[..lcp]));
                let eq_pr = Rc::new(eq_table(&kf, &point[lcp..n_pos]));
                let eq_pl = eq_table(&kf, &point[n_pos..]);
                for (fe, e) in [(1usize, *e1), (2, *e2), (3, *e3)] {
                    claims_v.push(BkClaim {
                        in_weight: false,
                        value: scp.final_evals[fe].clone(),
                        parts: to_parts(
                            (0..layers_n).map(|li| (li, e, eq_pl[li].clone(), eq_pr.clone(), eq_pc.clone())).collect(),
                            &reg,
                        ),
                    });
                }
                sci += 1;
            }
            // Stage-A phase, verifier side.
            let mut alphas_v: Vec<Option<KElem>> = vec![None; specs.len()];
            if mode == GgMode::Full {
                rr_tv_claim = t_verify.elapsed().as_secs_f64(); // [UPERF3-RR]
            for (pi, sp) in specs.iter().enumerate() {
                    if sp.silu.is_some() {
                        alphas_v[pi] = Some(tv.challenge_k(&kf));
                    }
                }
                tv.absorb("gg-u0h", &polys_bytes(&proof_h.as_ref().unwrap().u0));
            } else if ss_cfg.is_some() {
                // [UPERF3-SS] one alpha per lookup-carrying pair, then u_0(T_h).
                for (pi, sp) in specs.iter().enumerate() {
                    if sp.silu.is_some() || !plans[pi].ss_routes.is_empty() {
                        alphas_v[pi] = Some(tv.challenge_k(&kf));
                    }
                }
                tv.absorb("gg-u0h", &polys_bytes(&proof_h.as_ref().unwrap().u0));
            }
            for (pi, sp) in specs.iter().enumerate() {
                match &ships[pi] {
                    GgShip::Descent(ptx) => {
                        let plan = &sp.plan;
                        let alpha_v = tv.challenge_k(&kf);
                        let shell_w = zero_masks(&kf, plan.depth, plan.e_bits);
                        let Some((roots_w, endw_v)) =
                            masked_gkr_verify(&kf, plan.l, plan.depth, &shell_w, &ptx.pw, &mut tv, false)
                        else {
                            fail(&mut accept, &mut first_fail, format!("pair-descent-w:{}", sp.name()));
                            break 'verify;
                        };
                        let shell_t = zero_masks(&kf, sp.dt, plan.e_bits);
                        let Some((roots_t, endt_v)) =
                            masked_gkr_verify(&kf, plan.l, sp.dt, &shell_t, &ptx.pt, &mut tv, false)
                        else {
                            fail(&mut accept, &mut first_fail, format!("pair-descent-t:{}", sp.name()));
                            break 'verify;
                        };
                        let mut cross_ok = true;
                        for i in 0..plan.n_real {
                            cross_ok &= root_cross_check(&kf, &roots_w[i], &roots_t[i]);
                        }
                        for i in plan.n_real..plan.l {
                            for p in [&ptx.pw.layer1[i], &ptx.pt.layer1[i]] {
                                cross_ok &= kf.is_zero(&p[0])
                                    && kf.is_zero(&p[1])
                                    && p[2] == kf.one()
                                    && p[3] == kf.one();
                            }
                        }
                        if !cross_ok {
                            fail(&mut accept, &mut first_fail, format!("pair-cross-check:{}", sp.name()));
                            break 'verify;
                        }
                        let view = BkPairView {
                            alpha: &alpha_v,
                            pw: &ptx.pw,
                            endw: &endw_v,
                            pt: &ptx.pt,
                            endt: &endt_v,
                        };
                        bk_pair_claims(&kf, sp, &reg, pi, &view, &ypow, &mut claims_v);
                    }
                    GgShip::Logup(outs) => {
                        let alpha_v = alphas_v[pi].clone().unwrap();
                        let mat = logup_mat[pi].as_ref().unwrap();
                        let (_, ti_h, n_log2) = plans[pi].logup.unwrap();
                        let gh_rows = gh.as_ref().unwrap().tensors[ti_h].rows;
                        for (j, out) in outs.iter().enumerate() {
                            let rho_v: Vec<KElem> = (0..n_log2).map(|_| tv.challenge_k(&kf)).collect();
                            let (chain_ok, sum_ok) =
                                logup_sumcheck_verify(&kf, n_log2, &alpha_v, &rho_v, out, &mut tv);
                            if !chain_ok || !sum_ok {
                                fail(
                                    &mut accept,
                                    &mut first_fail,
                                    format!("logup-{}:{}", if chain_ok { "sum" } else { "chain" }, sp.name()),
                                );
                                break 'verify;
                            }
                            tv.absorb_k(&kf, "gg-lu-final", &out.proof.final_evals);
                            tv.absorb_k(
                                &kf,
                                "gg-lu-served",
                                &[out.h_sum.clone(), out.table_sum.clone(), out.h_at_point.clone(), out.key_at_point.clone()],
                            );
                            gg_logup_claims(
                                &kf, &reg, sp, &plans[pi], gh_rows, j, &alpha_v, &mat.table_k, out,
                                &mut claims_v, &mut claims_h_v,
                            );
                        }
                    }
                    GgShip::SsLookup(outs) => {
                        // [UPERF3-SS] the SiLU pair under the committed-h routing.
                        let alpha_v = alphas_v[pi].clone().unwrap();
                        let kappa = plans[pi].ss_kappa;
                        let (ti_m, ti_h, n_log2) = plans[pi].logup.unwrap();
                        let gh_rows = gh.as_ref().unwrap().tensors[ti_h].rows;
                        let table_v = sp.table_k(&kf);
                        for (j, out) in outs.iter().enumerate() {
                            let rho_v: Vec<KElem> = (0..n_log2 - kappa).map(|_| tv.challenge_k(&kf)).collect();
                            let (chain_ok, sum_ok) =
                                ring::stage_a::full::lookup_verify(&kf, n_log2, &alpha_v, &rho_v, out, &mut tv);
                            if !chain_ok || !sum_ok {
                                fail(
                                    &mut accept,
                                    &mut first_fail,
                                    format!("ss-lookup-{}:{}", if chain_ok { "sum" } else { "chain" }, sp.name()),
                                );
                                break 'verify;
                            }
                            ss_absorb_served(&kf, &mut tv, out);
                            ss_lookup_claims(
                                &kf, &reg, sp, &sp.members[j], ti_m, j, ti_h, gh_rows, j, &alpha_v, &table_v, out,
                                &mut claims_v, &mut claims_h_v,
                            );
                        }
                    }
                    GgShip::Zc(proofs) => {
                        for (ci, cls) in plans[pi].classes.iter().enumerate() {
                            let m_cols = cls.members.len();
                            let n_tot = cls.n_log2 + ring::zc_range::zc_agg_axis(m_cols);
                            let rho_v: Vec<_> = (0..n_tot).map(|_| ext.challenge(&kf, &mut tv)).collect();
                            let betas_v: Vec<_> = (0..cls.w + 1).map(|_| ext.challenge(&kf, &mut tv)).collect();
                            let res = if mode == GgMode::Masked {
                                ring::stage_a::zc_agg_verify_masked_served(
                                    &kf, &ext, cls.n_log2, 1, cls.w, m_cols, &rho_v, &betas_v, &proofs[ci],
                                    &mut tv,
                                )
                            } else {
                                zc_agg_verify(
                                    &kf, &ext, cls.n_log2, 1, cls.w, m_cols, &rho_v, &betas_v, &proofs[ci],
                                    &mut tv,
                                )
                            };
                            let Some(point) = res else {
                                fail(&mut accept, &mut first_fail, format!("zc-agg:{}", sp.name()));
                                break 'verify;
                            };
                            let mut flat: Vec<KElem> = proofs[ci]
                                .col_claims
                                .iter()
                                .flat_map(|cl| cl.iter().map(|e| ext.to_k(e)))
                                .collect();
                            if let Some(mf) = &proofs[ci].mask_final {
                                flat.push(ext.to_k(mf));
                            }
                            tv.absorb_k(&kf, "gg-zc-claims", &flat);
                            gg_zc_claims_sel(&kf, &ext, &reg, sp, cls, &proofs[ci], &point, &mut claims_v);
                            if mode == GgMode::Masked {
                                gg_mask_claims(&kf, &ext, cls, &proofs[ci], &point, &mut claims_v);
                            }
                        }
                        // [UPERF3-SS] rung V1: the routed members after the classes.
                        for (ri, r) in plans[pi].ss_routes.iter().enumerate() {
                            let alpha_v = alphas_v[pi].clone().unwrap();
                            let gh_rows = gh.as_ref().unwrap().tensors[r.ti_h].rows;
                            let table_v = sp.table_k(&kf);
                            let out = &ss_ships[pi][ri];
                            let rho_v: Vec<KElem> = (0..r.n_log2 - r.kappa).map(|_| tv.challenge_k(&kf)).collect();
                            let (chain_ok, sum_ok) =
                                ring::stage_a::full::lookup_verify(&kf, r.n_log2, &alpha_v, &rho_v, out, &mut tv);
                            if !chain_ok || !sum_ok {
                                fail(
                                    &mut accept,
                                    &mut first_fail,
                                    format!("ss-lookup-{}:{}", if chain_ok { "sum" } else { "chain" }, sp.name()),
                                );
                                break 'verify;
                            }
                            ss_absorb_served(&kf, &mut tv, out);
                            ss_lookup_claims(
                                &kf, &reg, sp, &sp.members[r.mi], r.ti_m, 0, r.ti_h, gh_rows, 0, &alpha_v, &table_v, out,
                                &mut claims_v, &mut claims_h_v,
                            );
                        }
                    }
                }
            }
            rr_tv_stagea = t_verify.elapsed().as_secs_f64(); // [UPERF3-RR]
            // Publics.
            let r_out: Vec<KElem> = (0..lr + lcx).map(|_| tv.challenge_k(&kf)).collect();
            let eq_oc = Rc::new(eq_table(&kf, &r_out[..lcx]));
            let eq_or = Rc::new(eq_table(&kf, &r_out[lcx..]));
            let mut pi_c = 0usize;
            for (e, _tag) in [(0usize, "X"), (16usize, "z")] {
                for (li, lay) in lays.iter().enumerate() {
                    let want = bg_mle(&kf, &bf_entry_values(e, lay), bf_d(), &eq_or, &eq_oc);
                    if public_vals[pi_c] != want {
                        fail(&mut accept, &mut first_fail, "public-claim".to_string());
                        break 'verify;
                    }
                    claims_v.push(BkClaim {
                        in_weight: false,
                        value: want,
                        parts: to_parts(vec![(li, e, kf.one(), eq_or.clone(), eq_oc.clone())], &reg),
                    });
                    pi_c += 1;
                }
            }
            tv.absorb_k(&kf, "gg-public", &public_vals);
            let nus_v: Vec<KElem> = (0..claims_v.len()).map(|_| tv.challenge_k(&kf)).collect();
            let nus_h_v: Vec<KElem> = (0..claims_h_v.len()).map(|_| tv.challenge_k(&kf)).collect();
            let (vb_w_v, vb_a_v, gc_w_v, gc_a_v) = assemble(&claims_v, &nus_v);
            rr_tv_pub = t_verify.elapsed().as_secs_f64(); // [UPERF3-RR]
            let res_w = bg_verify_group(&ctxr, &kf, &reg.gw, &sched_w, &gc_w_v, &vb_w_v, &proof_w, &mut tv, crs_seed, None);
            let res_a = bg_verify_group(&ctxr, &kf, &reg.ga, &sched_a, &gc_a_v, &vb_a_v, &proof_a, &mut tv, crs_seed, None);
            for res in [&res_w, &res_a] {
                if let Err(e) = res {
                    fail(&mut accept, &mut first_fail, (*e).to_string());
                }
            }
            if let (Some(g), Some(sh), Some(ph)) = (gh.as_ref(), sched_h.as_ref(), proof_h.as_ref()) {
                let mut vb_h_v = kf.zero();
                let mut gc_h_v = GroupClaims::new(g.tensors.len());
                for ((value, parts), nu) in claims_h_v.iter().zip(nus_h_v.iter()) {
                    vb_h_v = kf.add(&vb_h_v, &kf.mul(nu, value));
                    for (ti, scale, row, col) in parts {
                        gc_h_v.push(ClaimContrib {
                            tensor_idx: *ti,
                            scale: kf.mul(nu, scale),
                            row: row.clone(),
                            col: col.clone(),
                        });
                    }
                }
                if let Err(e) = bg_verify_group(&ctxr, &kf, g, sh, &gc_h_v, &vb_h_v, ph, &mut tv, crs_seed, None) {
                    fail(&mut accept, &mut first_fail, e.to_string());
                }
            }
        }
        rr_tv_state = tv.state(); // [UPERF3-RR]
    }
    let verify_s = t_verify.elapsed().as_secs_f64();

    // ---- Byte lines + the oracle delta. ----
    let mut bytes_groups = 0usize;
    let mut group_desc = String::new();
    for (name, proof) in [("weight", Some(&proof_w)), ("act", Some(&proof_a)), ("act-h", proof_h.as_ref())] {
        let Some(p) = proof else { continue };
        let b = p.counted_bytes();
        let tot = b.outer_identities + b.claim_rows + b.level_msgs + b.floor;
        bytes_groups += tot;
        group_desc.push_str(&format!(" {name} {tot} B;"));
    }
    let bytes_publics = 64 * public_vals.len();
    let bytes_inst = inst_kel * 64;
    let total =
        bytes_statement + bytes_inst + bytes_publics + stage_a_bytes + bytes_groups;
    println!(
        "  STAGE-A pass: commit {commit_s:.1}s prove {prove_s:.1}s verify {verify_s:.1}s | {total} B counted | accept {accept}"
    );
    if let Some(f) = &first_fail {
        println!("    first_fail: {f}");
    }
    println!(
        "  bytes: statement {bytes_statement} + instances {bytes_inst} + STAGE-A {stage_a_bytes} + publics {bytes_publics} + groups {bytes_groups} ({group_desc})"
    );
    println!(
        "  groups: weight n_0 {} ({} lv), act n_0 {} ({} lv){}",
        reg.gw.n_digit_rings,
        sched_w.levels.len(),
        reg.ga.n_digit_rings,
        sched_a.levels.len(),
        match (gh.as_ref(), sched_h.as_ref()) {
            (Some(g), Some(sh)) => format!(", act-h n_0 {} ({} lv)", g.n_digit_rings, sh.levels.len()),
            _ => String::new(),
        }
    );
    let n_claims = claims.len() + claims_h.len();
    println!("  claims served: {} (act/weight) + {} (act-h) = {n_claims}", claims.len(), claims_h.len());
    if let (Some(cfg), Some(g)) = (ss_cfg, gh.as_ref()) {
        println!(
            "  [UPERF3-SS] full-ss: kappa_silu {} route {:?} | act-h tensors {} | helper build {:.2}s, lookup sumchecks {:.2}s",
            cfg.kappa_silu,
            cfg.route_nrw,
            g.tensors.iter().map(|t| format!("{} {}x{} {} rings", t.name, t.rows, t.cols, t.n_digit_rings())).collect::<Vec<_>>().join(", "),
            ss_secs_helper,
            ss_secs_prove,
        );
    }
    let _ = clog2; // (used by gg_build_groups)
    let rr_prof_stage_a: Vec<(&'static str, f64, u64)> = prof::report();
    let mut rr_prof_oracle: Vec<(&'static str, f64, u64)> = Vec::new();
    if with_oracle {
        println!("  ORACLE (frozen bk_pass_run, same shape, default path):");
        let opts = BkOpts { layers_n, t, p2: false, tamper: BkTamper::None, weak_alpha: false, quiet: true, ..Default::default() };
        prof::reset();
        let (v, c, _art) = bk_pass_run(&opts);
        rr_prof_oracle = prof::report();
        println!(
            "    accept {} | commit {:.1}s prove {:.1}s verify {:.1}s | {} B counted (descent pairs {} B)",
            v.accept(),
            c.commit_s,
            c.prove_s,
            c.verify_s,
            c.bytes_total(),
            c.bytes_pairs()
        );
        let reg_o = bk_build_groups(&lays, t, &specs, q);
        println!(
            "  TRANSCRIPT DELTA [COUNTED]: descent pairs {} B -> STAGE-A {} B; total {} B -> {} B; act n_0 {} -> {}{}",
            c.bytes_pairs(),
            stage_a_bytes,
            c.bytes_total(),
            total,
            reg_o.ga.n_digit_rings,
            reg.ga.n_digit_rings,
            match gh.as_ref() {
                Some(g) => format!(" + act-h {}", g.n_digit_rings),
                None => String::new(),
            }
        );
    }
    // [UPERF3-RR] rung 1: the attribution table + the identity digest.
    println!(
        "[UPERF3-RR] ATTRIBUTION mode {mode_name}{} (walls s; {} threads):",
        if rr_zc_claims_batched() { " + zc claims BATCHED (ZK_RR_ZC_CLAIMS=batched: a Stage-A transcript VARIANT)" } else { "" },
        ring::eval_proof::threads()
    );
    println!(
        "  commit {commit_s:.2}: groups+planes {:.2} | witness {:.2} | precommit weight {:.2} | precommit act {:.2} | statement {:.2}",
        rr_t_groups, rr_t_wit - rr_t_groups, rr_t_pre_w - rr_t_wit, rr_t_pre_a - rr_t_pre_w, commit_s - rr_t_pre_a
    );
    println!(
        "  prove {prove_s:.2}: claim-layer {:.2} | stage-a phase {:.2} = silu descents {:.2} + logup {:.2} + zc tabs-build {:.2} + zc prove {:.2} (eq {:.2} rounds {:.2} folds {:.2}; {} rounds, {:.2} G MACs) + zc claims-transport {:.2} + other {:.2} | publics+nus {:.2} | opening weight {:.2} | opening act {:.2} | tail {:.2}",
        rr_t_claim, rr_t_stagea - rr_t_claim, rr_s_desc, rr_s_logup, rr_s_tabs, rr_s_zc, rr_s_zc_eq, rr_s_zc_round, rr_s_zc_fold, rr_zc_rounds, rr_zc_macs as f64 / 1e9, rr_s_zc_claims,
        (rr_t_stagea - rr_t_claim) - rr_s_desc - rr_s_logup - rr_s_tabs - rr_s_zc - rr_s_zc_claims,
        rr_t_pub - rr_t_stagea, rr_t_gw - rr_t_pub, rr_t_ga - rr_t_gw, prove_s - rr_t_ga
    );
    for l in &rr_zc_lines {
        println!("    {l}");
    }
    println!(
        "  verify {verify_s:.2}: claim-layer {:.2} | stage-a {:.2} | publics+nus {:.2} | group verifies {:.2}",
        rr_tv_claim, rr_tv_stagea - rr_tv_claim, rr_tv_pub - rr_tv_stagea, verify_s - rr_tv_pub
    );
    println!("  device: {} | {} | {} | {}", ring::gpu::label(), ring::gpu::k9_label(), ring::gpu::ixf_label(), ring::gpu::zc_label());
    println!("  phase table (prof, process-global; STAGE-A pass | ORACLE pass; bg.* per-group totals, ep.* shared by prover and verifier):");
    let mut names: Vec<&'static str> = rr_prof_stage_a.iter().map(|l| l.0).collect();
    for l in &rr_prof_oracle {
        if !names.contains(&l.0) {
            names.push(l.0);
        }
    }
    for name in names {
        let sa = rr_prof_stage_a.iter().find(|l| l.0 == name).map(|l| (l.1, l.2)).unwrap_or((0.0, 0));
        let or = rr_prof_oracle.iter().find(|l| l.0 == name).map(|l| (l.1, l.2)).unwrap_or((0.0, 0));
        if sa.1 == 0 && sa.0 == 0.0 && or.1 == 0 && or.0 == 0.0 {
            continue;
        }
        println!("    {name:<24} {:>9.2}s x{:<6} | {:>9.2}s x{}", sa.0, sa.1, or.0, or.1);
    }
    println!(
        "[UPERF3-RR] STAGE-A DIGEST statement {} | prover-transcript {} | verifier-transcript {} | bytes {total}",
        hex_full(&ctx_digest),
        hex_full(&rr_tr_state),
        hex_full(&rr_tv_state)
    );
    println!("  peak RSS {:.0} MiB", uperf_a_peak_rss_mib());
    accept
}

/// [UPERF3-GG] rung 2 helper — mutable access to a member entry's plane
/// (the tamper legs; remainder/narrowing entries only).
/// [UPERF3-OO] returns the compact plane; element writes go through
/// `BfPlane::set` (widening — a tampered out-of-class value rides wide).
fn gg_entry_values_mut(e: usize, lay: &mut BfLayer) -> &mut BfPlane {
    match BF_ENTRIES[e] {
        "Rg" => &mut lay.rg,
        "Ru" => &mut lay.ru,
        "Rh" => &mut lay.rh,
        "Rd" => &mut lay.rd,
        "u8" => &mut lay.u8v,
        "h8" => &mut lay.h8,
        "z" => &mut lay.z,
        _ => panic!("tamper leg supports remainder/narrowing entries only"),
    }
}

/// [UPERF3-GG] rung 2 helper — the eval-proof STAND-IN on the descent
/// side: evaluate one served claim's parts directly against the raw
/// committed grids (scale x row^T M col per part, values embedded as the
/// digit witness would serve them) and return the functional value the
/// opening would ground `claim.value` against.
fn gg_claim_functional(
    kf: &ring::kfield::KField,
    tensors: &[ring::eval_proof::AggTensor],
    vals: &[Option<&[i64]>],
    claim: &BkClaim,
) -> ring::kfield::KElem {
    let zq = &kf.zq;
    let mut acc = kf.zero();
    for (ti, scale, row, col) in &claim.parts {
        let ten = &tensors[*ti];
        let v = vals[*ti].unwrap_or_else(|| panic!("claim touches unresolved tensor {}", ten.name));
        let mut part = kf.zero();
        for (r, rw) in row.iter().enumerate() {
            if kf.is_zero(rw) {
                continue;
            }
            let mut rowacc = kf.zero();
            for (c, cw) in col.iter().enumerate() {
                let x = v[r * ten.cols + c];
                if x != 0 {
                    rowacc = kf.add(&rowacc, &kf.scale(zq.to_mod(x), cw));
                }
            }
            part = kf.add(&part, &kf.mul(rw, &rowacc));
        }
        acc = kf.add(&acc, &kf.mul(scale, &part));
    }
    acc
}

/// [UPERF3-GG] rung 2 — the descent ORACLE leg for ONE pair on the REAL
/// layers: bk_pass_run's per-pair call sequence at a fixed seed (alpha =
/// first challenge, aligned witness trees + blinded table trees over the
/// pair's aux, masked descents both sides, the pass-form verify —
/// zero-mask shells, no pins — root cross-checks, then bk_pair_claims from
/// the verifier's re-derived endpoints). Returns (verify+cross ok, the
/// served claims, walls).
#[allow(clippy::type_complexity)]
fn uperf_a_gg_desc_leg(
    kf: &ring::kfield::KField,
    sp: &BkPairSpec,
    lays: &[BfLayer],
    reg: &BkRegistry,
    pi: usize,
    seed: u8,
) -> (bool, Vec<BkClaim>, BkAuxMat, f64, f64, f64) {
    use ring::descent_fold::{aligned_witness_tree, neutral_tree};
    use ring::gkr::root_cross_check;
    use ring::gkr_masked::{blinded_table_tree, masked_gkr_prove, masked_gkr_verify, zero_masks};
    use ring::kfield::KElem;
    use ring::sumcheck::LkpTranscript;
    let zq = &kf.zq;
    let plan = &sp.plan;
    let mut rng = ring::ProverRng::from_test_seed("uperf3-gg-diff-aux", &[seed, sp.pid as u8]);
    let mut aux = bk_build_aux(sp, lays, reg, pi, kf, &mut rng);
    let mut tr = LkpTranscript::new("uperf3-gg-diff", &[seed; 32]);
    let alpha = tr.challenge_k(kf);
    let t0 = Instant::now();
    let mut wtrees: Vec<ring::gkr::FracTree> = Vec::with_capacity(plan.l);
    for i in 0..plan.n_real {
        let slots = bk_tree_slots(kf, sp, lays, i);
        let slot_refs: Vec<(ring::descent_fold::MemberShape, usize, &[KElem])> =
            slots.iter().map(|(s, b, c)| (*s, *b, c.as_slice())).collect();
        wtrees.push(aligned_witness_tree(kf, &alpha, &slot_refs, plan.depth, &aux.bl_w[i]));
    }
    for _ in plan.n_real..plan.l {
        wtrees.push(neutral_tree(kf, plan.depth));
    }
    let trees_a = t0.elapsed().as_secs_f64();
    let masks_w = aux.masks_w.take().expect("witness masks drawn once");
    let t1 = Instant::now();
    let (pw, _endw) = masked_gkr_prove(kf, &wtrees, masks_w, &mut tr);
    drop(wtrees);
    let t2 = Instant::now();
    let tab_k = sp.table_k(kf);
    let mut ttrees: Vec<ring::gkr::FracTree> = Vec::with_capacity(plan.l);
    for i in 0..plan.n_real {
        let m_k: Vec<KElem> = aux.m_counts[i].iter().map(|&c| kf.embed(zq.to_mod(c))).collect();
        ttrees.push(blinded_table_tree(kf, &alpha, &tab_k, &m_k, sp.dt, &aux.bl_t[i]));
    }
    for _ in plan.n_real..plan.l {
        ttrees.push(neutral_tree(kf, sp.dt));
    }
    let trees_s = trees_a + t2.elapsed().as_secs_f64();
    let masks_t = aux.masks_t.take().expect("table masks drawn once");
    let (pt, _endt) = masked_gkr_prove(kf, &ttrees, masks_t, &mut tr);
    drop(ttrees);
    let prove_s = t1.elapsed().as_secs_f64() - (trees_s - trees_a);
    // The pass-form VERIFY on a fresh transcript.
    let t3 = Instant::now();
    let mut tv = LkpTranscript::new("uperf3-gg-diff", &[seed; 32]);
    let alpha_v = tv.challenge_k(kf);
    assert!(alpha_v == alpha, "alpha replay");
    let shell_w = zero_masks(kf, plan.depth, plan.e_bits);
    let Some((roots_w, endw_v)) = masked_gkr_verify(kf, plan.l, plan.depth, &shell_w, &pw, &mut tv, false) else {
        return (false, Vec::new(), aux, trees_s, prove_s, t3.elapsed().as_secs_f64());
    };
    let shell_t = zero_masks(kf, sp.dt, plan.e_bits);
    let Some((roots_t, endt_v)) = masked_gkr_verify(kf, plan.l, sp.dt, &shell_t, &pt, &mut tv, false) else {
        return (false, Vec::new(), aux, trees_s, prove_s, t3.elapsed().as_secs_f64());
    };
    let mut cross_ok = tv.state() == tr.state();
    for i in 0..plan.n_real {
        cross_ok &= root_cross_check(kf, &roots_w[i], &roots_t[i]);
    }
    for i in plan.n_real..plan.l {
        for p in [&pw.layer1[i], &pt.layer1[i]] {
            cross_ok &= kf.is_zero(&p[0]) && kf.is_zero(&p[1]) && p[2] == kf.one() && p[3] == kf.one();
        }
    }
    let verify_s = t3.elapsed().as_secs_f64();
    let mut claims: Vec<BkClaim> = Vec::new();
    if cross_ok {
        let ypow = bk_ypow_col(kf);
        let view = BkPairView { alpha: &alpha_v, pw: &pw, endw: &endw_v, pt: &pt, endt: &endt_v };
        bk_pair_claims(kf, sp, reg, pi, &view, &ypow, &mut claims);
    }
    (cross_ok, claims, aux, trees_s, prove_s, verify_s)
}

/// [UPERF3-GG] rung 2 — ONE-FAMILY DIFFERENTIAL on the real shape: the
/// chosen range pair proved BOTH ways at fixed seeds — (a) the masked
/// descent pair (the frozen pass's call sequence, the ORACLE) with every
/// served claim grounded directly against the raw committed grids (the
/// eval-proof stand-in), and (b) the Stage-A aggregate zero-check
/// ([UPERF3-EE] zc_agg) over the same columns' width-w bit planes with
/// every served claim checked bit-for-bit against base_mle_eval (the S1
/// zc_range_open_check pattern). Plus the off-table tamper mini-legs on
/// both sides.
fn uperf_a_gg_diff(pair: &str, layers_n: usize, t: usize, seed: u8) {
    use ring::kfield::KField;
    use ring::stage_a::{clog2, range_planes};
    use ring::sumcheck::LkpTranscript;
    use ring::zc_range::{SubExt, ZcAggInstance, ZcRangeInstance, base_mle_eval, zc_agg_prove, zc_agg_verify};
    use sha2::{Digest, Sha256};
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let q = ctxr.zq.q;
    println!(
        "[UPERF3-GG] diff: pair {pair}, {layers_n} layers, T = {t}, seed {seed} [WSL-BOX NOISY-SHARED]"
    );
    let lays: Vec<BfLayer> = (0..layers_n).map(|l| bf_load_layer(l, t, true)).collect();
    let specs = bk_pair_specs(&lays, t);
    let pi = specs.iter().position(|s| s.name() == pair).unwrap_or_else(|| {
        panic!("pair {pair} absent at this shape (present: {:?})", specs.iter().map(|s| s.name()).collect::<Vec<_>>())
    });
    let sp = &specs[pi];
    assert!(sp.silu.is_none(), "diff rung covers the range families (SiLU rides rung 3)");
    let reg = bk_build_groups(&lays, t, &specs, q);
    let w = sp.t_rows.trailing_zeros() as usize;

    // ---- (a) the descent ORACLE leg + the serving check. ----
    let (ok, claims, aux, trees_s, prove_s, verify_s) = uperf_a_gg_desc_leg(&kf, sp, &lays, &reg, pi, seed);
    assert!(ok, "honest descent pair must verify + cross-check");
    // [UPERF3-OO] guard owners for the per-tensor slices (battery leg,
    // small shapes — holding every act plane materialized is fine here).
    let mut owners: Vec<Option<BfVals>> = (0..reg.ga.tensors.len()).map(|_| None).collect();
    for (li, lay) in lays.iter().enumerate() {
        for e in 0..BF_ENTRIES.len() {
            let (in_w, ti) = reg.map[li][e];
            if !in_w {
                owners[ti] = Some(bf_entry_values(e, lay));
            }
        }
    }
    let mut vals_of: Vec<Option<&[i64]>> = owners.iter().map(|o| o.as_ref().map(|g| &**g)).collect();
    let [ti_m, ti_bl, ti_wm, ti_tm] = reg.aux_base[pi];
    vals_of[ti_m] = Some(&aux.vals_m);
    vals_of[ti_bl] = Some(&aux.vals_bl);
    vals_of[ti_wm] = Some(&aux.vals_wm);
    vals_of[ti_tm] = Some(&aux.vals_tm);
    let mut ground_ok = 0usize;
    for (ci, claim) in claims.iter().enumerate() {
        assert!(!claim.in_weight, "pair claims live in the act group");
        let f = gg_claim_functional(&kf, &reg.ga.tensors, &vals_of, claim);
        assert!(f == claim.value, "descent served claim {ci} does not ground against the raw grids");
        ground_ok += 1;
    }
    println!(
        "  (a) descent oracle: verify+cross green; SERVING CHECK {ground_ok}/{} claims — each claim.value == sum_parts(scale x row^T M col) over the raw committed grids (members via bf_entry_values, aux via bk_build_aux) EXACT; trees {trees_s:.2}s prove {prove_s:.2}s verify {verify_s:.2}s",
        claims.len()
    );

    // ---- (b) the Stage-A zc_agg leg + the serving check. ----
    // One aggregate per shape class (equal n_log2 per zc_agg).
    let ext = SubExt::new(&kf, 4);
    let mut shape_classes: Vec<(usize, usize)> = Vec::new();
    for m in &sp.members {
        let key = (m.shape.rows, m.shape.cols);
        if !shape_classes.contains(&key) {
            shape_classes.push(key);
        }
    }
    let mut zc_claims_total = 0usize;
    let mut zc_rounds_total = 0usize;
    let mut zc_prove_s = 0.0f64;
    for (rows, cols) in &shape_classes {
        let n_el = rows * cols;
        let n_log2 = clog2(n_el);
        let members: Vec<&BkMember> =
            sp.members.iter().filter(|m| (m.shape.rows, m.shape.cols) == (*rows, *cols)).collect();
        let m_cols = members.len();
        // The instances read the SAME committed values the descent folded.
        let mut store: Vec<(Vec<Vec<u32>>, Vec<u32>)> = Vec::with_capacity(m_cols);
        let mut code_digest = Sha256::new_with_prefix(b"uperf3-gg-codes-v1");
        for m in &members {
            let vals = bf_entry_values(m.entry, &lays[m.li]);
            let (planes, rem) = range_planes(&vals, m.offset, w, n_log2);
            for &r in rem.iter().take(vals.len()) {
                code_digest.update(r.to_le_bytes());
            }
            store.push((planes, rem));
        }
        let cols_inst: Vec<ZcRangeInstance> = store
            .iter()
            .map(|(p, r)| ZcRangeInstance { n_log2, e0: 1, planes: p, rem: r })
            .collect();
        let inst = ZcAggInstance { n_log2, e0: 1, cols: cols_inst };
        let a = inst.a();
        let n_tot = n_log2 + a;
        let mut trz = LkpTranscript::new("uperf3-gg-zc", &[seed; 32]);
        let rho: Vec<_> = (0..n_tot).map(|_| ext.challenge(&kf, &mut trz)).collect();
        let betas: Vec<_> = (0..w + 1).map(|_| ext.challenge(&kf, &mut trz)).collect();
        let tz = Instant::now();
        let (proof, point, stats) = zc_agg_prove(&kf, &ext, &inst, &rho, &betas, &mut trz);
        zc_prove_s += tz.elapsed().as_secs_f64();
        let mut trv = LkpTranscript::new("uperf3-gg-zc", &[seed; 32]);
        let rho_v: Vec<_> = (0..n_tot).map(|_| ext.challenge(&kf, &mut trv)).collect();
        let betas_v: Vec<_> = (0..w + 1).map(|_| ext.challenge(&kf, &mut trv)).collect();
        assert!(rho_v == rho && betas_v == betas, "challenge replay");
        let vpoint = zc_agg_verify(&kf, &ext, n_log2, 1, w, m_cols, &rho_v, &betas_v, &proof, &mut trv)
            .expect("honest aggregate must verify");
        assert!(vpoint == point && trv.state() == trz.state(), "zc transcript parity");
        // SERVING CHECK: every stacked claim == the table MLE at r_col.
        let r_col = &point[..n_log2];
        let mut mle_ok = 0usize;
        for (i, (planes, rem)) in store.iter().enumerate() {
            for (k, plane) in planes.iter().enumerate() {
                assert!(
                    proof.col_claims[i][k] == base_mle_eval(&ext, plane, r_col),
                    "zc served claim (col {i}, plane {k}) != base_mle_eval"
                );
                mle_ok += 1;
            }
            assert!(
                proof.col_claims[i][w] == base_mle_eval(&ext, rem, r_col),
                "zc served claim (col {i}, rem) != base_mle_eval"
            );
            mle_ok += 1;
        }
        zc_claims_total += mle_ok;
        zc_rounds_total += stats.rounds;
        println!(
            "  (b) zc_agg [{rows}x{cols} class]: m = {m_cols} cols x 2^{n_log2}, a = {a}, {} rounds, E_4; verify green; SERVING CHECK {mle_ok}/{mle_ok} col_claims == base_mle_eval(plane_k | rem, r_col) BIT-FOR-BIT; shared committed-code digest {}",
            stats.rounds,
            hex_full(&code_digest.finalize().into())[..16].to_string()
        );
    }
    println!(
        "  claims swap at this pair: descent serves {} claims (incl. {} member-grid parts inside wq) -> zc serves {zc_claims_total} MLE claims over {zc_rounds_total} rounds; zc prove {zc_prove_s:.2}s vs descent trees+prove {:.2}s [NOISY-SHARED]",
        claims.len(),
        sp.members.len(),
        trees_s + prove_s
    );

    // ---- Tamper mini-legs (the BK RangeViolation shape: a committable
    // ---- code bumped by +2^w — off-table both ways). ----
    let mut lays_t: Vec<BfLayer> = (0..layers_n).map(|l| bf_load_layer(l, t, true)).collect();
    let m0 = sp.members[0];
    let idx = 3usize;
    {
        let p = gg_entry_values_mut(m0.entry, &mut lays_t[m0.li]);
        let v = p.get(idx);
        p.set(idx, v + (1i64 << w));
    }
    let (ok_t, _c, _a, _t1, _t2, _t3) = uperf_a_gg_desc_leg(&kf, sp, &lays_t, &reg, pi, seed);
    assert!(!ok_t, "tampered descent leg must fail the root cross-check");
    println!("  tamper (a): +2^{w} at member 0 idx {idx} -> descent REJECTS (root cross-check / mass mismatch)");
    {
        let (rows, cols) = (m0.shape.rows, m0.shape.cols);
        let n_log2 = clog2(rows * cols);
        let members: Vec<&BkMember> =
            sp.members.iter().filter(|m| (m.shape.rows, m.shape.cols) == (rows, cols)).collect();
        let mut store: Vec<(Vec<Vec<u32>>, Vec<u32>)> = Vec::with_capacity(members.len());
        for (mi, m) in members.iter().enumerate() {
            let vals = bf_entry_values(m.entry, &lays_t[m.li]);
            if mi == 0 {
                // The cheating prover: the committed rem carries the real
                // (off-table) code; the best available planes are its low
                // w bits (the top bit cannot be presented — booleanity).
                let size = 1usize << n_log2;
                let mut planes = vec![vec![0u32; size]; w];
                let mut rem = vec![0u32; size];
                for (i, &v) in vals.iter().enumerate() {
                    let code = v + m.offset;
                    for (k, plane) in planes.iter_mut().enumerate() {
                        plane[i] = ((code >> k) & 1) as u32;
                    }
                    rem[i] = ctxr.zq.to_mod(code) as u32;
                }
                store.push((planes, rem));
            } else {
                store.push(range_planes(&vals, m.offset, w, n_log2));
            }
        }
        let cols_inst: Vec<ZcRangeInstance> =
            store.iter().map(|(p, r)| ZcRangeInstance { n_log2, e0: 1, planes: p, rem: r }).collect();
        let inst = ZcAggInstance { n_log2, e0: 1, cols: cols_inst };
        let n_tot = n_log2 + inst.a();
        let m_cols = inst.m();
        let mut trz = LkpTranscript::new("uperf3-gg-zc-tamper", &[seed; 32]);
        let rho: Vec<_> = (0..n_tot).map(|_| ext.challenge(&kf, &mut trz)).collect();
        let betas: Vec<_> = (0..w + 1).map(|_| ext.challenge(&kf, &mut trz)).collect();
        let (proof, _point, _stats) = zc_agg_prove(&kf, &ext, &inst, &rho, &betas, &mut trz);
        let mut trv = LkpTranscript::new("uperf3-gg-zc-tamper", &[seed; 32]);
        let rho_v: Vec<_> = (0..n_tot).map(|_| ext.challenge(&kf, &mut trv)).collect();
        let betas_v: Vec<_> = (0..w + 1).map(|_| ext.challenge(&kf, &mut trv)).collect();
        let res = zc_agg_verify(&kf, &ext, n_log2, 1, w, m_cols, &rho_v, &betas_v, &proof, &mut trv);
        assert!(res.is_none(), "tampered zc leg must reject");
        println!("  tamper (b): same bump, truncated-plane cheat -> zc_agg_verify REJECTS (recomposition breaks; the top bit cannot be presented)");
    }
    println!("[UPERF3-GG] diff: ALL LEGS GREEN (peak RSS {:.0} MiB)", uperf_a_peak_rss_mib());
}

/// [UPERF3-GG] rung 1 — THE OBJECT MAP (no proving): every descent-pair
/// family of the REAL pass at (layers, t), from the same engine structures
/// bk_pass_run drives (bk_pair_specs / plan_pair_trees /
/// pair_expected_bytes / the bk_pair_claims shape), with its Stage-A
/// replacement instance per design memo §2.3/§2.4. At (12, 512) the rows
/// are reconciled against the memo §1.1 counted table; any mismatch is
/// printed as a FINDING, never papered over.
fn uperf_a_gg_map(layers_n: usize, t: usize) {
    use ring::stage_a::{clog2, descent_pair_claims, zc_agg_plan};
    println!(
        "[UPERF3-GG] object map: {layers_n} layers, T = {t} (engine structures; memo §1.1 reconciliation at 12x512)"
    );
    let lays: Vec<BfLayer> = (0..layers_n).map(|l| bf_load_layer(l, t, true)).collect();
    let specs = bk_pair_specs(&lays, t);
    let q = ring_ctx_q8().zq.q;
    let reg = bk_build_groups(&lays, t, &specs, q);

    // ---- The descent side, as built. ----
    println!("  DESCENT PAIRS (as built — what the selector replaces):");
    println!(
        "  {:<8} {:>4} {:>5} {:>3} {:>4} {:>5} {:>3} {:>6} {:>9} {:>7} {:>10}",
        "pair", "mem", "trees", "l", "pad", "depth", "dt", "e_bits", "derived_B", "claims", "aux_vals"
    );
    let (mut tm, mut tr, mut tl, mut tp, mut tb, mut tc, mut ta) = (0usize, 0usize, 0usize, 0usize, 0usize, 0usize, 0usize);
    // memo §1.1 counted rows at 12x512: (name, cols, trees, l, pad, depth, dt, bytes)
    let memo: [(&str, usize, usize, usize, usize, usize, usize, usize); 10] = [
        ("silu-m3", 10, 5, 8, 3, 22, 9, 118_336),
        ("silu-m4", 2, 1, 1, 0, 22, 9, 92_480),
        ("nrw-88", 24, 12, 16, 4, 22, 9, 129_856),
        ("nrw-z", 12, 6, 8, 2, 21, 9, 111_360),
        ("rem-w5", 4, 2, 2, 0, 22, 6, 91_776),
        ("rem-w6", 7, 3, 4, 1, 22, 7, 102_336),
        ("rem-w7", 10, 3, 4, 1, 22, 8, 105_472),
        ("rem-w8", 17, 8, 8, 0, 22, 9, 118_336),
        ("rem-w9", 7, 3, 4, 1, 22, 10, 112_512),
        ("rem-w10", 3, 2, 2, 0, 21, 11, 100_992),
    ];
    let mut findings: Vec<String> = Vec::new();
    for (pi, sp) in specs.iter().enumerate() {
        let p = &sp.plan;
        let bytes = ring::descent_fold::pair_expected_bytes(p.depth, sp.dt, p.e_bits, p.l);
        let (_, _, claims) = descent_pair_claims(p.depth, sp.dt);
        let [m_cols, bl_kel, wm_kel, tm_kel] = reg.aux_shape[pi];
        let aux_vals = m_cols + (bl_kel + wm_kel + tm_kel) * ring::kfield::K_DEG;
        println!(
            "  {:<8} {:>4} {:>5} {:>3} {:>4} {:>5} {:>3} {:>6} {:>9} {:>7} {:>10}",
            sp.name(), sp.members.len(), p.n_real, p.l, p.l - p.n_real, p.depth, sp.dt, p.e_bits, bytes, claims, aux_vals
        );
        tm += sp.members.len();
        tr += p.n_real;
        tl += p.l;
        tp += p.l - p.n_real;
        tb += bytes;
        tc += claims;
        ta += aux_vals;
        if (layers_n, t) == (12, 512) {
            if let Some(row) = memo.iter().find(|r| r.0 == sp.name()) {
                let got = (sp.members.len(), p.n_real, p.l, p.l - p.n_real, p.depth, sp.dt, bytes);
                let want = (row.1, row.2, row.3, row.4, row.5, row.6, row.7);
                if got != want {
                    findings.push(format!("{}: engine {:?} != memo {:?}", sp.name(), got, want));
                }
            } else {
                findings.push(format!("{}: pair absent from the memo table", sp.name()));
            }
        }
    }
    println!(
        "  {:<8} {:>4} {:>5} {:>3} {:>4} {:>5} {:>3} {:>6} {:>9} {:>7} {:>10}",
        "TOTAL", tm, tr, tl, tp, "", "", "", tb, tc, ta
    );
    if (layers_n, t) == (12, 512) {
        let want_tot = (96usize, 45usize, 57usize, 12usize, 1_083_456usize);
        let got_tot = (tm, tr, tl, tp, tb);
        if got_tot != want_tot {
            findings.push(format!("TOTAL: engine {:?} != memo {:?}", got_tot, want_tot));
        }
        if findings.is_empty() {
            println!("  memo §1.1 reconciliation: ALL ROWS MATCH (cols/trees/l/pad/depth/dt/bytes + totals)");
        } else {
            println!("  memo §1.1 reconciliation FINDINGS ({}):", findings.len());
            for f in &findings {
                println!("    FINDING: {f}");
            }
        }
    }
    println!(
        "  each pair serves: per side 2(D-1)+2(D-2) mask-open claims (g-hypersum + g-open per layer, Rp/Rq per interior layer, vs bk-wm/tm)"
    );
    println!(
        "  + wp (blinder-a), wq (member tensors + blinder-u — the ONLY claims over committed pass data; SiLU members add a Y-scaled a8 part), tp (bk-m + blinder-a), tq (blinder-u + statement table fold)"
    );

    // ---- The Stage-A replacement (memo §2.3 range -> zc_agg; §2.4 SiLU -> LogUp). ----
    println!("  STAGE-A REPLACEMENT (selector on; per memo §2.3/§2.4, shapes as validated by [UPERF3-EE]/[UPERF3-S]):");
    println!(
        "  {:<8} {:<26} {:>4} {:>7} {:>2} {:>2} {:>7} {:>7} {:>12}",
        "pair", "instance", "m", "n_log2", "w", "a", "rounds", "claims", "commit_vals"
    );
    let (mut sc, mut sv) = (0usize, 0usize);
    for sp in &specs {
        // Group the pair's members by shape (equal n_log2 per aggregate;
        // mixed-shape pairs get one aggregate per shape class).
        let mut shapes: Vec<((usize, usize), usize)> = Vec::new();
        for m in &sp.members {
            let key = (m.shape.rows, m.shape.cols);
            match shapes.iter_mut().find(|s| s.0 == key) {
                Some(s) => s.1 += 1,
                None => shapes.push((key, 1)),
            }
        }
        let w = sp.t_rows.trailing_zeros() as usize;
        for ((rows, cols), m) in &shapes {
            let n_el = rows * cols;
            let n_log2 = clog2(n_el);
            if sp.silu.is_some() {
                // LogUp-as-one-sumcheck per member column (the S2-validated
                // form): rounds = n_log2 each; commits h (n_el x 16 coords
                // per column) + keeps the m multiplicities (256/tree).
                let claims = m * 2 + 2; // h(x*), key(x*) per col + m-claim + sum-equality
                let commit = m * (n_el << 4);
                println!(
                    "  {:<8} {:<26} {:>4} {:>7} {:>2} {:>2} {:>7} {:>7} {:>12}",
                    sp.name(),
                    "LOGUP h+m (Had prover)",
                    m,
                    n_log2,
                    "-",
                    "-",
                    m * n_log2,
                    claims,
                    commit
                );
                sc += claims;
                sv += commit;
            } else {
                let (a, rounds, claims) = zc_agg_plan(*m, n_log2, w);
                let commit = m * w * (1usize << n_log2);
                println!(
                    "  {:<8} {:<26} {:>4} {:>7} {:>2} {:>2} {:>7} {:>7} {:>12}",
                    sp.name(),
                    format!("ZC-AGG e0=1 sign-binary"),
                    m,
                    n_log2,
                    w,
                    a,
                    rounds,
                    claims,
                    commit
                );
                sc += claims;
                sv += commit;
            }
        }
    }
    println!(
        "  {:<8} {:<26} {:>4} {:>7} {:>2} {:>2} {:>7} {:>7} {:>12}",
        "TOTAL", "", "", "", "", "", "", sc, sv
    );
    println!(
        "  replaced committed aux: bk-m/bl/wm/tm = {ta} values -> planes/h/m = {sv} values (planes i8-class bits; h rides the ACT group as the blinders did)"
    );
    println!(
        "  served-claim swap: {tc} descent-derived claims -> {sc} MLE claims at the aggregates' points (+ the aggregate round polys on the wire in place of {tb} descent B)"
    );
    // ---- The commit-side growth, in digit rings (the finding the memo's
    // ---- "commit nothing new" line does not carry for the q31 pass:
    // ---- width-planes must be committed to close the off-table gap, and
    // ---- h's K coordinates commit at the blinder class l0_q). ----
    let dring = |values: usize, l0: usize| values.div_ceil(128) * l0;
    let (mut add_plane_r, mut add_h_r) = (0usize, 0usize);
    for sp in &specs {
        let mut shapes: Vec<((usize, usize), usize)> = Vec::new();
        for m in &sp.members {
            let key = (m.shape.rows, m.shape.cols);
            match shapes.iter_mut().find(|s| s.0 == key) {
                Some(s) => s.1 += 1,
                None => shapes.push((key, 1)),
            }
        }
        let w = sp.t_rows.trailing_zeros() as usize;
        for ((rows, cols), m) in &shapes {
            let n_log2 = ring::stage_a::clog2(rows * cols);
            if sp.silu.is_some() {
                add_h_r += dring(m * (1usize << n_log2) * ring::kfield::K_DEG, reg.l0_q);
            } else {
                add_plane_r += dring(m * w * (1usize << n_log2), 1);
            }
        }
    }
    let mut retired_r = 0usize;
    for base in &reg.aux_base {
        for &ti in base.iter() {
            retired_r += reg.ga.tensors[ti].n_digit_rings();
        }
    }
    println!(
        "  ACT-GROUP DIGIT RINGS [COUNTED approx, per-tensor padding folded]: today n_0 = {} (incl. {} aux rings retired); Stage-A adds planes ~{} + h(l0_q={}) ~{} rings -> n_0 ~{}",
        reg.ga.n_digit_rings,
        retired_r,
        add_plane_r,
        reg.l0_q,
        add_h_r,
        reg.ga.n_digit_rings - retired_r + add_plane_r + add_h_r
    );
    println!("  [COUNTED from the engine structures; no proving in this arm]");
}

// ===========================================================================
// [UPERF3-JJ] U-PERF3 round 6, lane JJ — SPIKE X-S1: the integer softmax
// chain through the real claim machinery (U_PERF3_ATTENTION_STATEMENT_
// DESIGN.md §5.3; semantics ATTENTION_INTEGER_SPEC.md §2.4-2.5; value
// oracle scripts/attention_spec_spike.py). ADDITIVE: nothing here is
// called by any shipped path; frozen registries unmoved (the exp member
// is lane-local in ring/attn_softmax.rs — open freeze question in the
// ledger).
//
//   uperf-x chain [seed] [t]    — the value chain + digests (acceptance c)
//   uperf-x prove [seed] [t]    — the committed chain, honest ACCEPT (a)
//   uperf-x battery             — the AT-O8/O9 tamper legs (b)
//   uperf-x stage-a [seed] [t]  — the Stage-A range-fact leg (d)
// ===========================================================================

fn uperf_x_main(args: &[String]) {
    match args.first().map(String::as_str) {
        Some("chain") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(161);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(512);
            uperf_x_chain_inner(seed, t, false);
        }
        Some("chain-cal") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(161);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(512);
            uperf_x_chain_inner(seed, t, true);
        }
        Some("prove") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(161);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(512);
            uperf_x_prove(seed, t);
        }
        Some("battery") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(161);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(64);
            uperf_x_battery(seed, t);
        }
        Some("prove-cal") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(161);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(512);
            uperf_x_prove_cal(seed, t);
        }
        Some("stage-a") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(161);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(512);
            uperf_x_stage_a(seed, t);
        }
        // [UPERF3-NN] X1 arms (round 8; toy shape T 16 value / T 32 proven).
        Some("entries") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(1611);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(16);
            uperf_x_entries(seed, t);
        }
        Some("layer-chain") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(1611);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(16);
            uperf_x_layer_chain(seed, t);
        }
        Some("pw-battery") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(1611);
            uperf_x_pw_battery(seed);
        }
        Some("head-prove") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(1611);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(32);
            uperf_x_head_prove(seed, t);
        }
        Some("head-battery") => {
            let seed: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(1611);
            let t: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(32);
            uperf_x_head_battery(seed, t);
        }
        _ => {
            eprintln!("usage: ring_matmul uperf-x chain [seed] [t] | prove [seed] [t] | prove-cal [seed] [t] | battery [seed] [t] | stage-a [seed] [t]");
            eprintln!("       ring_matmul uperf-x entries [seed] [t] | layer-chain [seed] [t] | pw-battery [seed] | head-prove [seed] [t] | head-battery [seed] [t]   [UPERF3-NN]");
            std::process::exit(2);
        }
    }
}

/// [UPERF3-JJ] rung 1 — `uperf-x chain [seed] [t]` (and the rung-5
/// `chain-cal` twin at the measured eS = -2 on calibrated-shaped s8):
/// the value chain, printed in the exact format of the Python side
/// (scratchpad xs1_chain_ref.py driving the oracle's softmax_int) for
/// a byte-for-byte diff. Acceptance (c).
fn uperf_x_chain_inner(seed: u64, t: usize, cal: bool) {
    use ring::attn_softmax::{
        E_S, F_E, F_P, HEAD_DIM, calibrated_s8, derive_chain, exp_member, seeded_s8,
        tensor_digest,
    };
    use sha2::{Digest, Sha256};
    let es = if cal { -2 } else { E_S };
    let hex = |d: &[u8; 32]| d.iter().map(|b| format!("{b:02x}")).collect::<String>();
    let (tab, tab_dig) = exp_member(es);
    let (_, tab_dig_m2) = exp_member(if es == -1 { -2 } else { -1 });
    let s8 = if cal { calibrated_s8(seed, t * t) } else { seeded_s8(seed, t * t) };
    let ch = derive_chain(t, &s8, &tab);
    println!(
        "[UPERF3-JJ] chain{} seed {seed} t {t} eS {es} d_h {HEAD_DIM} fE {F_E} fP {F_P}",
        if cal { "-cal" } else { "" }
    );
    println!("  exp-member(eS {es})  {}", hex(&tab_dig));
    println!("  exp-member(eS {})  {}", if es == -1 { -2 } else { -1 }, hex(&tab_dig_m2));
    let tensors: [(&str, &[i64]); 9] = [
        ("s8", &ch.s8), ("m", &ch.m), ("zsel", &ch.zsel), ("d", &ch.d), ("E", &ch.e),
        ("Sum", &ch.sum), ("P", &ch.p), ("rho", &ch.rho), ("sigma", &ch.sigma),
    ];
    let mut combined = Sha256::new();
    for (name, v) in tensors {
        let d = tensor_digest(v);
        combined.update(d);
        println!("  {name:<6} {}", hex(&d));
    }
    let cd: [u8; 32] = combined.finalize().into();
    println!("  CHAIN  {}", hex(&cd));
}

// ---------------------------------------------------------------------------
// [UPERF3-JJ] rung 2 — the committed chain + the honest proof through the
// as-built machinery (the u3_layer_run wave pattern): 9 committed entries,
// the d-pin (PW-3), six thin-sumcheck gates with real PW-3/PW-4 public
// weights, six lookup/range instances (incl. the REAL fused (d, E)
// LookupAt pair against the lane-local frozen exp member), pins -> psi
// claims -> masked wave split -> ct waves + closing, ONE rolling
// transcript. Gate order is FIXED (F5: no ordering freedom):
//   G1 F-one (row-sum-1)   G2 F-hit (attainment ZC)   G3 Sum (masked row
//   sum, PW-3)             G4 DIV (broadcast divisor, PW-4)
//   G5 sigma-def           G6 off-support batch pin   G7 the d-pin (PW-3)
//   then the instances: exp pair, d-w8, zsel-w1, P-w10, rho-w, sigma-w.

const XS_ENTRIES: [&str; 9] = ["s8", "m", "zsel", "d", "E", "Sum", "P", "rho", "sigma"];

fn xs_entry_len(e: usize, t: usize) -> usize {
    match XS_ENTRIES[e] {
        "m" | "Sum" => t,
        _ => t * t,
    }
}

fn xs_entry_values<'a>(e: usize, ch: &'a ring::attn_softmax::SoftmaxChain) -> &'a [i64] {
    match XS_ENTRIES[e] {
        "s8" => &ch.s8,
        "m" => &ch.m,
        "zsel" => &ch.zsel,
        "d" => &ch.d,
        "E" => &ch.e,
        "Sum" => &ch.sum,
        "P" => &ch.p,
        "rho" => &ch.rho,
        "sigma" => &ch.sigma,
        _ => unreachable!(),
    }
}

/// The derived remainder width: wrho = fE + log2(T) (18 at the contract
/// T = 512 — the oracle's w18; lane-local derivation at other T,
/// ledger-recorded).
fn xs_wrho(t: usize) -> usize {
    (ring::attn_softmax::F_E as usize) + (usize::BITS as usize - 1 - t.leading_zeros() as usize)
}

/// The chain derivation with tamper knobs (mask_shift for the
/// shifted-mask leg; m_delta = (row, +-1) for the m legs; exp table as
/// given — the wrong-member leg passes the eS = -2 member). The honest
/// call (shift 0, no delta, eS -1 member) bit-equals
/// ring::attn_softmax::derive_chain (asserted by the caller).
fn xs_derive(
    t: usize,
    s8: &[i64],
    tab: &[i64; 256],
    mask_shift: i64,
    m_delta: Option<(usize, i64)>,
) -> ring::attn_softmax::SoftmaxChain {
    use ring::attn_softmax::{F_E, F_P, SoftmaxChain};
    let mask = |r: usize, c: usize| (c as i64) <= (r as i64) + mask_shift;
    let sm_at = |r: usize, c: usize| if mask(r, c) { s8[r * t + c] } else { -127 };
    let mut m = vec![0i64; t];
    let mut zsel = vec![0i64; t * t];
    let mut d = vec![0i64; t * t];
    let mut e = vec![0i64; t * t];
    let mut sum = vec![0i64; t];
    let mut p = vec![0i64; t * t];
    let mut rho = vec![0i64; t * t];
    let mut sigma = vec![0i64; t * t];
    for r in 0..t {
        let mut mx = i64::MIN;
        let mut arg = 0usize;
        for c in 0..t {
            let v = sm_at(r, c);
            if v > mx {
                mx = v;
                arg = c;
            }
        }
        if let Some((tr_, delta)) = m_delta {
            if tr_ == r {
                mx += delta;
            }
        }
        m[r] = mx;
        zsel[r * t + arg] = 1;
        let mut s_acc = 0i64;
        for c in 0..t {
            let dd = mx - sm_at(r, c);
            d[r * t + c] = dd;
            // Tampered chains may push dd outside [0, 256): the table
            // read wraps (& 255) so the rest of the chain stays
            // self-consistent — the RANGE/LOOKUP gates see the raw dd.
            let ev = tab[(dd & 255) as usize];
            e[r * t + c] = ev;
            if mask(r, c) {
                s_acc += ev;
            }
        }
        assert!(s_acc >= 1, "empty support row");
        let _ = F_E;
        sum[r] = s_acc;
        for c in 0..t {
            if mask(r, c) {
                let num = e[r * t + c] << F_P;
                let q = num / s_acc;
                let rr = num - q * s_acc;
                p[r * t + c] = q;
                rho[r * t + c] = rr;
                sigma[r * t + c] = s_acc - 1 - rr;
            }
        }
    }
    SoftmaxChain { t, s8: s8.to_vec(), m, zsel, d, e, sum, p, rho, sigma }
}

/// One lookup/range instance of the spike chain (the U3Inst shape).
#[derive(Clone)]
struct XsInst {
    name: String,
    entry: usize,
    pair: Option<usize>,
    offset: i64,
    t_rows: usize,
    /// Some(eS) for the exp fused pair — the STATEMENT member.
    exp_es: Option<i32>,
    dw: usize,
    dt: usize,
    base_m: usize,
    m_c: usize,
    idx_bl: usize,
    base_wm: usize,
    base_tm: usize,
    wm_c: usize,
    tm_c: usize,
}

fn xs_instances(t: usize, es: i32) -> Vec<XsInst> {
    let n2 = t * t;
    let wrho = xs_wrho(t);
    let mk = |name: &str, entry: usize, pair: Option<usize>, t_rows: usize, exp_es: Option<i32>| XsInst {
        name: name.into(),
        entry,
        pair,
        offset: 0,
        t_rows,
        exp_es,
        dw: bf_dw_for(n2),
        dt: ((t_rows.trailing_zeros() as usize) + 1).max(4),
        base_m: usize::MAX,
        m_c: 0,
        idx_bl: usize::MAX,
        base_wm: usize::MAX,
        base_tm: usize::MAX,
        wm_c: 0,
        tm_c: 0,
    };
    // Transcript order = the spec's chain order: the w8/w1 range facts
    // (F-dom, F-bin), THEN the exp lookup, then the division-side widths.
    vec![
        mk("rng-d-w8", 3, None, 256, None),
        mk("rng-zsel-w1", 2, None, 2, None),
        mk("exp-pair", 3, Some(4), 256, Some(es)),
        mk("rng-P-w10", 6, None, 1 << 10, None),
        mk(&format!("rng-rho-w{wrho}"), 7, None, 1 << wrho, None),
        mk(&format!("rng-sigma-w{wrho}"), 8, None, 1 << wrho, None),
    ]
}

struct XsLayout {
    entry_base: Vec<usize>,
    entry_cms: Vec<usize>,
    insts: Vec<XsInst>,
    n_data: usize,
    base_pad: usize,
    base_closing_g: usize,
    base_wave_g: usize,
    n_commits: usize,
    c2_max: usize,
    wave_g_groups: usize,
    closing_g_groups: usize,
    plan: ring::ct_engine::WavePlan,
    pad_layout: ring::ct_engine::WavePadLayout,
}

fn xs_layout(t: usize, es: i32, shape: CommitShape, q: u64) -> XsLayout {
    use ring::ct_engine::{WavePadLayout, plan_waves};
    use ring::gkr_masked::mask_coeff_counts;
    use ring::kfield::K_DEG;
    let per = shape.msg_r * D;
    let mut entry_base = vec![0usize; XS_ENTRIES.len()];
    let mut entry_cms = vec![0usize; XS_ENTRIES.len()];
    let mut cursor = 0usize;
    for e in 0..XS_ENTRIES.len() {
        // Tails allowed (m/Sum are T-length): the pack pads with zeros;
        // pins/instances address only the first n positions.
        entry_base[e] = cursor;
        entry_cms[e] = xs_entry_len(e, t).div_ceil(per);
        cursor += entry_cms[e];
    }
    let kel_cms = |n_kel: usize| (n_kel * K_DEG).div_ceil(per).max(1);
    let mut insts = xs_instances(t, es);
    for inst in insts.iter_mut() {
        let (gw, rw) = mask_coeff_counts(inst.dw, 0);
        let (gt, rt) = mask_coeff_counts(inst.dt, 0);
        inst.wm_c = kel_cms(gw + rw);
        inst.tm_c = kel_cms(gt + rt);
        inst.m_c = inst.t_rows.div_ceil(per).max(1);
        inst.base_m = cursor;
        inst.idx_bl = cursor + inst.m_c;
        inst.base_wm = cursor + inst.m_c + 1;
        inst.base_tm = inst.base_wm + inst.wm_c;
        cursor += inst.m_c + 1 + inst.wm_c + inst.tm_c;
        assert!(ring::gkr::ceiling_gate_ok(1u64 << inst.dw, q));
        assert!(ring::gkr::ceiling_gate_ok(1u64 << inst.dt, q));
    }
    let n_data = cursor;
    let wave_g_groups = UR1_PIN_COPIES.div_ceil(shape.msg_r);
    let c2_max = ur1_c2_max_commits(q, shape);
    let data_cap = c2_max - 1 - wave_g_groups;
    let plan = plan_waves(n_data, &[], data_cap).expect("group-free first-fit plan");
    let n_waves = plan.waves.len();
    let pad_layout =
        WavePadLayout::derive(UR1_PIN_COPIES, (0..n_waves).collect(), n_waves, shape.msg_r)
            .expect("pad layout derives");
    let closing_g_groups =
        if pad_layout.has_pads() { UR1_PIN_COPIES.div_ceil(shape.msg_r) } else { 0 };
    let base_pad = n_data;
    let base_closing_g = base_pad + pad_layout.n_pad_cms;
    let base_wave_g = base_closing_g + closing_g_groups;
    let n_commits = base_wave_g + n_waves * wave_g_groups;
    XsLayout {
        entry_base,
        entry_cms,
        insts,
        n_data,
        base_pad,
        base_closing_g,
        base_wave_g,
        n_commits,
        c2_max,
        wave_g_groups,
        closing_g_groups,
        plan,
        pad_layout,
    }
}

/// The spike statement bytes (digest = uk8_sha): shape + spec params +
/// the STATEMENT exp member digest + the causal-mask convention + the
/// entry commitment digests. The witness tags bind exactly as in the
/// bf/u3 pass statements.
fn xs_statement_bytes(t: usize, es: i32, commit_digests: &[Vec<u8>], crs_hash: &[u8]) -> Vec<u8> {
    use ring::attn_softmax::exp_member;
    let (_, dg) = exp_member(es);
    xs_statement_bytes_tagged(b"uperf3-jj-xs1-v1", b"", t, es, &dg, commit_digests, crs_hash)
}

/// [UPERF3-NN] The X-S1 statement bytes, parameterized (tag + extra
/// statement data + the member digest as an argument) so the lane-NN
/// head-indexed statements ride the same shape; the JJ entry point
/// above keeps its exact bytes (uperf-x battery digest is the guard).
fn xs_statement_bytes_tagged(
    tag: &[u8],
    extra: &[u8],
    t: usize,
    es: i32,
    member_digest: &[u8; 32],
    commit_digests: &[Vec<u8>],
    crs_hash: &[u8],
) -> Vec<u8> {
    use ring::attn_softmax::{F_E, F_P, HEAD_DIM};
    let mut b: Vec<u8> = tag.to_vec();
    b.extend(crs_hash);
    for v in [t, HEAD_DIM, xs_wrho(t)] {
        b.extend((v as u64).to_le_bytes());
    }
    for v in [es, F_E as i32, F_P as i32] {
        b.extend(v.to_le_bytes());
    }
    b.extend(b"mask:causal-lower-tri;offsupport-reads:-127;offsupport-aux:0");
    b.extend(member_digest);
    b.extend(extra);
    for d in commit_digests {
        b.extend(d);
    }
    b
}

fn xs_commit_entries(
    ch: &ring::attn_softmax::SoftmaxChain,
    t: usize,
    shape: CommitShape,
    crs: &ring::commit::RingCrs,
    path: &KernelPath,
    wit_tag: &str,
) -> (Vec<Vec<u8>>, BfCommitted) {
    let zq = ring_ctx_q8().zq;
    let per = shape.msg_r * D;
    let mut entry_digests = Vec::with_capacity(XS_ENTRIES.len());
    let mut kept =
        BfCommitted { msgs: Vec::new(), rhos8: Vec::new(), t1s: Vec::new(), t2s: Vec::new() };
    for e in 0..XS_ENTRIES.len() {
        let vals = xs_entry_values(e, ch);
        let n_cms = vals.len().div_ceil(per);
        let mut rng = ring::ProverRng::from_test_seed(
            wit_tag,
            &[(e as u64).to_le_bytes(), (t as u64).to_le_bytes()].concat(),
        );
        let mut cm_digests = Vec::with_capacity(n_cms);
        for g in 0..n_cms {
            let mut polys = vec![poly_zero(); shape.msg_r];
            for s in 0..shape.msg_r {
                for c in 0..D {
                    let idx = g * per + s * D + c;
                    if idx < vals.len() {
                        polys[s][c] = zq.to_mod(vals[idx]);
                    }
                }
            }
            let rho: Vec<Vec<i64>> = (0..shape.n_r).map(|_| rng_ternary_poly(&mut rng)).collect();
            let (t1, t2) = commit(path, crs, &polys, &rho);
            cm_digests.push(group_digest(&t1, &t2));
            kept.msgs.push(polys);
            kept.rhos8.push(rho.iter().flat_map(|p| p.iter().map(|&x| x as i8)).collect());
            kept.t1s.push(t1);
            kept.t2s.push(t2);
        }
        entry_digests.push(group_list_digest(&cm_digests));
    }
    (entry_digests, kept)
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum XsTamper {
    None,
    /// m[t0] += 1 (chain rederived self-consistently; zsel stays at the
    /// argmax). PRE-REGISTERED GATE: G2 F-hit (zsel o d = 1 != 0).
    MOverstate,
    /// m[t0] -= 1 (d = -1 at the argmax). PRE-REGISTERED GATE: the
    /// rng-d-w8 root cross-check (F-dom's lower edge); the exp pair's
    /// root cross-check and G2 also fire — recorded, not the gate.
    MUnderstate,
    /// A second zsel bit at a TIED max position (d = 0 there).
    /// PRE-REGISTERED GATE: G1 F-one (row-sum 2 != 1).
    ZselTwoHot,
    /// zsel moved to an off-support column on a row with m > -127.
    /// PRE-REGISTERED GATE: G2 F-hit (d off-support = m + 127 > 0).
    ZselOffsupport,
    /// P at one off-support position set nonzero. PRE-REGISTERED GATE:
    /// G6 the off-support batch zero-check.
    OffsupportP,
    /// The prover derives chain + ITS weight tables under a mask
    /// shifted by +1. PRE-REGISTERED GATE: G3's PW-3 weight-MLE check
    /// (the first mask-consuming public-weight gate in transcript
    /// order); every later mask gate + the d-pin waves also fire.
    ShiftedMask,
    /// Chain + exp instance run the eS = -2 member consistently; the
    /// statement declares eS = -1. PRE-REGISTERED GATE: the waves (the
    /// verifier folds the STATEMENT table into the exp tq leaf pin).
    WrongExpMember,
}

struct XsVerdict {
    statement_ok: bool,
    fone_ok: bool,
    fhit_ok: bool,
    sum_ok: bool,
    div_ok: bool,
    sigdef_ok: bool,
    offsup_ok: bool,
    roots_ok: Vec<bool>,
    sum_gate_ok: bool,
    waves_ok: bool,
    first_bad_wave: Option<usize>,
    closing_ok: bool,
}

impl XsVerdict {
    fn accept(&self) -> bool {
        self.statement_ok
            && self.fone_ok
            && self.fhit_ok
            && self.sum_ok
            && self.div_ok
            && self.sigdef_ok
            && self.offsup_ok
            && self.roots_ok.iter().all(|&b| b)
            && self.sum_gate_ok
            && self.waves_ok
            && self.closing_ok
    }
    fn first_failed_gate(&self, insts: &[XsInst]) -> String {
        if !self.statement_ok {
            return "statement".into();
        }
        for (ok, name) in [
            (self.fone_ok, "G1 F-one (row-sum-1)"),
            (self.fhit_ok, "G2 F-hit (attainment zero-check)"),
            (self.sum_ok, "G3 Sum (masked row sum, PW-3 weight check)"),
            (self.div_ok, "G4 DIV (broadcast-divisor zero-check, PW-4)"),
            (self.sigdef_ok, "G5 sigma-def"),
            (self.offsup_ok, "G6 off-support batch zero-check"),
        ] {
            if !ok {
                return name.into();
            }
        }
        for (i, &ok) in self.roots_ok.iter().enumerate() {
            if !ok {
                return format!("{} root cross-check", insts[i].name);
            }
        }
        if !self.sum_gate_ok {
            return "masked-claims sum gate".into();
        }
        if !self.waves_ok {
            return format!("waves (pin claims; first bad wave {:?})", self.first_bad_wave);
        }
        if !self.closing_ok {
            return "closing round".into();
        }
        "ACCEPT".into()
    }
}

/// [UPERF3-JJ] The X-S1 committed-chain run: derive (with tamper),
/// commit, prove on ONE rolling transcript, verify. Returns the verdict
/// + (commit_s, prove_s, verify_s, n_pins, n_waves).
fn xs1_run(
    seed: u64,
    t: usize,
    es: i32,
    cal: bool,
    tamper: XsTamper,
    quiet: bool,
) -> (XsVerdict, [f64; 3], usize, usize) {
    use ring::attn_softmax::{calibrated_s8, exp_member, seeded_s8};
    let s8 = if cal { calibrated_s8(seed, t * t) } else { seeded_s8(seed, t * t) };
    let (tab_stmt, member_digest) = exp_member(es);
    let (tab_wrong, _) = exp_member(if es == -1 { -2 } else { -1 });
    let cfg = XsCfg {
        label: "uperf3-jj-xs1",
        stmt_tag: b"uperf3-jj-xs1-v1",
        stmt_extra: b"",
        wit_tag: "uperf3-jj-wit",
        session_tag: "uperf3-jj-session",
        es,
        tab_stmt: &tab_stmt,
        member_digest,
        tab_wrong: &tab_wrong,
    };
    xs1_run_core(seed, t, &s8, &cfg, tamper, quiet)
}

/// [UPERF3-NN] The X-S1 rig parameterized over the s8 source, the exp
/// members and the statement/transcript tags (behavior-preserving
/// extraction: the JJ wrapper above reproduces the round-6 bytes
/// exactly — uperf-x battery digest be89d5da.. is the guard). Lane NN
/// drives it per (head) with the LAYER-derived s8 blocks and
/// head-tagged statements.
struct XsCfg<'a> {
    label: &'a str,
    stmt_tag: &'a [u8],
    stmt_extra: &'a [u8],
    wit_tag: &'a str,
    session_tag: &'a str,
    es: i32,
    tab_stmt: &'a [i64; 256],
    member_digest: [u8; 32],
    tab_wrong: &'a [i64; 256],
}

fn xs1_run_core(
    seed: u64,
    t: usize,
    s8_in: &[i64],
    cfg: &XsCfg,
    tamper: XsTamper,
    quiet: bool,
) -> (XsVerdict, [f64; 3], usize, usize) {
    use ring::attn_softmax::{F_P, derive_chain};
    use ring::ct_engine::{
        CtClaim, StdOpening, WavePads, closing_round_claims, ct_h0, derive_ct_round_params,
        draw_wave_pads, pack_wave_pads, prove_ct_round, sample_ct_masks,
        split_claims_prover_masked, split_claims_verifier_masked, verify_ct_round,
    };
    use ring::gkr::{eq_eval, eq_table};
    use ring::gkr_masked::{
        BlinderSet, DescentEnd, MaskedDescentProof, blinded_table_tree, blinded_witness_tree,
        blinder_positions, draw_masks, masked_gkr_prove, masked_gkr_verify, table_row_positions,
        witness_leaf_positions, zero_masks,
    };
    use ring::kfield::{K_DEG, KElem, KField};
    use ring::lookup::{PinTerm, PinnedValue, derive_pin_psi, fuse_pair, multiplicities, pin_claims};
    use ring::sumcheck::{LkpTranscript, SumcheckProof, sumcheck_prove, sumcheck_verify};

    assert!(t.is_power_of_two() && t >= 32, "xs1: T a power of two >= 32");
    let ctx_ring = ring_ctx_q8();
    let kf = KField::new(&ctx_ring);
    let zq = ctx_ring.zq;
    let q = zq.q;
    let shape = CommitShape { kappa: 8, n_r: 26, msg_r: 8 };
    let msg_r = shape.msg_r;
    let per = msg_r * D;
    let kpc = per / K_DEG;
    let crs = expand_crs(shape, q, 0x0A11);
    let zero = kf.zero();
    let one = kf.one();
    let lgt = t.trailing_zeros() as usize;
    let lv = 2 * lgt; // T x T hypercube variables
    let n2 = t * t;

    // ---- The witness chain (honest, then the tamper knob). --------------
    let s8: Vec<i64> = s8_in.to_vec();
    assert_eq!(s8.len(), n2);
    let es = cfg.es;
    let tab_stmt = cfg.tab_stmt;
    let tab_wrong = cfg.tab_wrong;
    let honest = derive_chain(t, &s8, tab_stmt);
    {
        // Rung-1 tie: the rig's knobbed derivation at honest knobs
        // bit-equals the value oracle's chain.
        let d0 = xs_derive(t, &s8, tab_stmt, 0, None);
        assert_eq!(d0.m, honest.m);
        assert_eq!(d0.p, honest.p);
        assert_eq!(d0.sigma, honest.sigma);
    }
    let t0_row = t / 2;
    // MUnderstate rides the STRONGEST cheater: a row where max - 1 is
    // also attained, so zsel can move to a d = 0 position and the
    // reject isolates to F-dom (the d range/lookup gates) — the spec's
    // "understating m makes some d negative" argument, adversarially.
    // [UPERF3-NN] computed lazily (only the leg that needs it), so
    // honest runs on arbitrary s8 sources never require such a row.
    let mu_row_find = || {
        (1..t)
            .rev()
            .find(|&r| {
                let mx = honest.m[r];
                mx > -127 && (0..=r).any(|c| s8[r * t + c] == mx - 1)
            })
            .expect("no row supports the m-understate leg at this seed/T")
    };
    let mut ch = match tamper {
        XsTamper::None => honest.clone(),
        XsTamper::MOverstate => xs_derive(t, &s8, tab_stmt, 0, Some((t0_row, 1))),
        XsTamper::MUnderstate => {
            let mu_row = mu_row_find();
            xs_derive(t, &s8, tab_stmt, 0, Some((mu_row, -1)))
        }
        XsTamper::ShiftedMask => xs_derive(t, &s8, tab_stmt, 1, None),
        XsTamper::WrongExpMember => xs_derive(t, &s8, tab_wrong, 0, None),
        XsTamper::ZselTwoHot | XsTamper::ZselOffsupport | XsTamper::OffsupportP => honest.clone(),
    };
    match tamper {
        XsTamper::MUnderstate => {
            let r = mu_row_find();
            let arg = (0..t).find(|&c| ch.zsel[r * t + c] == 1).unwrap();
            let c2 = (0..t).find(|&c| ch.d[r * t + c] == 0).expect("d = 0 position exists");
            ch.zsel[r * t + arg] = 0;
            ch.zsel[r * t + c2] = 1;
        }
        XsTamper::ZselTwoHot => {
            // A row with a TIE: two support positions attaining m.
            let mut done = false;
            for r in (1..t).rev() {
                let hits: Vec<usize> =
                    (0..=r).filter(|&c| ch.s8[r * t + c] == ch.m[r]).collect();
                if hits.len() >= 2 {
                    let second = hits.iter().find(|&&c| ch.zsel[r * t + c] == 0).unwrap();
                    ch.zsel[r * t + second] = 1;
                    done = true;
                    break;
                }
            }
            assert!(done, "no tied row found for the two-hot leg");
        }
        XsTamper::ZselOffsupport => {
            let r = t0_row;
            assert!(ch.m[r] > -127);
            let arg = (0..t).find(|&c| ch.zsel[r * t + c] == 1).unwrap();
            ch.zsel[r * t + arg] = 0;
            ch.zsel[r * t + (t - 1)] = 1; // t-1 > t/2: off-support
        }
        XsTamper::OffsupportP => {
            ch.p[t0_row * t + t0_row + 1] = 3;
        }
        _ => {}
    }
    // The prover's OWN mask (the shifted-mask leg derives + weights with
    // it); the verifier always uses the statement's causal mask.
    let p_shift: i64 = if tamper == XsTamper::ShiftedMask { 1 } else { 0 };
    let p_mask = move |r: usize, c: usize| (c as i64) <= (r as i64) + p_shift;
    let v_mask = |r: usize, c: usize| c <= r;
    // The prover's table for the exp instance (wrong-member leg forges
    // consistently; the verifier folds the STATEMENT member).
    let tab_prover: &[i64; 256] =
        if tamper == XsTamper::WrongExpMember { tab_wrong } else { tab_stmt };

    // ---- Commit pass (entries + aux; ALL before any challenge). ---------
    let t_commit = Instant::now();
    let rp_probe = derive_ct_round_params(q, shape, ur1_c2_max_commits(q, shape), 0, 0, true);
    let a1p = build_a1_paths(&crs, rp_probe.sigma, isqrt_u128(rp_probe.bound_sq));
    let path = KernelPath::A1(&a1p);
    let (entry_digests, kept) = xs_commit_entries(&ch, t, shape, &crs, &path, cfg.wit_tag);
    let ml = xs_layout(t, es, shape, q);
    let BfCommitted { mut msgs, mut rhos8, mut t1s, mut t2s } = kept;

    let mut rng = ring::ProverRng::from_test_seed(
        cfg.session_tag,
        &[seed.to_le_bytes(), (t as u64).to_le_bytes()].concat(),
    );
    let mut pads_live: Option<WavePads> = Some(draw_wave_pads(&mut rng, q, &ml.pad_layout));
    let pack_scalar_chunk = |vals: &[u64]| -> Vec<Poly> {
        assert!(vals.len() <= per);
        let mut polys = vec![poly_zero(); msg_r];
        for (i, &v) in vals.iter().enumerate() {
            polys[i / D][i % D] = v;
        }
        polys
    };
    let pack_kelems = |kelems: &[KElem]| -> Vec<Vec<Poly>> {
        let mut flat: Vec<u64> = Vec::with_capacity(kelems.len() * K_DEG);
        for e in kelems {
            flat.extend_from_slice(&e[..]);
        }
        (0..flat.len().div_ceil(per).max(1))
            .map(|g| {
                (0..msg_r)
                    .map(|s| {
                        (0..D)
                            .map(|c| {
                                let idx = g * per + s * D + c;
                                if idx < flat.len() { flat[idx] } else { 0 }
                            })
                            .collect()
                    })
                    .collect()
            })
            .collect()
    };
    let mut push_commit = |mv: Vec<Poly>,
                           rng: &mut ring::ProverRng,
                           msgs: &mut Vec<Vec<Poly>>,
                           rhos8: &mut Vec<Vec<i8>>,
                           t1s: &mut Vec<Vec<Poly>>,
                           t2s: &mut Vec<Vec<Poly>>| {
        let rho: Vec<Vec<i64>> = (0..shape.n_r).map(|_| rng_ternary_poly(rng)).collect();
        let (t1, t2) = commit(&path, &crs, &mv, &rho);
        msgs.push(mv);
        rhos8.push(rho.iter().flat_map(|p| p.iter().map(|&x| x as i8)).collect());
        t1s.push(t1);
        t2s.push(t2);
    };
    struct XsInstMat {
        w_col: Vec<ring::kfield::KElem>,
        tab_k: Vec<ring::kfield::KElem>,
        m_k: Vec<ring::kfield::KElem>,
        masks_w: Option<ring::gkr_masked::MaskSet>,
        masks_t: Option<ring::gkr_masked::MaskSet>,
        bl_w: ring::gkr_masked::BlinderSet,
        bl_t: ring::gkr_masked::BlinderSet,
    }
    let mut inst_mat: Vec<XsInstMat> = Vec::with_capacity(ml.insts.len());
    for inst in &ml.insts {
        let vals = xs_entry_values(inst.entry, &ch);
        let (w_col, tab_k): (Vec<KElem>, Vec<KElem>) = if inst.exp_es.is_some() {
            let pair = xs_entry_values(inst.pair.unwrap(), &ch);
            let w = vals
                .iter()
                .zip(pair.iter())
                .map(|(&x, &y)| fuse_pair(&kf, zq.to_mod(x), zq.to_mod(y)))
                .collect();
            let tk = tab_prover
                .iter()
                .enumerate()
                .map(|(dd, &ev)| fuse_pair(&kf, dd as u64, zq.to_mod(ev)))
                .collect();
            (w, tk)
        } else {
            let w = vals.iter().map(|&x| kf.embed(zq.to_mod(x + inst.offset))).collect();
            let tk = (0..inst.t_rows as u64).map(|j| kf.embed(j)).collect();
            (w, tk)
        };
        let m_k: Vec<KElem> = if inst.exp_es.is_some() {
            multiplicities(&kf, &w_col, &tab_k)
        } else {
            let mut hist = vec![0u64; inst.t_rows];
            for w in &w_col {
                let c0 = w[0] as usize;
                if c0 < inst.t_rows {
                    hist[c0] += 1;
                }
            }
            hist.into_iter().map(|h| kf.embed(h)).collect()
        };
        let m_vals: Vec<u64> = m_k.iter().map(|e| e[0]).collect();
        for g in 0..inst.m_c {
            let lo = g * per;
            let hi = ((g + 1) * per).min(m_vals.len());
            push_commit(
                pack_scalar_chunk(&m_vals[lo..hi]),
                &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s,
            );
        }
        let bw = BlinderSet::draw(&kf, &mut rng);
        let mut bt = BlinderSet::draw(&kf, &mut rng);
        bt.solve_mass(&kf, &bw.mass(&kf));
        let blinder_kelems: Vec<KElem> = {
            let mut v = Vec::with_capacity(16);
            for b in [&bw.tl, &bw.tr, &bw.f0, &bw.f1, &bt.tl, &bt.tr, &bt.f0, &bt.f1] {
                v.push(b.a.clone());
                v.push(b.u.clone());
            }
            v
        };
        let bl_msg = pack_kelems(&blinder_kelems);
        assert_eq!(bl_msg.len(), 1);
        push_commit(bl_msg.into_iter().next().unwrap(), &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        let mw = draw_masks(&kf, &mut rng, inst.dw, 0);
        let mt = draw_masks(&kf, &mut rng, inst.dt, 0);
        for mm in pack_kelems(&mw.flatten()) {
            push_commit(mm, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
        for mm in pack_kelems(&mt.flatten()) {
            push_commit(mm, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
        inst_mat.push(XsInstMat { w_col, tab_k, m_k, masks_w: Some(mw), masks_t: Some(mt), bl_w: bw, bl_t: bt });
    }
    assert_eq!(msgs.len(), ml.n_data);
    if ml.pad_layout.has_pads() {
        for mm in pack_wave_pads(&mut rng, q, msg_r, &ml.pad_layout, pads_live.as_ref().unwrap())
            .expect("pad packing")
        {
            push_commit(mm, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
    }
    for mm in sample_ct_masks(&mut rng, q, msg_r, if ml.closing_g_groups > 0 { UR1_PIN_COPIES } else { 0 }) {
        push_commit(mm, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
    }
    for _ in 0..ml.plan.waves.len() {
        for mm in sample_ct_masks(&mut rng, q, msg_r, UR1_PIN_COPIES) {
            push_commit(mm, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
    }
    assert_eq!(msgs.len(), ml.n_commits);
    let commit_s = t_commit.elapsed().as_secs_f64();

    let mut verdict = XsVerdict {
        statement_ok: true,
        fone_ok: true,
        fhit_ok: true,
        sum_ok: true,
        div_ok: true,
        sigdef_ok: true,
        offsup_ok: true,
        roots_ok: vec![true; ml.insts.len()],
        sum_gate_ok: true,
        waves_ok: true,
        first_bad_wave: None,
        closing_ok: true,
    };

    // ---- The statement + h0 (binds EVERY commitment). -------------------
    let st_bytes = xs_statement_bytes_tagged(
        cfg.stmt_tag, cfg.stmt_extra, t, es, &cfg.member_digest, &entry_digests, &crs.crs_hash,
    );
    let ctx = uk8_sha(&[&st_bytes]);
    let h0 = ct_h0(&crs, &ctx, &t1s, &t2s, &[]);

    // ---- Shared public helpers (prover uses p_mask, verifier v_mask). ---
    let lg2 = |n: usize| usize::BITS as usize - (n - 1).leading_zeros() as usize;
    assert_eq!(lg2(n2), lv);
    // eq-over-row-bits weight on position x: eq_r[row(x)] tables.
    let row_bcast = |eq_r: &[KElem]| -> Vec<KElem> {
        let mut w = Vec::with_capacity(n2);
        for r in 0..t {
            for _ in 0..t {
                w.push(eq_r[r].clone());
            }
        }
        w
    };
    let embed_col = |vals: &[i64]| -> Vec<KElem> {
        vals.iter().map(|&v| kf.embed(zq.to_mod(v))).collect()
    };
    // MLE of a mask-shaped public weight table at a point (the verifier's
    // PW-3/PW-4 evaluation; O(T^2) at spike scale).
    let pub_mle = |tab: &[KElem], point: &[KElem]| -> KElem {
        let ez = eq_table(&kf, point);
        let mut acc = kf.zero();
        for (x, w) in tab.iter().enumerate() {
            if !kf.is_zero(w) {
                acc = kf.add(&acc, &kf.mul(w, &ez[x]));
            }
        }
        acc
    };
    // Public mass sum_x eq(rho, x) * mask-ish(x) over a 0/1 indicator.
    let pub_mass = |eqt: &[KElem], ind: &dyn Fn(usize, usize) -> bool| -> KElem {
        let mut acc = kf.zero();
        for r in 0..t {
            for c in 0..t {
                if ind(r, c) {
                    acc = kf.add(&acc, &eqt[r * t + c]);
                }
            }
        }
        acc
    };
    let product2 = |kf: &KField, vals: &[KElem]| kf.mul(&vals[0], &vals[1]);
    let product3 = |kf: &KField, vals: &[KElem]| kf.mul(&kf.mul(&vals[0], &vals[1]), &vals[2]);
    // G4 combine: w * (P * Sumbc + L), degree 3.
    let div_combine = |kf: &KField, vals: &[KElem]| {
        kf.mul(&vals[0], &kf.add(&kf.mul(&vals[1], &vals[2]), &vals[3]))
    };

    // Pin builders shared verbatim by prover and verifier (weights are
    // the CALLER's public data; values ride the proof).
    let col_pin = |e: usize, weights_tab: &[KElem], value: &KElem| -> PinnedValue {
        let n_e = xs_entry_len(e, t);
        PinnedValue {
            terms: (0..ml.entry_cms[e])
                .map(|g| {
                    let lo = g * per;
                    let hi = ((g + 1) * per).min(n_e).min(weights_tab.len());
                    PinTerm::Scalar {
                        commit: ml.entry_base[e] + g,
                        coeff0: 0,
                        weights: weights_tab[lo..hi].to_vec(),
                    }
                })
                .collect(),
            value: value.clone(),
        }
    };

    // =====================================================================
    // PROVER (one rolling transcript from h0).
    // =====================================================================
    let t_prove = Instant::now();
    let mut tr = LkpTranscript::new(cfg.label, &h0);
    let mut pins: Vec<PinnedValue> = Vec::new();

    let zsel_k = embed_col(&ch.zsel);
    let d_k = embed_col(&ch.d);
    let e_k = embed_col(&ch.e);
    let p_k = embed_col(&ch.p);

    // ---- G1: F-one (row-sum-1). -----------------------------------------
    let (g1_proof, _) = {
        let r1: Vec<KElem> = (0..lgt).map(|_| tr.challenge_k(&kf)).collect();
        let eq_r1 = eq_table(&kf, &r1);
        let w1 = row_bcast(&eq_r1);
        let (scp, zst) = sumcheck_prove(&kf, vec![w1, zsel_k.clone()], 2, &product2, &mut tr);
        tr.absorb_k(&kf, "xs1-fone-final", &scp.final_evals);
        pins.push(col_pin(2, &eq_table(&kf, &zst), &scp.final_evals[1]));
        (scp, zst)
    };

    // ---- G2: F-hit (attainment zero-check, deg 3). ----------------------
    let (g2_proof, _) = {
        let rho1: Vec<KElem> = (0..lv).map(|_| tr.challenge_k(&kf)).collect();
        let eqt = eq_table(&kf, &rho1);
        let (scp, zst) =
            sumcheck_prove(&kf, vec![eqt, zsel_k.clone(), d_k.clone()], 3, &product3, &mut tr);
        tr.absorb_k(&kf, "xs1-fhit-final", &scp.final_evals);
        let lw = eq_table(&kf, &zst);
        pins.push(col_pin(2, &lw, &scp.final_evals[1]));
        pins.push(col_pin(3, &lw, &scp.final_evals[2]));
        (scp, zst)
    };

    // ---- G3: Sum (masked row sum; PW-3 weights). ------------------------
    let (g3_proof, g3_claim) = {
        let r2: Vec<KElem> = (0..lgt).map(|_| tr.challenge_k(&kf)).collect();
        let eq_r2 = eq_table(&kf, &r2);
        let mut w2 = row_bcast(&eq_r2);
        for r in 0..t {
            for c in 0..t {
                if !p_mask(r, c) {
                    w2[r * t + c] = kf.zero();
                }
            }
        }
        let mut v_sum = kf.zero();
        for (x, w) in w2.iter().enumerate() {
            if ch.e[x] != 0 && !kf.is_zero(w) {
                v_sum = kf.add(&v_sum, &kf.scale(zq.to_mod(ch.e[x]), w));
            }
        }
        tr.absorb_k(&kf, "xs1-sum-claim", std::slice::from_ref(&v_sum));
        let (scp, zst) = sumcheck_prove(&kf, vec![w2, e_k.clone()], 2, &product2, &mut tr);
        tr.absorb_k(&kf, "xs1-sum-final", &scp.final_evals);
        pins.push(col_pin(5, &eq_r2, &v_sum));
        pins.push(col_pin(4, &eq_table(&kf, &zst), &scp.final_evals[1]));
        (scp, v_sum)
    };

    // ---- G4: DIV (broadcast divisor Sum, PW-4; deg 3). ------------------
    let (g4_proof, _) = {
        let rho2: Vec<KElem> = (0..lv).map(|_| tr.challenge_k(&kf)).collect();
        let eqt = eq_table(&kf, &rho2);
        let mut w3 = eqt;
        for r in 0..t {
            for c in 0..t {
                if !p_mask(r, c) {
                    w3[r * t + c] = kf.zero();
                }
            }
        }
        let sumbc: Vec<KElem> = {
            let mut v = Vec::with_capacity(n2);
            for r in 0..t {
                let e = kf.embed(zq.to_mod(ch.sum[r]));
                for _ in 0..t {
                    v.push(e.clone());
                }
            }
            v
        };
        let l_tab: Vec<KElem> = (0..n2)
            .map(|x| kf.embed(zq.to_mod(ch.rho[x] - (ch.e[x] << F_P))))
            .collect();
        let (scp, zst) = sumcheck_prove(
            &kf, vec![w3, p_k.clone(), sumbc, l_tab], 3, &div_combine, &mut tr,
        );
        tr.absorb_k(&kf, "xs1-div-final", &scp.final_evals);
        let lw = eq_table(&kf, &zst);
        pins.push(col_pin(6, &lw, &scp.final_evals[1]));
        let eq_hi = eq_table(&kf, &zst[lgt..]);
        pins.push(col_pin(5, &eq_hi, &scp.final_evals[2]));
        // L pin: rho - 2^fP * E at z*.
        let neg_shift = zq.to_mod(-(1i64 << F_P));
        let lw_e: Vec<KElem> = lw.iter().map(|w| kf.scale(neg_shift, w)).collect();
        let mut pv = col_pin(7, &lw, &scp.final_evals[3]);
        pv.terms.extend(col_pin(4, &lw_e, &scp.final_evals[3]).terms);
        pins.push(pv);
        (scp, zst)
    };

    // ---- G5: sigma-def (sigma + rho + 1 - Sum = 0 on support). ----------
    let (g5_proof, _) = {
        let rho3: Vec<KElem> = (0..lv).map(|_| tr.challenge_k(&kf)).collect();
        let eqt = eq_table(&kf, &rho3);
        let mut w4 = eqt.clone();
        for r in 0..t {
            for c in 0..t {
                if !p_mask(r, c) {
                    w4[r * t + c] = kf.zero();
                }
            }
        }
        let c_tab: Vec<KElem> = (0..n2)
            .map(|x| kf.embed(zq.to_mod(ch.sigma[x] + ch.rho[x] - ch.sum[x / t])))
            .collect();
        // claim: sum w4 * C = -mask-mass (public on both sides).
        let (scp, zst) = sumcheck_prove(&kf, vec![w4, c_tab], 2, &product2, &mut tr);
        tr.absorb_k(&kf, "xs1-sigdef-final", &scp.final_evals);
        let lw = eq_table(&kf, &zst);
        let eq_hi = eq_table(&kf, &zst[lgt..]);
        let mut pv = col_pin(8, &lw, &scp.final_evals[1]);
        pv.terms.extend(col_pin(7, &lw, &scp.final_evals[1]).terms);
        let neg_hi: Vec<KElem> = eq_hi.iter().map(|w| kf.neg(w)).collect();
        pv.terms.extend(col_pin(5, &neg_hi, &scp.final_evals[1]).terms);
        pins.push(pv);
        (scp, zst)
    };

    // ---- G6: off-support batch pin (P, rho, sigma vanish off support). --
    let (g6_proof, g6_gamma) = {
        let gamma = tr.challenge_k(&kf);
        let gamma2 = kf.mul(&gamma, &gamma);
        let rho4: Vec<KElem> = (0..lv).map(|_| tr.challenge_k(&kf)).collect();
        let eqt = eq_table(&kf, &rho4);
        let mut w5 = eqt;
        for r in 0..t {
            for c in 0..t {
                if p_mask(r, c) {
                    w5[r * t + c] = kf.zero();
                }
            }
        }
        let b_tab: Vec<KElem> = (0..n2)
            .map(|x| {
                let mut v = kf.embed(zq.to_mod(ch.p[x]));
                v = kf.add(&v, &kf.mul(&gamma, &kf.embed(zq.to_mod(ch.rho[x]))));
                kf.add(&v, &kf.mul(&gamma2, &kf.embed(zq.to_mod(ch.sigma[x]))))
            })
            .collect();
        let (scp, zst) = sumcheck_prove(&kf, vec![w5, b_tab], 2, &product2, &mut tr);
        tr.absorb_k(&kf, "xs1-offsup-final", &scp.final_evals);
        let lw = eq_table(&kf, &zst);
        let lw_r: Vec<KElem> = lw.iter().map(|w| kf.mul(&gamma, w)).collect();
        let lw_s: Vec<KElem> = lw.iter().map(|w| kf.mul(&gamma2, w)).collect();
        let mut pv = col_pin(6, &lw, &scp.final_evals[1]);
        pv.terms.extend(col_pin(7, &lw_r, &scp.final_evals[1]).terms);
        pv.terms.extend(col_pin(8, &lw_s, &scp.final_evals[1]).terms);
        pins.push(pv);
        (scp, gamma)
    };

    // ---- G7: the d-pin (PW-3): d + mask o s8 - m_bc = 127 * maskC. ------
    {
        let r_d: Vec<KElem> = (0..lv).map(|_| tr.challenge_k(&kf)).collect();
        let lw = eq_table(&kf, &r_d);
        let eq_hi = eq_table(&kf, &r_d[lgt..]);
        let mut masked_lw = lw.clone();
        for r in 0..t {
            for c in 0..t {
                if !p_mask(r, c) {
                    masked_lw[r * t + c] = kf.zero();
                }
            }
        }
        let maskc_mass = pub_mass(&lw, &|r, c| !p_mask(r, c));
        let value = kf.scale(zq.to_mod(127), &maskc_mass);
        let mut pv = col_pin(3, &lw, &value);
        pv.terms.extend(col_pin(0, &masked_lw, &value).terms);
        let neg_hi: Vec<KElem> = eq_hi.iter().map(|w| kf.neg(w)).collect();
        pv.terms.extend(col_pin(1, &neg_hi, &value).terms);
        pins.push(pv);
    }
    let gates_s = t_prove.elapsed().as_secs_f64();

    // ---- The lookup/range instances (masked descent pairs + pins). ------
    let descent_pins = |base: usize,
                        shape_masks: &ring::gkr_masked::MaskSet,
                        proof: &MaskedDescentProof,
                        end: &DescentEnd,
                        depth: usize|
     -> Vec<PinnedValue> {
        use ring::gkr_masked::{g_hypersum_weights, g_open_weights, r_open_weights};
        let kelem_terms = |base: usize, flat_off: usize, weights: &[KElem]| -> Vec<PinTerm> {
            let mut terms = Vec::new();
            let mut i = 0usize;
            while i < weights.len() {
                let idx = flat_off + i;
                let commit = base + idx / kpc;
                let coeff0 = (idx % kpc) * K_DEG;
                let take = (kpc - (idx % kpc)).min(weights.len() - i);
                terms.push(PinTerm::Kelems { commit, coeff0, weights: weights[i..i + take].to_vec() });
                i += take;
            }
            terms
        };
        let mut out = Vec::new();
        for j in 1..depth {
            let lp_j = &proof.layers[j - 1];
            let gm = &shape_masks.g[j - 1];
            out.push(PinnedValue {
                terms: kelem_terms(base, shape_masks.g_offset(j), &g_hypersum_weights(&kf, gm)),
                value: lp_j.g_sum.clone(),
            });
            let (open_pt, mu_prev, c_w) = &end.layer_pts[j - 1];
            out.push(PinnedValue {
                terms: kelem_terms(base, shape_masks.g_offset(j), &g_open_weights(&kf, gm, open_pt)),
                value: lp_j.open_g.clone(),
            });
            if j >= 2 {
                let (orp, orq) = lp_j.open_r.clone().expect("interior layer opens Rp/Rq");
                let rw = r_open_weights(&kf, mu_prev, c_w);
                out.push(PinnedValue {
                    terms: kelem_terms(base, shape_masks.r_offset(j), &rw),
                    value: orp,
                });
                out.push(PinnedValue {
                    terms: kelem_terms(base, shape_masks.r_offset(j) + 6, &rw),
                    value: orq,
                });
            }
        }
        out
    };
    let leaf_pins = |inst: &XsInst,
                     tab_k: &[KElem],
                     endw: &DescentEnd,
                     endt: &DescentEnd,
                     alpha: &KElem|
     -> Vec<PinnedValue> {
        let n_el = xs_entry_len(inst.entry, t);
        let lw = eq_table(&kf, &endw.zstar);
        let lt = eq_table(&kf, &endt.zstar);
        let nw = 1usize << inst.dw;
        let nt = 1usize << inst.dt;
        let bpw = blinder_positions(nw);
        let bpt = blinder_positions(nt);
        let tpos = table_row_positions(inst.t_rows, nt);
        let wpos: Vec<usize> = witness_leaf_positions(n_el, nw);
        let eqw: Vec<KElem> = bpw.iter().map(|&p| lw[p].clone()).collect();
        let eqt: Vec<KElem> = bpt.iter().map(|&p| lt[p].clone()).collect();
        let hw = (0..n_el).fold(zero.clone(), |a, i| kf.add(&a, &lw[wpos[i]]));
        let ht = (0..inst.t_rows).fold(zero.clone(), |a, j| kf.add(&a, &lt[tpos[j]]));
        let sum_eqw = eqw.iter().fold(zero.clone(), |a, e| kf.add(&a, e));
        let sum_eqt = eqt.iter().fold(zero.clone(), |a, e| kf.add(&a, e));
        let ft = (0..inst.t_rows)
            .fold(zero.clone(), |a, j| kf.add(&a, &kf.mul(&lt[tpos[j]], &tab_k[j])));
        let z = zero.clone();
        let wp = PinnedValue {
            terms: vec![PinTerm::Kelems {
                commit: inst.idx_bl,
                coeff0: 0,
                weights: vec![
                    eqw[0].clone(), z.clone(), eqw[1].clone(), z.clone(),
                    eqw[2].clone(), z.clone(), eqw[3].clone(), z.clone(),
                ],
            }],
            value: kf.sub(&endw.p_claim, &hw),
        };
        let ddw = kf.sub(&kf.sub(&one, &hw), &sum_eqw);
        let mut wq_terms = vec![PinTerm::Kelems {
            commit: inst.idx_bl,
            coeff0: 0,
            weights: vec![
                z.clone(), eqw[0].clone(), z.clone(), eqw[1].clone(),
                z.clone(), eqw[2].clone(), z.clone(), eqw[3].clone(),
            ],
        }];
        for g in 0..ml.entry_cms[inst.entry] {
            let lo = g * per;
            let n_c = (n_el - lo).min(per);
            wq_terms.push(PinTerm::Scalar {
                commit: ml.entry_base[inst.entry] + g,
                coeff0: 0,
                weights: (0..n_c).map(|i| kf.neg(&lw[wpos[lo + i]])).collect(),
            });
        }
        if let Some(pe) = inst.pair {
            for g in 0..ml.entry_cms[pe] {
                let lo = g * per;
                let n_c = (n_el - lo).min(per);
                wq_terms.push(PinTerm::Scalar {
                    commit: ml.entry_base[pe] + g,
                    coeff0: 0,
                    weights: (0..n_c)
                        .map(|i| kf.neg(&ring::lookup::mul_y(&kf, &lw[wpos[lo + i]])))
                        .collect(),
                });
            }
        }
        let mut wq_value = kf.sub(&kf.sub(&endw.q_claim, &kf.mul(alpha, &hw)), &ddw);
        if inst.offset != 0 {
            wq_value = kf.add(&wq_value, &kf.scale(zq.to_mod(inst.offset), &hw));
        }
        let wq = PinnedValue { terms: wq_terms, value: wq_value };
        let mut tp_terms: Vec<PinTerm> = Vec::new();
        for g in 0..inst.m_c {
            let lo = g * per;
            let hi = ((g + 1) * per).min(inst.t_rows);
            tp_terms.push(PinTerm::Scalar {
                commit: inst.base_m + g,
                coeff0: 0,
                weights: (lo..hi).map(|j| lt[tpos[j]].clone()).collect(),
            });
        }
        tp_terms.push(PinTerm::Kelems {
            commit: inst.idx_bl,
            coeff0: 8 * K_DEG,
            weights: vec![
                eqt[0].clone(), z.clone(), eqt[1].clone(), z.clone(),
                eqt[2].clone(), z.clone(), eqt[3].clone(), z.clone(),
            ],
        });
        let tp = PinnedValue { terms: tp_terms, value: endt.p_claim.clone() };
        let ddt = kf.sub(&kf.sub(&one, &ht), &sum_eqt);
        let tq = PinnedValue {
            terms: vec![PinTerm::Kelems {
                commit: inst.idx_bl,
                coeff0: 8 * K_DEG,
                weights: vec![
                    z.clone(), eqt[0].clone(), z.clone(), eqt[1].clone(),
                    z.clone(), eqt[2].clone(), z.clone(), eqt[3].clone(),
                ],
            }],
            value: kf.add(&kf.sub(&kf.sub(&endt.q_claim, &kf.mul(alpha, &ht)), &ddt), &ft),
        };
        vec![wp, wq, tp, tq]
    };
    // The STATEMENT-side table (what the verifier folds).
    let stmt_tab_k = |inst: &XsInst| -> Vec<KElem> {
        if inst.exp_es.is_some() {
            tab_stmt
                .iter()
                .enumerate()
                .map(|(dd, &ev)| fuse_pair(&kf, dd as u64, zq.to_mod(ev)))
                .collect()
        } else {
            (0..inst.t_rows as u64).map(|j| kf.embed(j)).collect()
        }
    };

    let t_lkp = Instant::now();
    let mut inst_proofs: Vec<(MaskedDescentProof, MaskedDescentProof)> = Vec::new();
    for (ii, inst) in ml.insts.iter().enumerate() {
        let mat = &mut inst_mat[ii];
        let alpha = tr.challenge_k(&kf);
        let wtree = blinded_witness_tree(&kf, &alpha, &mat.w_col, inst.dw, &mat.bl_w);
        let (pw, endw) = masked_gkr_prove(&kf, &[wtree], mat.masks_w.take().unwrap(), &mut tr);
        let ttree = blinded_table_tree(&kf, &alpha, &mat.tab_k, &mat.m_k, inst.dt, &mat.bl_t);
        let (pt, endt) = masked_gkr_prove(&kf, &[ttree], mat.masks_t.take().unwrap(), &mut tr);
        let shell_w = zero_masks(&kf, inst.dw, 0);
        let shell_t = zero_masks(&kf, inst.dt, 0);
        pins.extend(descent_pins(inst.base_wm, &shell_w, &pw, &endw, inst.dw));
        pins.extend(descent_pins(inst.base_tm, &shell_t, &pt, &endt, inst.dt));
        pins.extend(leaf_pins(inst, &mat.tab_k, &endw, &endt, &alpha));
        inst_proofs.push((pw, pt));
        mat.w_col = Vec::new();
    }
    let lkp_s = t_lkp.elapsed().as_secs_f64();

    // ---- Pin batch -> psi claims -> masked wave split -> waves. ---------
    for p in &pins {
        tr.absorb_k(&kf, "xs1-pin", std::slice::from_ref(&p.value));
    }
    let n_pins = pins.len();
    let psi = derive_pin_psi(&tr.state(), UR1_PIN_COPIES, pins.len() * K_DEG, q);
    let claims_p = pin_claims(&kf, &pins, ml.n_data, msg_r, &psi);
    drop(pins);
    let msg_refs: Vec<&[Poly]> = msgs[..ml.n_data].iter().map(|mm| mm.as_slice()).collect();
    let (mut pw_claims, reveals) = split_claims_prover_masked(
        &zq,
        &ml.plan,
        &claims_p,
        &msg_refs,
        &ml.pad_layout,
        pads_live.take().expect("pads drawn pre-challenge"),
    )
    .expect("honest masked split");
    drop(claims_p);
    if pw_claims.is_empty() {
        pw_claims = (0..ml.plan.waves.len()).map(|_| Vec::new()).collect();
    }

    let n_waves = ml.plan.waves.len();
    let unpack_rho = |packed: &[i8]| -> Vec<Vec<i64>> {
        (0..shape.n_r)
            .map(|r| packed[r * D..(r + 1) * D].iter().map(|&b| b as i64).collect())
            .collect()
    };
    let wave_idxs = |w: usize| -> Vec<usize> {
        let mut v = ml.plan.waves[w].clone();
        if ml.pad_layout.has_pads() {
            v.push(ml.base_pad + w / ml.pad_layout.waves_per_cm);
        }
        let g0 = ml.base_wave_g + w * ml.wave_g_groups;
        v.extend(g0..g0 + ml.wave_g_groups);
        v
    };
    let mut wave_proofs: Vec<ring::ct_engine::CtRoundProof> = Vec::with_capacity(n_waves);
    let mut rp_cache: std::collections::BTreeMap<usize, (ring::ct_engine::CtRoundParams, ring::commit::A1Paths)> =
        std::collections::BTreeMap::new();
    let tr_state = tr.state();
    for w in 0..n_waves {
        let idxs = wave_idxs(w);
        let n_cw = idxs.len();
        assert!(n_cw <= ml.c2_max);
        if !rp_cache.contains_key(&n_cw) {
            let rp = derive_ct_round_params(q, shape, n_cw, 0, 0, true);
            let a1pw = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cw, (rp, a1pw));
        }
        let (rp_w, a1p_w) = rp_cache.get(&n_cw).unwrap();
        let path_w = KernelPath::A1(a1p_w);
        let claims_w: Vec<CtClaim> = std::mem::take(&mut pw_claims[w]);
        let wrhos: Vec<Vec<Vec<i64>>> = idxs.iter().map(|&i| unpack_rho(&rhos8[i])).collect();
        let openings: Vec<StdOpening> = idxs
            .iter()
            .enumerate()
            .map(|(j, &i)| StdOpening { t1: &t1s[i], t2: &t2s[i], x: &msgs[i], rho: &wrhos[j] })
            .collect();
        let mut state_p: Vec<u8> = tr_state.to_vec();
        state_p.extend((w as u64).to_le_bytes());
        let wt1s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t1s[i].clone()).collect();
        let wt2s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t2s[i].clone()).collect();
        let h0_w = ct_h0(&crs, &state_p, &wt1s, &wt2s, &[]);
        let pad_shift = usize::from(ml.pad_layout.has_pads());
        let (proof_w, _) = prove_ct_round(
            &path_w, &ctx_ring, rp_w, None, &crs, &h0_w, &claims_w, &[], &[], &[], &openings,
            &[], &[], ml.plan.waves[w].len() + pad_shift, &mut rng,
        );
        wave_proofs.push(proof_w);
    }
    let closing_proof = if ml.pad_layout.has_pads() {
        let idxs_z: Vec<usize> = (ml.base_pad..ml.base_pad + ml.pad_layout.n_pad_cms)
            .chain(ml.base_closing_g..ml.base_closing_g + ml.closing_g_groups)
            .collect();
        let n_cz = idxs_z.len();
        if !rp_cache.contains_key(&n_cz) {
            let rp = derive_ct_round_params(q, shape, n_cz, 0, 0, true);
            let a1pz = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cz, (rp, a1pz));
        }
        let (rp_z, a1p_z) = rp_cache.get(&n_cz).unwrap();
        let path_z = KernelPath::A1(a1p_z);
        let claims_z = closing_round_claims(&zq, &ml.pad_layout);
        let mut state_z: Vec<u8> = tr_state.to_vec();
        state_z.extend(b"xs1-closing");
        let zt1s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t1s[i].clone()).collect();
        let zt2s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t2s[i].clone()).collect();
        let h0_z = ct_h0(&crs, &state_z, &zt1s, &zt2s, &[]);
        let zrhos: Vec<Vec<Vec<i64>>> = idxs_z.iter().map(|&i| unpack_rho(&rhos8[i])).collect();
        let openings_z: Vec<StdOpening> = idxs_z
            .iter()
            .enumerate()
            .map(|(j, &i)| StdOpening { t1: &t1s[i], t2: &t2s[i], x: &msgs[i], rho: &zrhos[j] })
            .collect();
        let (proof_z, _) = prove_ct_round(
            &path_z, &ctx_ring, rp_z, None, &crs, &h0_z, &claims_z, &[], &[], &[], &openings_z,
            &[], &[], ml.pad_layout.n_pad_cms, &mut rng,
        );
        Some(proof_z)
    } else {
        None
    };
    let prove_s = t_prove.elapsed().as_secs_f64();

    // =====================================================================
    // VERIFIER (statement gate + the same rolling transcript).
    // =====================================================================
    let t_verify = Instant::now();
    {
        let st_v = xs_statement_bytes_tagged(
            cfg.stmt_tag, cfg.stmt_extra, t, es, &cfg.member_digest, &entry_digests, &crs.crs_hash,
        );
        if uk8_sha(&[&st_v]) != ctx {
            verdict.statement_ok = false;
            return (verdict, [commit_s, prove_s, 0.0], n_pins, n_waves);
        }
    }
    let mut tv = LkpTranscript::new(cfg.label, &h0);
    let mut pins_v: Vec<PinnedValue> = Vec::new();

    // ---- G1. ------------------------------------------------------------
    {
        let r1: Vec<KElem> = (0..lgt).map(|_| tv.challenge_k(&kf)).collect();
        let sc = sumcheck_verify(&kf, lv, 2, &one, &g1_proof, &product2, &mut tv);
        tv.absorb_k(&kf, "xs1-fone-final", &g1_proof.final_evals);
        match sc {
            Some((zst, _)) => {
                // W1's MLE at z* = eq(r1, z*_high) — mask-free public row weight.
                if g1_proof.final_evals[0] != eq_eval(&kf, &r1, &zst[lgt..]) {
                    verdict.fone_ok = false;
                }
                pins_v.push(col_pin(2, &eq_table(&kf, &zst), &g1_proof.final_evals[1]));
            }
            None => verdict.fone_ok = false,
        }
    }
    // ---- G2. ------------------------------------------------------------
    {
        let rho1: Vec<KElem> = (0..lv).map(|_| tv.challenge_k(&kf)).collect();
        let sc = sumcheck_verify(&kf, lv, 3, &zero, &g2_proof, &product3, &mut tv);
        tv.absorb_k(&kf, "xs1-fhit-final", &g2_proof.final_evals);
        match sc {
            Some((zst, _)) => {
                if g2_proof.final_evals[0] != eq_eval(&kf, &rho1, &zst) {
                    verdict.fhit_ok = false;
                }
                let lw = eq_table(&kf, &zst);
                pins_v.push(col_pin(2, &lw, &g2_proof.final_evals[1]));
                pins_v.push(col_pin(3, &lw, &g2_proof.final_evals[2]));
            }
            None => verdict.fhit_ok = false,
        }
    }
    // ---- G3 (PW-3 weight check: the shifted-mask pre-registered gate). --
    {
        let r2: Vec<KElem> = (0..lgt).map(|_| tv.challenge_k(&kf)).collect();
        let eq_r2 = eq_table(&kf, &r2);
        tv.absorb_k(&kf, "xs1-sum-claim", std::slice::from_ref(&g3_claim));
        let sc = sumcheck_verify(&kf, lv, 2, &g3_claim, &g3_proof, &product2, &mut tv);
        tv.absorb_k(&kf, "xs1-sum-final", &g3_proof.final_evals);
        match sc {
            Some((zst, _)) => {
                let mut w2v = row_bcast(&eq_r2);
                for r in 0..t {
                    for c in 0..t {
                        if !v_mask(r, c) {
                            w2v[r * t + c] = kf.zero();
                        }
                    }
                }
                if g3_proof.final_evals[0] != pub_mle(&w2v, &zst) {
                    verdict.sum_ok = false;
                }
                pins_v.push(col_pin(5, &eq_r2, &g3_claim));
                pins_v.push(col_pin(4, &eq_table(&kf, &zst), &g3_proof.final_evals[1]));
            }
            None => verdict.sum_ok = false,
        }
    }
    // ---- G4. ------------------------------------------------------------
    {
        let rho2: Vec<KElem> = (0..lv).map(|_| tv.challenge_k(&kf)).collect();
        let sc = sumcheck_verify(&kf, lv, 3, &zero, &g4_proof, &div_combine, &mut tv);
        tv.absorb_k(&kf, "xs1-div-final", &g4_proof.final_evals);
        match sc {
            Some((zst, _)) => {
                let eqt = eq_table(&kf, &rho2);
                let mut w3v = eqt;
                for r in 0..t {
                    for c in 0..t {
                        if !v_mask(r, c) {
                            w3v[r * t + c] = kf.zero();
                        }
                    }
                }
                if g4_proof.final_evals[0] != pub_mle(&w3v, &zst) {
                    verdict.div_ok = false;
                }
                let lw = eq_table(&kf, &zst);
                pins_v.push(col_pin(6, &lw, &g4_proof.final_evals[1]));
                let eq_hi = eq_table(&kf, &zst[lgt..]);
                pins_v.push(col_pin(5, &eq_hi, &g4_proof.final_evals[2]));
                let neg_shift = zq.to_mod(-(1i64 << F_P));
                let lw_e: Vec<KElem> = lw.iter().map(|w| kf.scale(neg_shift, w)).collect();
                let mut pv = col_pin(7, &lw, &g4_proof.final_evals[3]);
                pv.terms.extend(col_pin(4, &lw_e, &g4_proof.final_evals[3]).terms);
                pins_v.push(pv);
            }
            None => verdict.div_ok = false,
        }
    }
    // ---- G5. ------------------------------------------------------------
    {
        let rho3: Vec<KElem> = (0..lv).map(|_| tv.challenge_k(&kf)).collect();
        let eqt = eq_table(&kf, &rho3);
        let claim_v = kf.neg(&pub_mass(&eqt, &|r, c| v_mask(r, c)));
        let sc = sumcheck_verify(&kf, lv, 2, &claim_v, &g5_proof, &product2, &mut tv);
        tv.absorb_k(&kf, "xs1-sigdef-final", &g5_proof.final_evals);
        match sc {
            Some((zst, _)) => {
                let mut w4v = eqt;
                for r in 0..t {
                    for c in 0..t {
                        if !v_mask(r, c) {
                            w4v[r * t + c] = kf.zero();
                        }
                    }
                }
                if g5_proof.final_evals[0] != pub_mle(&w4v, &zst) {
                    verdict.sigdef_ok = false;
                }
                let lw = eq_table(&kf, &zst);
                let eq_hi = eq_table(&kf, &zst[lgt..]);
                let mut pv = col_pin(8, &lw, &g5_proof.final_evals[1]);
                pv.terms.extend(col_pin(7, &lw, &g5_proof.final_evals[1]).terms);
                let neg_hi: Vec<KElem> = eq_hi.iter().map(|w| kf.neg(w)).collect();
                pv.terms.extend(col_pin(5, &neg_hi, &g5_proof.final_evals[1]).terms);
                pins_v.push(pv);
            }
            None => verdict.sigdef_ok = false,
        }
    }
    // ---- G6. ------------------------------------------------------------
    {
        let gamma = tv.challenge_k(&kf);
        // NOTE: after an earlier REJECTING gate the verifier transcript
        // is deliberately desynced (house behavior — the verdict names
        // the first failing gate); gamma is NOT asserted equal to the
        // prover's.
        let _ = &g6_gamma;
        let gamma2 = kf.mul(&gamma, &gamma);
        let rho4: Vec<KElem> = (0..lv).map(|_| tv.challenge_k(&kf)).collect();
        let sc = sumcheck_verify(&kf, lv, 2, &zero, &g6_proof, &product2, &mut tv);
        tv.absorb_k(&kf, "xs1-offsup-final", &g6_proof.final_evals);
        match sc {
            Some((zst, _)) => {
                let eqt = eq_table(&kf, &rho4);
                let mut w5v = eqt;
                for r in 0..t {
                    for c in 0..t {
                        if v_mask(r, c) {
                            w5v[r * t + c] = kf.zero();
                        }
                    }
                }
                if g6_proof.final_evals[0] != pub_mle(&w5v, &zst) {
                    verdict.offsup_ok = false;
                }
                let lw = eq_table(&kf, &zst);
                let lw_r: Vec<KElem> = lw.iter().map(|w| kf.mul(&gamma, w)).collect();
                let lw_s: Vec<KElem> = lw.iter().map(|w| kf.mul(&gamma2, w)).collect();
                let mut pv = col_pin(6, &lw, &g6_proof.final_evals[1]);
                pv.terms.extend(col_pin(7, &lw_r, &g6_proof.final_evals[1]).terms);
                pv.terms.extend(col_pin(8, &lw_s, &g6_proof.final_evals[1]).terms);
                pins_v.push(pv);
            }
            None => verdict.offsup_ok = false,
        }
    }
    // ---- G7 (verifier side, TRUE mask). ---------------------------------
    {
        let r_d: Vec<KElem> = (0..lv).map(|_| tv.challenge_k(&kf)).collect();
        let lw = eq_table(&kf, &r_d);
        let eq_hi = eq_table(&kf, &r_d[lgt..]);
        let mut masked_lw = lw.clone();
        for r in 0..t {
            for c in 0..t {
                if !v_mask(r, c) {
                    masked_lw[r * t + c] = kf.zero();
                }
            }
        }
        let maskc_mass = pub_mass(&lw, &|r, c| !v_mask(r, c));
        let value = kf.scale(zq.to_mod(127), &maskc_mass);
        let mut pv = col_pin(3, &lw, &value);
        pv.terms.extend(col_pin(0, &masked_lw, &value).terms);
        let neg_hi: Vec<KElem> = eq_hi.iter().map(|w| kf.neg(w)).collect();
        pv.terms.extend(col_pin(1, &neg_hi, &value).terms);
        pins_v.push(pv);
    }
    // ---- Instances. -----------------------------------------------------
    for (ii, inst) in ml.insts.iter().enumerate() {
        let (pw, pt) = &inst_proofs[ii];
        let alpha = tv.challenge_k(&kf);
        let shell_w = zero_masks(&kf, inst.dw, 0);
        let shell_t = zero_masks(&kf, inst.dt, 0);
        let vw = masked_gkr_verify(&kf, 1, inst.dw, &shell_w, pw, &mut tv, false);
        let vt = masked_gkr_verify(&kf, 1, inst.dt, &shell_t, pt, &mut tv, false);
        match (vw, vt) {
            (Some((roots_w, ew)), Some((roots_t, et))) => {
                let mut ok = !kf.is_zero(&roots_w[0][1]) && !kf.is_zero(&roots_t[0][1]);
                ok &= kf.mul(&roots_w[0][0], &roots_t[0][1])
                    == kf.mul(&roots_t[0][0], &roots_w[0][1]);
                verdict.roots_ok[ii] = ok;
                pins_v.extend(descent_pins(inst.base_wm, &shell_w, pw, &ew, inst.dw));
                pins_v.extend(descent_pins(inst.base_tm, &shell_t, pt, &et, inst.dt));
                pins_v.extend(leaf_pins(inst, &stmt_tab_k(inst), &ew, &et, &alpha));
            }
            _ => {
                verdict.roots_ok[ii] = false;
            }
        }
    }
    // ---- Pin batch + waves. ---------------------------------------------
    for p in &pins_v {
        tv.absorb_k(&kf, "xs1-pin", std::slice::from_ref(&p.value));
    }
    let psi_v = derive_pin_psi(&tv.state(), UR1_PIN_COPIES, pins_v.len() * K_DEG, q);
    let claims_v = pin_claims(&kf, &pins_v, ml.n_data, msg_r, &psi_v);
    drop(pins_v);
    let v_split = split_claims_verifier_masked(&zq, &ml.plan, &claims_v, &reveals, &ml.pad_layout);
    drop(claims_v);
    let mut vw_claims: Vec<Vec<CtClaim>> = match v_split {
        Ok(v) => v,
        Err(_) => {
            verdict.sum_gate_ok = false;
            verdict.waves_ok = false;
            return (verdict, [commit_s, prove_s, t_verify.elapsed().as_secs_f64()], n_pins, n_waves);
        }
    };
    if vw_claims.is_empty() {
        vw_claims = (0..n_waves).map(|_| Vec::new()).collect();
    }
    let tv_state = tv.state();
    for w in 0..n_waves {
        let idxs = wave_idxs(w);
        let n_cw = idxs.len();
        let (rp_w, a1p_w) = rp_cache.get(&n_cw).expect("verifier derives the same round shapes");
        let path_w = KernelPath::A1(a1p_w);
        let claims_w: Vec<CtClaim> = std::mem::take(&mut vw_claims[w]);
        let mut state_v: Vec<u8> = tv_state.to_vec();
        state_v.extend((w as u64).to_le_bytes());
        let wt1s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t1s[i].clone()).collect();
        let wt2s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t2s[i].clone()).collect();
        let h0_wv = ct_h0(&crs, &state_v, &wt1s, &wt2s, &[]);
        let pad_shift = usize::from(ml.pad_layout.has_pads());
        let ok_w = verify_ct_round(
            &path_w, &ctx_ring, rp_w, None, &crs, &h0_wv, &claims_w, &[], &[], &[], &wt1s, &wt2s,
            &[], &[], &[], ml.plan.waves[w].len() + pad_shift, &wave_proofs[w],
        );
        if !ok_w {
            verdict.waves_ok = false;
            if verdict.first_bad_wave.is_none() {
                verdict.first_bad_wave = Some(w);
            }
        }
    }
    if let Some(proof_z) = &closing_proof {
        let idxs_z: Vec<usize> = (ml.base_pad..ml.base_pad + ml.pad_layout.n_pad_cms)
            .chain(ml.base_closing_g..ml.base_closing_g + ml.closing_g_groups)
            .collect();
        let n_cz = idxs_z.len();
        let (rp_z, a1p_z) = rp_cache.get(&n_cz).expect("closing shape derived");
        let path_z = KernelPath::A1(a1p_z);
        let claims_zv = closing_round_claims(&zq, &ml.pad_layout);
        let mut state_zv: Vec<u8> = tv_state.to_vec();
        state_zv.extend(b"xs1-closing");
        let zt1s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t1s[i].clone()).collect();
        let zt2s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t2s[i].clone()).collect();
        let h0_zv = ct_h0(&crs, &state_zv, &zt1s, &zt2s, &[]);
        if !verify_ct_round(
            &path_z, &ctx_ring, rp_z, None, &crs, &h0_zv, &claims_zv, &[], &[], &[], &zt1s, &zt2s,
            &[], &[], &[], ml.pad_layout.n_pad_cms, proof_z,
        ) {
            verdict.closing_ok = false;
        }
    }
    let verify_s = t_verify.elapsed().as_secs_f64();
    if !quiet {
        println!(
            "  xs1 seed {seed} t {t}: accept={} | {} data cms / {} commits / {n_waves} waves / {n_pins} pins | commit {commit_s:.1}s prove {prove_s:.1}s (gates {gates_s:.1} lkp {lkp_s:.1}) verify {verify_s:.1}s [WSL-BOX NOISY-SHARED]",
            verdict.accept(), ml.n_data, ml.n_commits,
        );
    }
    (verdict, [commit_s, prove_s, verify_s], n_pins, n_waves)
}

/// [UPERF3-JJ] `uperf-x prove [seed] [t]` — acceptance (a).
fn uperf_x_prove(seed: u64, t: usize) {
    let (verdict, _, _, _) = xs1_run(seed, t, ring::attn_softmax::E_S, false, XsTamper::None, false);
    let insts = xs_instances(t, ring::attn_softmax::E_S);
    println!(
        "[UPERF3-JJ] prove: {} (first gate state: {})",
        if verdict.accept() { "ACCEPT" } else { "REJECT" },
        verdict.first_failed_gate(&insts)
    );
    assert!(verdict.accept(), "honest xs1 chain must ACCEPT");
}

/// [UPERF3-JJ] rung 5 — `uperf-x prove-cal [seed] [t]`: the
/// CALIBRATED-DATA variant. The s8 draw is score-shaped at the
/// MEASURED eS = -2 (lane CC's results/m8b_gemma4_attn_stats.json,
/// layer 0: absmax 25.887, e8 -2); the statement binds the eS = -2
/// member; chain stats (exp underflow share, Sum range, row-mass
/// window) printed for the record.
fn uperf_x_prove_cal(seed: u64, t: usize) {
    use ring::attn_softmax::{F_E, F_P, calibrated_s8, derive_chain, exp_member};
    let es = -2;
    let (tab, _) = exp_member(es);
    let s8 = calibrated_s8(seed, t * t);
    let ch = derive_chain(t, &s8, &tab);
    let mut zero_e = 0usize;
    let mut support = 0usize;
    for r in 0..t {
        for c in 0..=r {
            support += 1;
            if ch.e[r * t + c] == 0 {
                zero_e += 1;
            }
        }
    }
    let (mut mass_lo, mut mass_hi) = (i64::MAX, i64::MIN);
    for r in 0..t {
        let m: i64 = (0..=r).map(|c| ch.p[r * t + c]).sum();
        mass_lo = mass_lo.min(m);
        mass_hi = mass_hi.max(m);
    }
    println!(
        "[UPERF3-JJ] prove-cal chain stats: exp underflow {:.1}% of support | Sum in [{}, {}] (floor 2^{F_E} = {}) | row mass in [{mass_lo}, {mass_hi}] vs 2^{F_P} = {}",
        100.0 * zero_e as f64 / support as f64,
        ch.sum.iter().min().unwrap(),
        ch.sum.iter().max().unwrap(),
        1i64 << F_E,
        1i64 << F_P
    );
    let (verdict, _, _, _) = xs1_run(seed, t, es, true, XsTamper::None, false);
    let insts = xs_instances(t, es);
    println!(
        "[UPERF3-JJ] prove-cal (eS -2, measured exponent): {} (first gate state: {})",
        if verdict.accept() { "ACCEPT" } else { "REJECT" },
        verdict.first_failed_gate(&insts)
    );
    assert!(verdict.accept(), "calibrated xs1 chain must ACCEPT");
}

/// [UPERF3-JJ] rung 3 — `uperf-x battery [seed] [t]`: the AT-O8/AT-O9
/// tamper legs, EACH asserted to reject at its PRE-REGISTERED gate
/// (acceptance b), plus the honest ACCEPT leg. Prints its own digest
/// over the leg outcome lines.
fn uperf_x_battery(seed: u64, t: usize) {
    use sha2::{Digest, Sha256};
    let t0 = Instant::now();
    println!(
        "[UPERF3-JJ] uperf-x battery at seed {seed}, T = {t} (ZK_THREADS {})",
        ring::eval_proof::threads()
    );
    let insts = xs_instances(t, ring::attn_softmax::E_S);
    // (leg, tamper, the PRE-REGISTERED gate as first_failed_gate names it,
    //  side-fire notes asserted where checkable).
    let legs: Vec<(&str, XsTamper, String)> = vec![
        ("honest", XsTamper::None, "ACCEPT".into()),
        (
            "m-overstated (+1, chain self-consistent, zsel at argmax)",
            XsTamper::MOverstate,
            "G2 F-hit (attainment zero-check)".into(),
        ),
        (
            "m-understated (-1, zsel moved to a d=0 position — strongest cheater)",
            XsTamper::MUnderstate,
            "rng-d-w8 root cross-check".into(),
        ),
        (
            "zsel two-hot (second bit at a TIED max, d=0 there)",
            XsTamper::ZselTwoHot,
            "G1 F-one (row-sum-1)".into(),
        ),
        (
            "zsel off-support (row-sum still 1; d = m+127 > 0 there)",
            XsTamper::ZselOffsupport,
            "G2 F-hit (attainment zero-check)".into(),
        ),
        (
            "off-support P != 0 (support facts untouched)",
            XsTamper::OffsupportP,
            "G6 off-support batch zero-check".into(),
        ),
        (
            "shifted mask (prover derives + weights with support t' <= t+1)",
            XsTamper::ShiftedMask,
            "G3 Sum (masked row sum, PW-3 weight check)".into(),
        ),
        (
            // The verifier folds the STATEMENT member into the exp tq
            // leaf pin; the changed pin value shifts the psi-batched
            // claim mass, and the masked split's sum gate rejects —
            // the leaf-pin gate surfacing one step before the waves.
            "wrong exp member (eS -2 forged consistently; statement says -1)",
            XsTamper::WrongExpMember,
            "masked-claims sum gate".into(),
        ),
    ];
    let mut digest = Sha256::new();
    let mut all_ok = true;
    for (name, tamper, expect) in &legs {
        let (verdict, _, _, _) = xs1_run(seed, t, ring::attn_softmax::E_S, false, *tamper, true);
        let got = verdict.first_failed_gate(&insts);
        let leg_ok = got == *expect
            && (*tamper == XsTamper::None) == verdict.accept();
        // Side-fire assertions where the gate order lets us check them.
        let side = match tamper {
            XsTamper::MUnderstate => {
                // The exp pair's root cross-check must ALSO fire (the
                // fused (d, E) code is off-table at the d = -1 position);
                // F-one/F-hit stay green (the strongest-cheater move).
                let s = !verdict.roots_ok[2] && verdict.fone_ok && verdict.fhit_ok;
                if s { " [exp-pair root also fires; G1/G2 green]" } else { " [SIDE-FIRE CHECK FAILED]" }
            }
            XsTamper::OffsupportP => {
                let s = verdict.fone_ok && verdict.fhit_ok && verdict.sum_ok && verdict.div_ok && verdict.sigdef_ok;
                if s { " [G1-G5 green: support facts blind to it]" } else { " [SIDE-FIRE CHECK FAILED]" }
            }
            XsTamper::ZselOffsupport | XsTamper::MOverstate => {
                let s = verdict.fone_ok;
                if s { " [G1 green]" } else { " [SIDE-FIRE CHECK FAILED]" }
            }
            XsTamper::ShiftedMask => {
                let s = verdict.fone_ok && verdict.fhit_ok;
                if s { " [G1/G2 green (mask-free gates)]" } else { " [SIDE-FIRE CHECK FAILED]" }
            }
            XsTamper::WrongExpMember => {
                // The forge is self-consistent: every gate and every
                // root cross-check stays green — ONLY the statement-side
                // table fold catches it (C5's whole point).
                let s = verdict.fone_ok && verdict.fhit_ok && verdict.sum_ok
                    && verdict.div_ok && verdict.sigdef_ok && verdict.offsup_ok
                    && verdict.roots_ok.iter().all(|&b| b);
                if s { " [all gates + roots green: the STATEMENT table is the only witness]" } else { " [SIDE-FIRE CHECK FAILED]" }
            }
            _ => "",
        };
        let line = format!(
            "  {} {name}: gate {got}{side}",
            if leg_ok && !side.contains("FAILED") { "ok  " } else { "FAIL" }
        );
        println!("{line}");
        digest.update(line.as_bytes());
        digest.update(expect.as_bytes());
        all_ok &= leg_ok && !side.contains("FAILED");
    }
    let dg: [u8; 32] = digest.finalize().into();
    assert!(all_ok, "xs1 battery: a leg missed its pre-registered gate");
    println!(
        "[UPERF3-JJ] battery: {} legs ok in {:.1}s [WSL-BOX NOISY-SHARED]",
        legs.len(),
        t0.elapsed().as_secs_f64()
    );
    println!("[UPERF3-JJ] XS1 BATTERY DIGEST {}", hex_full(&dg));
}

/// [UPERF3-JJ] rung 4 — `uperf-x stage-a [seed] [t]` (acceptance d):
/// the SAME chain's range facts (d w8, zsel w1, the rho/sigma
/// remainder w18s at the contract T) through zc_range's zero-check
/// form, with the masked descent pair as the ORACLE on the same
/// committed column (the S1/lane-GG differential pattern at
/// attention's widths) and the c = 16 sub-extension proven
/// BYTE-IDENTICAL to the boxed-K oracle (rounds, fold point, finals,
/// transcript state — the uperf-s battery leg-A identity).
fn uperf_x_stage_a(seed: u64, t: usize) {
    use ring::attn_softmax::{E_S, derive_chain, exp_member, seeded_s8};
    use ring::gkr::{eq_eval, root_cross_check};
    use ring::kfield::{KElem, KField};
    use ring::sumcheck::LkpTranscript;
    use ring::zc_range::{
        SubExt, ZcRangeInstance, zc_range_open_check, zc_range_prove, zc_range_prove_oracle_k,
        zc_range_verify,
    };
    use sha2::{Digest, Sha256};
    let t0 = Instant::now();
    let ctx = ring_ctx_q8();
    let kf = KField::new(&ctx);
    let q = ctx.zq.q;
    assert!(t.is_power_of_two() && t >= 32);
    let lgt = t.trailing_zeros() as usize;
    let n_log2 = 2 * lgt;
    let wrho = xs_wrho(t);
    let (tab, _) = exp_member(E_S);
    let s8 = seeded_s8(seed, t * t);
    let ch = derive_chain(t, &s8, &tab);
    println!(
        "[UPERF3-JJ] stage-a leg at seed {seed}, T = {t} (n = 2^{n_log2}; widths d w8, zsel w1, rho/sigma w{wrho}; ZK_THREADS {})",
        ring::eval_proof::threads()
    );
    let groups: [(&str, &[i64], usize); 4] = [
        ("d-w8", &ch.d, 8),
        ("zsel-w1", &ch.zsel, 1),
        (&format!("rho-w{wrho}").leak(), &ch.rho, wrho),
        (&format!("sigma-w{wrho}").leak(), &ch.sigma, wrho),
    ];
    let mut all = Sha256::new();
    for (gi, (name, vals, w)) in groups.iter().enumerate() {
        // ---- (a) the masked descent pair — the ORACLE form of the fact.
        let keys: Vec<KElem> = vals.iter().map(|&v| kf.embed(ctx.zq.to_mod(v))).collect();
        let tab_k: Vec<KElem> = (0..1u64 << w).map(|j| kf.embed(j)).collect();
        let mut mult = vec![0u64; 1 << w];
        for &v in vals.iter() {
            mult[v as usize] += 1;
        }
        let depth = n_log2 + 1;
        let dt = (w + 1).max(4);
        let out = uperf_s_descent_pair(
            &kf, "uperf3-jj-za", (seed as u8) ^ (gi as u8), &keys, &tab_k, &mult, depth, dt,
        );
        assert!(
            root_cross_check(&kf, &out.wroot, &out.troot),
            "{name}: descent-oracle root cross-check"
        );
        // ---- (b) the Stage-A zero-check form on the same column.
        let (planes, rem) = ring::stage_a::range_planes(vals, 0, *w, n_log2);
        let inst = ZcRangeInstance { n_log2, e0: 1, planes: &planes, rem: &rem };
        let mut c16_secs = 0.0;
        for c in [8usize, 16] {
            let ext = SubExt::new(&kf, c);
            let mut tr = LkpTranscript::new("uperf3-jj-za-zc", &[seed as u8 ^ gi as u8; 32]);
            let rho: Vec<_> = (0..n_log2).map(|_| ext.challenge(&kf, &mut tr)).collect();
            let betas: Vec<_> = (0..=*w).map(|_| ext.challenge(&kf, &mut tr)).collect();
            let tz = Instant::now();
            let (proof, point, _st) = zc_range_prove(&kf, &ext, &inst, &rho, &betas, &mut tr);
            let prove_s = tz.elapsed().as_secs_f64();
            let mut tv = LkpTranscript::new("uperf3-jj-za-zc", &[seed as u8 ^ gi as u8; 32]);
            let rho_v: Vec<_> = (0..n_log2).map(|_| ext.challenge(&kf, &mut tv)).collect();
            let betas_v: Vec<_> = (0..=*w).map(|_| ext.challenge(&kf, &mut tv)).collect();
            let vp = zc_range_verify(&kf, &ext, n_log2, 1, *w, &rho_v, &betas_v, &proof, &mut tv);
            assert!(
                vp.as_deref() == Some(point.as_slice()) && tv.state() == tr.state(),
                "{name}: zc verify at c {c}"
            );
            assert!(
                zc_range_open_check(&ext, &inst, &point, &proof.finals),
                "{name}: open check at c {c}"
            );
            for g in &proof.rounds {
                for e in g {
                    for x in ext.to_k(e) {
                        all.update(x.to_le_bytes());
                    }
                }
            }
            if c == 16 {
                c16_secs = prove_s;
                // ---- (c) c = 16 IS the frozen K arithmetic: byte identity
                // against the boxed-K oracle on the SAME challenges.
                let mut trb =
                    LkpTranscript::new("uperf3-jj-za-zc", &[seed as u8 ^ gi as u8; 32]);
                let rho_k: Vec<KElem> = (0..n_log2).map(|_| trb.challenge_k(&kf)).collect();
                let betas_k: Vec<KElem> = (0..=*w).map(|_| trb.challenge_k(&kf)).collect();
                assert!(rho.iter().zip(&rho_k).all(|(e, k)| ext.to_k(e) == *k));
                let (pk, pointk) = zc_range_prove_oracle_k(&kf, &inst, &rho_k, &betas_k, &mut trb);
                assert_eq!(tr.state(), trb.state(), "{name}: transcript identity at c=16");
                for (ge, gk) in proof.rounds.iter().zip(pk.rounds.iter()) {
                    assert!(
                        ge.iter().zip(gk.iter()).all(|(e, k)| ext.to_k(e) == *k),
                        "{name}: round-poly identity"
                    );
                }
                assert!(point.iter().zip(&pointk).all(|(e, k)| ext.to_k(e) == *k));
                assert_eq!(pk.final_evals[0], eq_eval(&kf, &rho_k, &pointk));
                assert!(
                    proof.finals.iter().zip(pk.final_evals[1..].iter()).all(|(e, k)| ext.to_k(e) == *k),
                    "{name}: finals identity"
                );
                let _ = q;
            }
        }
        println!(
            "  ok   {name}: descent-oracle roots cross-check green (depth {depth} + table depth {dt}, trees+prove {:.2}s) | zc form c 8/16 verify+open green (c16 prove {c16_secs:.2}s) | c16 == boxed-K oracle byte-identical [WSL-BOX NOISY-SHARED]",
            out.trees_s + out.prove_s
        );
    }
    let dg: [u8; 32] = all.finalize().into();
    println!(
        "[UPERF3-JJ] stage-a leg: 4 fact groups x (oracle + zc + K-identity) green in {:.1}s",
        t0.elapsed().as_secs_f64()
    );
    println!("[UPERF3-JJ] XS1 STAGE-A DIGEST {}", hex_full(&dg));
}

// ===========================================================================
// [UPERF3-NN] U-PERF3 round 8, lane NN — X1: the attention ENTRY CLASSES +
// PUBLIC-WEIGHT WIRINGS at toy shape (design memo §5.1 X1; semantics
// ATTENTION_INTEGER_SPEC.md §2.1-2.9; value side ring/attn_entries.rs;
// softmax core = the X-S1 machinery above, reused per head through
// xs1_run_core). ADDITIVE: nothing here is called by any shipped path;
// frozen registries unmoved (rope/exp members lane-local, AT-O5/O6
// pending). AT-O2 ruled UNFUSED (66 entries; ledger).
//
//   uperf-x entries [seed] [t]      — the typed 66-entry table + census
//   uperf-x layer-chain [seed] [t]  — the full-layer value chain (diff vs
//                                     scripts/attention_x1_layer_ref.py)
//   uperf-x pw-battery [seed]       — PW-1..PW-4 + head-coeff-MLE F5 legs
//   uperf-x head-prove [seed] [t]   — the per-head X-S1 chain proven (2 heads)
//   uperf-x head-battery [seed] [t] — AT-O8/O9-class tamper legs per head
// ===========================================================================

/// The per-entry (QuantMeta, TypingV4) rows + class label + exponent
/// SOURCE tag (the §1.6b measured defaults / synthetic / structural /
/// derived), at the toy dims. Declared class bounds (int8 operands),
/// never draw-empirical — the bf_entry_typing discipline.
fn x1_entry_typing(
    e: usize,
    lay: &ring::attn_entries::X1Layer,
) -> (manifest::QuantMeta, manifest::TypingV4, &'static str, String) {
    use manifest::{CLS_ACC, CLS_ACT8, CLS_AUX31, CLS_REM, CLS_W8S, QuantMeta, TypingV4};
    use ring::attn_entries::{bits_signed, bits_unsigned, E_GAMMA, E_W, E_X, TOY_D, W_LIMB, X1_ENTRIES};
    use ring::attn_softmax::{F_E, F_P, HEAD_DIM};
    let m = &lay.meta;
    let t = lay.t;
    let q = |bits: u32, signed: bool| QuantMeta { bits, frac_bits: 0, signed };
    let qf = |bits: u32, frac: u32, signed: bool| QuantMeta { bits, frac_bits: frac, signed };
    let ty = |se: i32, sym: bool, class: u32| TypingV4 { scale_exp: se, symmetric: sym, class, base_e0: 2 };
    let tyw = |se: i32| TypingV4 { scale_exp: se, symmetric: true, class: CLS_W8S, base_e0: 1 };
    let d_i = TOY_D as i64;
    let ceps_a = m.ceps_a;
    let ceps_m = m.ceps_m;
    let dmax_a = ring::attn_entries::isqrt_i64(d_i * 127 * 127 + ceps_a);
    let dmax_m = ring::attn_entries::isqrt_i64(d_i * 127 * 127 + ceps_m);
    let acc768 = bits_signed(d_i * 127 * 127); // inner-d int8xint8 declared class
    let acc_score = bits_signed(HEAD_DIM as i64 * 127 * 127);
    let acc_pv = bits_signed((t as i64) * (1 << F_P) * 127);
    let acc_rope = bits_signed(2 * 127 << 7);
    let xw1_b = bits_signed(127 * ((1i64 << (E_X - std::cmp::min(E_X, m.e_ao))) + (1i64 << (m.e_ao - std::cmp::min(E_X, m.e_ao)))));
    let meas = |e8: i32| format!("MEASURED §1.6b l0 e8 {e8} (per-tensor int8)");
    let seam = |e8: i32| format!("MEASURED §1.6b l0 e8 {e8}; SEAM: i16 class @8B (stack_wide ruling)");
    let der = "derived (edge metadata)".to_string();
    let strq = "structural (§1.6 axis table: none)".to_string();
    let syn = "SYNTHETIC (spec §0 class; X2/AT-O1 kills)".to_string();
    let wsrc = "study class eW -9 (Wattn int8 MEASURED +0.20 composed)".to_string();
    match X1_ENTRIES[e] {
        "xsqA" => (q(15, true), ty(2 * E_X, true, CLS_ACC), "ACC", der),
        "xsqM" => (q(15, true), ty(2 * m.e_r1, true, CLS_ACC), "ACC", der),
        "SSA" => (q(bits_unsigned(d_i * 127 * 127 + ceps_a), false), ty(2 * E_X, false, CLS_ACC), "ACC", der),
        "SSM" => (q(bits_unsigned(d_i * 127 * 127 + ceps_m), false), ty(2 * m.e_r1, false, CLS_ACC), "ACC", der),
        "DA" => (q(bits_unsigned(dmax_a), false), ty(E_X, false, CLS_AUX31), "AUX", der),
        "DM" => (q(bits_unsigned(dmax_m), false), ty(m.e_r1, false, CLS_AUX31), "AUX", der),
        "DsqA" => (q(bits_unsigned(dmax_a * dmax_a), false), ty(2 * E_X, false, CLS_AUX31), "AUX", der),
        "DsqM" => (q(bits_unsigned(dmax_m * dmax_m), false), ty(2 * m.e_r1, false, CLS_AUX31), "AUX", der),
        "a1A" | "a2A" | "a1M" | "a2M" => (q(14, false), ty(0, false, CLS_AUX31), "AUX", "derived (isqrt fact pair w14)".to_string()),
        "xn8" => (q(8, true), ty(m.e_xn, true, CLS_ACT8), "ACT8", syn),
        "xm8" => (q(8, true), ty(m.e_xm, true, CLS_ACT8), "ACT8", syn),
        "rhoA_lo" | "sigA_lo" => (q(W_LIMB, false), ty(0, false, CLS_REM), "REM", format!("derived (norm DIV limb {W_LIMB} of w{})", m.wrho_a)),
        "rhoA_hi" | "sigA_hi" => (q(m.wrho_a - W_LIMB, false), ty(0, false, CLS_REM), "REM", format!("derived (norm DIV limb hi of w{})", m.wrho_a)),
        "rhoM_lo" | "sigM_lo" => (q(W_LIMB, false), ty(0, false, CLS_REM), "REM", format!("derived (norm DIV limb {W_LIMB} of w{})", m.wrho_m)),
        "rhoM_hi" | "sigM_hi" => (q(m.wrho_m - W_LIMB, false), ty(0, false, CLS_REM), "REM", format!("derived (norm DIV limb hi of w{})", m.wrho_m)),
        "Qacc" => (q(acc768, true), ty(m.e_xn + E_W, true, CLS_ACC), "ACC", der),
        "Kacc" => (q(acc768, true), ty(m.e_xn + E_W, true, CLS_ACC), "ACC", der),
        "Vacc" => (q(acc768, true), ty(m.e_xn + E_W, true, CLS_ACC), "ACC", der),
        "q8" => (q(8, true), ty(m.e_q, true, CLS_ACT8), "ACT8", meas(-3)),
        "k8" => (q(8, true), ty(m.e_k, true, CLS_ACT8), "ACT8", meas(-6)),
        "v8" => (q(8, true), ty(m.e_v, true, CLS_ACT8), "ACT8", meas(-3)),
        "rQ" => (q(m.sh_q, false), ty(m.e_xn + E_W, false, CLS_REM), "REM", der),
        "rK" => (q(m.sh_k, false), ty(m.e_xn + E_W, false, CLS_REM), "REM", der),
        "rV" => (q(m.sh_v, false), ty(m.e_xn + E_W, false, CLS_REM), "REM", der),
        "QRacc" | "KRacc" => (q(acc_rope, true), ty(m.e_q - 7, true, CLS_ACC), "ACC", der),
        "qr8" => (q(8, true), ty(m.e_qr, true, CLS_ACT8), "ACT8", meas(-3)),
        "kr8" => (q(8, true), ty(m.e_kr, true, CLS_ACT8), "ACT8", meas(-6)),
        "rQR" | "rKR" => (q(7, false), ty(m.e_q - 7, false, CLS_REM), "REM", der),
        "Sacc" => (q(acc_score, true), ty(m.e_qr + m.e_kr, true, CLS_ACC), "ACC", der),
        "s8" => (q(8, true), ty(m.e_s, true, CLS_ACT8), "ACT8", meas(-2)),
        "rS" => (q(m.sh_s, false), ty(m.e_qr + m.e_kr, false, CLS_REM), "REM", der),
        "m" => (q(8, true), ty(m.e_s, true, CLS_ACT8), "ACT8", strq),
        "d" => (q(8, false), ty(m.e_s, false, CLS_AUX31), "AUX", strq),
        "zsel" => (q(1, false), ty(0, false, CLS_AUX31), "AUX", strq),
        "E" => (qf(F_E as u32 + 1, F_E as u32, false), ty(-(F_E as i32), false, CLS_AUX31), "AUX", strq),
        "Sum" => (qf(m.wrho_sm + 1, F_E as u32, false), ty(-(F_E as i32), false, CLS_AUX31), "AUX", strq),
        "P" => (qf(F_P as u32 + 1, F_P as u32, false), ty(-(F_P as i32), false, CLS_AUX31), "AUX", strq),
        "rho" | "sig" => (q(m.wrho_sm, false), ty(-(F_E as i32), false, CLS_REM), "REM", strq),
        "Oacc" => (q(acc_pv, true), ty(m.e_v - F_P as i32, true, CLS_ACC), "ACC", der),
        "o8" => (q(8, true), ty(m.e_o, true, CLS_ACT8), "ACT8", meas(-3)),
        "rO" => (q(m.sh_o, false), ty(m.e_v - F_P as i32, false, CLS_REM), "REM", der),
        "AOacc" => (q(acc768, true), ty(m.e_o + E_W, true, CLS_ACC), "ACC", der),
        "ao8" => (q(8, true), ty(m.e_ao, true, CLS_ACT8), "ACT8", seam(-3)),
        "rAO" => (q(m.sh_ao, false), ty(m.e_o + E_W, false, CLS_REM), "REM", der),
        "xw1" => (q(xw1_b, true), ty(std::cmp::min(E_X, m.e_ao), true, CLS_ACC), "ACC", der),
        "xres1" => (q(8, true), ty(m.e_r1, true, CLS_ACT8), "ACT8", seam(0)),
        "rr1" => (q(m.sh_r1, false), ty(std::cmp::min(E_X, m.e_ao), false, CLS_REM), "REM", der),
        "xw2" => (q(bits_signed(254), true), ty(m.e_r1, true, CLS_ACC), "ACC", der),
        "xres2" => (q(8, true), ty(m.e_r2, true, CLS_ACT8), "ACT8", seam(0)),
        "rr2" => (q(m.sh_r2, false), ty(m.e_r1, false, CLS_REM), "REM", der),
        "Wq" | "Wk" | "Wv" | "Wo" => (q(8, true), tyw(E_W), "W8S", wsrc),
        "gA" | "gM" => (q(8, true), tyw(E_GAMMA), "W8S", "study gamma class eG -6 (oracle convention)".to_string()),
        _ => unreachable!(),
    }
}

/// [UPERF3-NN] rung 1 — `uperf-x entries [seed] [t]`: the typed entry
/// enumeration, reconciled against the spec §4.1 census (66 = witness
/// 60 + weights 6) and the memo §1 inventory; deltas FLAGGED.
fn uperf_x_entries(seed: u64, t: usize) {
    use ring::attn_entries::{derive_layer, x1_entry_shape, X1_BLOCKS, X1_ENTRIES};
    use sha2::{Digest, Sha256};
    let lay = derive_layer(seed, t);
    let mut out: Vec<String> = Vec::new();
    out.push(format!(
        "[UPERF3-NN] entries seed {seed} t {t} (toy: d 128, H 2, Hkv 1, dh 64) — AT-O2: UNFUSED (66)"
    ));
    let mut block_iter = X1_BLOCKS.iter();
    let mut block_left = 0usize;
    let mut counted = 0usize;
    for e in 0..X1_ENTRIES.len() {
        if block_left == 0 {
            let (bn, bc) = block_iter.next().unwrap();
            block_left = *bc;
            out.push(format!("  -- {bn} ({bc})"));
        }
        block_left -= 1;
        counted += 1;
        let (r, c) = x1_entry_shape(e, t);
        let (qm, ty, cls, src) = x1_entry_typing(e, &lay);
        out.push(format!(
            "  {:>2} {:<8} {:>4}x{:<4} {:<4} bits {:>2}{} frac {} scale 2^{:<3} sym {} e0 {} | {}",
            e,
            X1_ENTRIES[e],
            r,
            c,
            cls,
            qm.bits,
            if qm.signed { "s" } else { "u" },
            qm.frac_bits,
            ty.scale_exp,
            if ty.symmetric { 1 } else { 0 },
            ty.base_e0,
            src
        ));
    }
    assert_eq!(counted, 66);
    out.push("  RECONCILIATION vs spec §4.1 / memo §1:".to_string());
    out.push("    census 66/66 (witness 60 + weights 6): attn_norm 11, qkv 9, rope 6, scores 3, softmax 8, pv 3, wo 3, resid1 3, mlp_norm 11, resid2 3, weights 6 — MATCHES".to_string());
    out.push(format!(
        "    softmax rho/sig SINGLE range facts at w{} = fE + log2(T) (18 at 125M T=512; §2.9 split rule) — no limb split; norm remainders split ({}, {})",
        lay.meta.wrho_sm,
        ring::attn_entries::W_LIMB,
        lay.meta.wrho_a - ring::attn_entries::W_LIMB
    ));
    out.push("    FLAG (delta, by design): X_l input + the FFN 17 are the MVP-1 entries (shared, not re-counted); resid2 consumes the FFN output — toy chain uses a seeded stand-in (the X3 seam)".to_string());
    out.push("    FLAG (delta, by design): Gemma AM-5 sites (QK-norm x2, post_attn/post_ffn norms) are NOT in the §4.1 125M inventory — the §1.6b postn measured row has no entry here; they enter with the route-N adapter, not X1".to_string());
    out.push("    FLAG (class registry): attention aux (D/Dsq/a1/a2/d/zsel/E/Sum/P) rides CLS_AUX31 + CLS_REM — no dedicated narrow class row added (frozen registries untouched); whether narrower classes pay is an X3 pricing item".to_string());
    out.push("    C2 axes (§1.6b MEASURED): per-tensor (degenerate) at every core site; per-head vectors NOT needed at first order — head-axis kept as the AM-3 recorded escape (the pw-battery's coeff-MLE leg exercises the machinery)".to_string());
    let mut h = Sha256::new();
    for l in &out {
        h.update(l.as_bytes());
        h.update(b"\n");
        println!("{l}");
    }
    let dg: [u8; 32] = h.finalize().into();
    println!("[UPERF3-NN] X1 ENTRIES DIGEST {}", hex_full(&dg));
}

/// [UPERF3-NN] rung 2 — `uperf-x layer-chain [seed] [t]`: the full
/// toy-layer value chain; stdout byte-diffable vs the stated reference
/// scripts/attention_x1_layer_ref.py (acceptance (c) at layer scope).
fn uperf_x_layer_chain(seed: u64, t: usize) {
    use ring::attn_entries::{derive_layer, layer_header_lines, X1_ENTRIES};
    use ring::attn_softmax::tensor_digest;
    use sha2::{Digest, Sha256};
    let lay = derive_layer(seed, t);
    for l in layer_header_lines(seed, &lay) {
        println!("{l}");
    }
    let mut combined = Sha256::new();
    for (e, name) in X1_ENTRIES.iter().enumerate() {
        let dg = tensor_digest(&lay.entries[e]);
        combined.update(dg);
        println!("  {name:<8} {}", ring::attn_entries::hex32(&dg));
    }
    let cd: [u8; 32] = combined.finalize().into();
    println!("  CHAIN {}", ring::attn_entries::hex32(&cd));
}

/// The layer CHAIN digest (sha256 over the 66 entry digests) — the
/// head-prove statement's layer-binding bytes.
fn x1_chain_digest(lay: &ring::attn_entries::X1Layer) -> [u8; 32] {
    use ring::attn_softmax::tensor_digest;
    use sha2::{Digest, Sha256};
    let mut combined = Sha256::new();
    for e in 0..ring::attn_entries::X1_ENTRIES.len() {
        combined.update(tensor_digest(&lay.entries[e]));
    }
    combined.finalize().into()
}

/// Dense multilinear evaluation by folding (LSB-first: bit j of the
/// index pairs with point[j] — the house eq_table convention). The
/// INDEPENDENT second evaluation path of the F5 legs.
fn x1_mle_fold(kf: &ring::kfield::KField, vals: &[ring::kfield::KElem], point: &[ring::kfield::KElem]) -> ring::kfield::KElem {
    let mut cur = vals.to_vec();
    let n = 1usize << point.len();
    assert!(vals.len() <= n);
    cur.resize(n, kf.zero());
    for p in point {
        let half = cur.len() / 2;
        let mut nxt = Vec::with_capacity(half);
        for i in 0..half {
            let lo = &cur[2 * i];
            let hi = &cur[2 * i + 1];
            nxt.push(kf.add(lo, &kf.mul(p, &kf.sub(hi, lo))));
        }
        cur = nxt;
    }
    cur.into_iter().next().unwrap()
}

/// [UPERF3-NN] rung 3 — `uperf-x pw-battery [seed]`: the PW-1..PW-4
/// builders' F5 legs (each public-weight functional == its direct
/// evaluation at random points, two independent code paths) + the
/// head-indexed public coefficient MLE (the BG layer-MLE precedent
/// extended to (l, h)) + the rope-cs member freeze legs.
fn uperf_x_pw_battery(seed: u64) {
    use ring::attn_entries::{derive_layer, rope_member, seeded_w8, HEAD_DIM as DH, TOY_GQA_GROUP, TOY_H};
    use ring::gkr::eq_table;
    use ring::kfield::{KElem, KField};
    use ring::sumcheck::LkpTranscript;
    use sha2::{Digest, Sha256};
    let t0 = Instant::now();
    let ctx_ring = ring_ctx_q8();
    let kf = KField::new(&ctx_ring);
    let zq = ctx_ring.zq;
    let t = 16usize;
    let lay = derive_layer(seed, t);
    let h0 = uk8_sha(&[b"uperf3-nn-pw", &seed.to_le_bytes()]);
    let mut tr = LkpTranscript::new("uperf3-nn-pw", &h0);
    let mut draw = |n: usize| -> Vec<KElem> { (0..n).map(|_| tr.challenge_k(&kf)).collect() };
    let embed = |v: i64| kf.embed(zq.to_mod(v));
    let embed_col = |vals: &[i64]| -> Vec<KElem> { vals.iter().map(|&v| embed(v)).collect() };
    let dense_eval = |vals: &[KElem], point: &[KElem]| -> KElem {
        let ez = eq_table(&kf, point);
        let mut acc = kf.zero();
        for (x, v) in vals.iter().enumerate() {
            if !kf.is_zero(v) {
                acc = kf.add(&acc, &kf.mul(v, &ez[x]));
            }
        }
        acc
    };
    let mut legs: Vec<(String, bool)> = Vec::new();
    let mut leg = |name: &str, ok: bool| {
        assert!(ok, "PW battery leg FAILED: {name}");
        println!("  leg {name}: ok");
        legs.push((name.to_string(), ok));
    };

    // ---- PW-1: RoPE flip-read + sign-folded c/s weight closed forms. ----
    {
        let q8 = lay.entry("q8"); // [t, H*64] head-major; n = 2048 = 2^11
        let n = q8.len();
        let lv = n.trailing_zeros() as usize;
        let (ctab, stab, _) = rope_member(t);
        let half = DH / 2;
        // index bits: i = b & 63 (bits 0-5; top-of-head bit 5), h = bit 6.., t = high bits
        let lgh = TOY_H.trailing_zeros() as usize;
        let qk = embed_col(q8);
        let qracc = lay.entry("QRacc");
        let r = draw(lv);
        // (a) flip-read exact identity: dense sum of eq(r,b)*q8(flip b)
        //     == MLE(q8) at r with coordinate 5 replaced by 1 - r_5.
        let flip_tab: Vec<KElem> = (0..n).map(|b| qk[b ^ half].clone()).collect();
        let dense_flip = dense_eval(&flip_tab, &r);
        let mut r_flip = r.clone();
        r_flip[5] = kf.sub(&kf.one(), &r[5]);
        let fold_flip = x1_mle_fold(&kf, &qk, &r_flip);
        leg("pw1-flip-read-identity", dense_flip == fold_flip);
        // (b) the rotation relation as a weighted zero point: the honest
        //     witness satisfies QRacc = cW o q8 + sW o q8(flip) pointwise.
        let cw = |b: usize| -> i64 { ctab[(b >> (6 + lgh)) * half + (b & (half - 1))] };
        let sw = |b: usize| -> i64 {
            let s = stab[(b >> (6 + lgh)) * half + (b & (half - 1))];
            if (b >> 5) & 1 == 1 { s } else { -s }
        };
        let mut acc = kf.zero();
        let ez = eq_table(&kf, &r);
        for b in 0..n {
            let resid = qracc[b] - cw(b) * q8[b] - sw(b) * q8[b ^ half];
            if resid != 0 {
                acc = kf.add(&acc, &kf.mul(&embed(resid), &ez[b]));
            }
        }
        leg("pw1-rotation-zero-check", kf.is_zero(&acc));
        // (c) cW~ closed form: head + top-of-head bits marginalize to 1.
        let cw_tab: Vec<KElem> = (0..n).map(|b| embed(cw(b))).collect();
        let dense_cw = dense_eval(&cw_tab, &r);
        let c_small: Vec<KElem> = (0..t * half).map(|x| embed(ctab[x])).collect();
        let mut pt_small: Vec<KElem> = r[..5].to_vec();
        pt_small.extend_from_slice(&r[6 + lgh..]);
        let closed_cw = x1_mle_fold(&kf, &c_small, &pt_small);
        leg("pw1-cw-closed-form", dense_cw == closed_cw);
        // (d) sW~ closed form: the sign rides the top-of-head bit as
        //     the factor (2*r_5 - 1).
        let sw_tab: Vec<KElem> = (0..n).map(|b| embed(sw(b))).collect();
        let dense_sw = dense_eval(&sw_tab, &r);
        let s_small: Vec<KElem> = (0..t * half).map(|x| embed(stab[x])).collect();
        let sign = kf.sub(&kf.add(&r[5], &r[5]), &kf.one());
        let closed_sw = kf.mul(&sign, &x1_mle_fold(&kf, &s_small, &pt_small));
        leg("pw1-sw-closed-form", dense_sw == closed_sw);
    }

    // ---- PW-2: the GQA/MQA map as public K-side weight structure. -------
    {
        // (a) the layer's own map (H 2 -> Hkv 1, g(h) = h/2 = 0: MQA).
        let kr8 = lay.entry("kr8"); // [t, 64]
        let lgh = TOY_H.trailing_zeros() as usize;
        let lv = lgh + (t * DH).trailing_zeros() as usize;
        let r = draw(lv);
        let (r_h, r_tj) = (&r[lv - lgh..], &r[..lv - lgh]);
        let stacked: Vec<KElem> = (0..TOY_H * t * DH)
            .map(|b| {
                let h = b >> ((t * DH).trailing_zeros() as usize);
                let tj = b & (t * DH - 1);
                let _g = h / TOY_GQA_GROUP; // = 0 at Hkv 1
                embed(kr8[tj])
            })
            .collect();
        let dense = dense_eval(&stacked, &r);
        // structured: sum_h eq(r_h, h) * MLE(kr8)(r_tj) with g(h) = 0.
        let eq_h = eq_table(&kf, r_h);
        let mle_k = x1_mle_fold(&kf, &embed_col(kr8), r_tj);
        let mut structured = kf.zero();
        for eh in eq_h.iter().take(TOY_H) {
            structured = kf.add(&structured, &kf.mul(eh, &mle_k));
        }
        leg("pw2-mqa-map-h2-hkv1", dense == structured);
        // (b) a NONTRIVIAL map on synthetic data: H 2 -> Hkv 2 identity
        //     (g(h) = h): the head bits pass through to the kv index.
        let k2 = seeded_w8("x1-pw2", seed, t * 2 * DH);
        let lv2 = (2 * t * DH).trailing_zeros() as usize;
        let r2 = draw(lv2);
        let (r2_h, r2_tj) = (&r2[lv2 - 1..], &r2[..lv2 - 1]);
        // stacked read: b = (h, t, j) reads k2[t, h*64 + j] (g = h).
        let lgtj = (t * DH).trailing_zeros() as usize;
        let stacked2: Vec<KElem> = (0..2 * t * DH)
            .map(|b| {
                let h = b >> lgtj;
                let tt = (b & (t * DH - 1)) >> 6;
                let j = b & (DH - 1);
                embed(k2[tt * 2 * DH + h * DH + j])
            })
            .collect();
        let dense2 = dense_eval(&stacked2, &r2);
        // structured: sum_h eq(r_h, h) * MLE(k2)(r_j, bits(h), r_t) —
        // the kv-head coordinate of k2's index space pinned to h.
        let eq_h2 = eq_table(&kf, r2_h);
        let mut structured2 = kf.zero();
        for h in 0..2usize {
            let mut pt: Vec<KElem> = r2_tj[..6].to_vec(); // j bits
            pt.push(if h == 1 { kf.one() } else { kf.zero() }); // kv-head bit
            pt.extend_from_slice(&r2_tj[6..]); // t bits
            let v = x1_mle_fold(&kf, &embed_col(&k2), &pt);
            structured2 = kf.add(&structured2, &kf.mul(&eq_h2[h], &v));
        }
        leg("pw2-gqa-identity-map-h2-hkv2", dense2 == structured2);
    }

    // ---- PW-3: causal mask closed form + band degeneracy. ---------------
    {
        let lgt = t.trailing_zeros() as usize;
        let ra = draw(lgt); // row point
        let rb = draw(lgt); // col point
        // dense: sum over support pairs.
        let ea = eq_table(&kf, &ra);
        let eb = eq_table(&kf, &rb);
        let mut dense = kf.zero();
        for tt in 0..t {
            for c in 0..=tt {
                dense = kf.add(&dense, &kf.mul(&ea[tt], &eb[c]));
            }
        }
        // closed form (O(log T) DP): le~ = lt + eq over MSB-first bits.
        let mut eq_acc = kf.one();
        let mut lt_acc = kf.zero();
        for j in (0..lgt).rev() {
            let a = &ra[j];
            let b = &rb[j];
            let both0 = kf.mul(&kf.sub(&kf.one(), a), &kf.sub(&kf.one(), b));
            let both1 = kf.mul(a, b);
            let a1b0 = kf.mul(a, &kf.sub(&kf.one(), b));
            lt_acc = kf.add(&lt_acc, &kf.mul(&eq_acc, &a1b0));
            eq_acc = kf.mul(&eq_acc, &kf.add(&both0, &both1));
        }
        let closed = kf.add(&lt_acc, &eq_acc);
        leg("pw3-causal-mle-closed-form", dense == closed);
        // pub_mass tie on the full TxT index space (row bits HIGH).
        let rho = draw(2 * lgt);
        let et = eq_table(&kf, &rho);
        let mut mass = kf.zero();
        for tt in 0..t {
            for c in 0..=tt {
                mass = kf.add(&mass, &et[tt * t + c]);
            }
        }
        let mut eq_acc2 = kf.one();
        let mut lt_acc2 = kf.zero();
        for j in (0..lgt).rev() {
            let a = &rho[lgt + j]; // row bit
            let b = &rho[j]; // col bit
            let both0 = kf.mul(&kf.sub(&kf.one(), a), &kf.sub(&kf.one(), b));
            let both1 = kf.mul(a, b);
            let a1b0 = kf.mul(a, &kf.sub(&kf.one(), b));
            lt_acc2 = kf.add(&lt_acc2, &kf.mul(&eq_acc2, &a1b0));
            eq_acc2 = kf.mul(&eq_acc2, &kf.add(&both0, &both1));
        }
        leg("pw3-mask-mass-tie", mass == kf.add(&lt_acc2, &eq_acc2));
        // band degeneracy (AM-6): window w >= T => band == causal.
        let w = 2 * t; // any window >= T
        let mut same = true;
        for tt in 0..t {
            for c in 0..t {
                let band = c <= tt && tt < c + w;
                let causal = c <= tt;
                same &= band == causal;
            }
        }
        leg("pw3-band-degenerates-at-T<=window", same);
        // wrong-mask sanity: the shifted triangle's MLE differs (whp).
        let mut dense_shift = kf.zero();
        for tt in 0..t {
            for c in 0..t.min(tt + 2) {
                dense_shift = kf.add(&dense_shift, &kf.mul(&ea[tt], &eb[c]));
            }
        }
        leg("pw3-shifted-mask-differs", dense_shift != closed);
    }

    // ---- PW-4: broadcast reads (free row/col MLE reads). -----------------
    {
        let lgt = t.trailing_zeros() as usize;
        let lgd = ring::attn_entries::TOY_D.trailing_zeros() as usize;
        // (a) row-broadcast divisor: Sum_bc over columns == MLE(Sum) at
        //     the row coordinates (the G4 eq_hi pin identity).
        let sum = &lay.entry("Sum")[..t]; // head 0's Sum column
        let z = draw(2 * lgt);
        let bc: Vec<KElem> = (0..t * t).map(|x| embed(sum[x / t])).collect();
        let dense = dense_eval(&bc, &z);
        let fold = x1_mle_fold(&kf, &embed_col(sum), &z[lgt..]);
        leg("pw4-row-broadcast-divisor", dense == fold);
        // (b) col-broadcast weight vector: G_bc over rows == MLE(G) at
        //     the column coordinates (the RMSNorm G read).
        let g = lay.entry("gA");
        let z2 = draw(lgt + lgd);
        let bc2: Vec<KElem> = (0..t << lgd).map(|x| embed(g[x & ((1 << lgd) - 1)])).collect();
        let dense2 = dense_eval(&bc2, &z2);
        let fold2 = x1_mle_fold(&kf, &embed_col(g), &z2[..lgd]);
        leg("pw4-col-broadcast-gamma", dense2 == fold2);
        // (c) row-broadcast D (the norm divisor read), scaled by 2^tn.
        let dd = lay.entry("DA");
        let z3 = draw(lgt + lgd);
        let tn = lay.meta.tn_a;
        let bc3: Vec<KElem> = (0..t << lgd).map(|x| embed(dd[x >> lgd] << tn)).collect();
        let dense3 = dense_eval(&bc3, &z3);
        let fold3 = kf.scale(zq.to_mod(1i64 << tn), &x1_mle_fold(&kf, &embed_col(dd), &z3[lgd..]));
        leg("pw4-row-broadcast-normdiv", dense3 == fold3);
    }

    // ---- The head-indexed public coefficient MLE (AM-3 / §1.6: the BG
    //      layer-coefficient precedent extended to (l, h)). --------------
    {
        let n_l = 4usize;
        let n_h = TOY_H;
        let lv = (n_l * n_h).trailing_zeros() as usize;
        // statement shift table s_{l,h} (synthetic, seeded, in [0, 16)).
        let sv: Vec<i64> = seeded_w8("x1-coeff", seed, n_l * n_h).iter().map(|v| (v + 16) % 16).collect();
        let cvals: Vec<KElem> = sv.iter().map(|&s| embed(1i64 << s)).collect();
        let r = draw(lv);
        let dense = dense_eval(&cvals, &r);
        let fold = x1_mle_fold(&kf, &cvals, &r);
        leg("pwc-head-coeff-mle-f5", dense == fold);
        // wrong-vector: one tampered shift moves the value (whp) — the
        // statement-read obligation's terminal-mismatch analog.
        let mut sv2 = sv.clone();
        sv2[3] = (sv2[3] + 1) % 16;
        let cvals2: Vec<KElem> = sv2.iter().map(|&s| embed(1i64 << s)).collect();
        leg("pwc-wrong-vector-differs", dense_eval(&cvals2, &r) != dense);
    }

    // ---- rope-cs-table-v1 member freeze legs (AT-O6 discipline). --------
    {
        for tm in [16usize, 32usize] {
            let (c1, s1, d1) = rope_member(tm); // asserts the pinned digest
            let (c2, s2, d2) = rope_member(tm);
            leg(&format!("rope-t{tm}-deterministic"), c1 == c2 && s1 == s2 && d1 == d2);
            let bound_ok = c1.iter().chain(s1.iter()).all(|&v| v.abs() <= 128);
            leg(&format!("rope-t{tm}-bounds"), bound_ok && c1[0] == 128 && s1[0] == 0);
        }
    }

    let mut h = Sha256::new();
    for (name, ok) in &legs {
        h.update(name.as_bytes());
        h.update(if *ok { &b"=ok\n"[..] } else { &b"=FAIL\n"[..] });
    }
    let dg: [u8; 32] = h.finalize().into();
    println!(
        "[UPERF3-NN] pw-battery: {} legs ok in {:.1}s [WSL-BOX NOISY-SHARED]",
        legs.len(),
        t0.elapsed().as_secs_f64()
    );
    println!("[UPERF3-NN] X1 PW BATTERY DIGEST {}", hex_full(&dg));
}

/// Head-run config: the layer-calibrated statement member + the
/// head-tagged statement bytes over the xs1 core.
fn x1_head_cfg<'a>(
    lay: &'a ring::attn_entries::X1Layer,
    tab_wrong: &'a [i64; 256],
    chain_dig: &[u8; 32],
    h: usize,
    wit_tag: &'a str,
    session_tag: &'a str,
    extra_buf: &'a mut Vec<u8>,
) -> XsCfg<'a> {
    extra_buf.clear();
    extra_buf.extend(b"head");
    extra_buf.extend((h as u64).to_le_bytes());
    extra_buf.extend((ring::attn_entries::TOY_H as u64).to_le_bytes());
    extra_buf.extend(chain_dig);
    XsCfg {
        label: "uperf3-nn-x1",
        stmt_tag: b"uperf3-nn-x1-head-v1",
        stmt_extra: extra_buf,
        wit_tag,
        session_tag,
        es: lay.meta.e_s,
        tab_stmt: &lay.exp_tab,
        member_digest: lay.meta.exp_digest,
        tab_wrong,
    }
}

/// [UPERF3-NN] rung 4a — `uperf-x head-prove [seed] [t]`: the layer
/// chain's per-head s8 blocks through the X-S1 machinery (xs1_run_core
/// reused per head; head-tagged statements binding the LAYER-calibrated
/// exp member + the layer chain digest). Honest ACCEPT per head.
fn uperf_x_head_prove(seed: u64, t: usize) {
    use ring::attn_entries::{derive_layer, TOY_H};
    use ring::attn_softmax::{derive_chain, F_E, HEAD_DIM};
    use sha2::{Digest, Sha256};
    let lay = derive_layer(seed, t);
    let chain_dig = x1_chain_digest(&lay);
    let tab_wrong = ring::attn_softmax::exp_table_generate(lay.meta.e_s - 1, HEAD_DIM, F_E);
    println!(
        "[UPERF3-NN] head-prove seed {seed} t {t}: eS {} member {} (ZK_THREADS {})",
        lay.meta.e_s,
        ring::attn_entries::hex32(&lay.meta.exp_digest),
        ring::eval_proof::threads(),
    );
    let mut all = Sha256::new();
    all.update(chain_dig);
    for h in 0..TOY_H {
        let s8h = lay.s8_head(h);
        // the layer/spike tie: the per-head chain the core will derive
        // equals the LAYER's committed softmax slices bit-for-bit.
        let ch = derive_chain(t, &s8h, &lay.exp_tab);
        let n2 = t * t;
        assert_eq!(&ch.m[..], &lay.entry("m")[h * t..(h + 1) * t]);
        assert_eq!(&ch.p[..], &lay.entry("P")[h * n2..(h + 1) * n2]);
        assert_eq!(&ch.sigma[..], &lay.entry("sig")[h * n2..(h + 1) * n2]);
        let wit_tag = format!("uperf3-nn-wit-h{h}");
        let session_tag = format!("uperf3-nn-session-h{h}");
        let mut extra = Vec::new();
        let cfg = x1_head_cfg(&lay, &tab_wrong, &chain_dig, h, &wit_tag, &session_tag, &mut extra);
        let (verdict, _, n_pins, n_waves) = xs1_run_core(seed, t, &s8h, &cfg, XsTamper::None, false);
        let insts = xs_instances(t, lay.meta.e_s);
        println!(
            "[UPERF3-NN] head {h}: {} (first gate state: {})",
            if verdict.accept() { "ACCEPT" } else { "REJECT" },
            verdict.first_failed_gate(&insts)
        );
        assert!(verdict.accept(), "head {h}: honest run must accept");
        all.update((h as u64).to_le_bytes());
        all.update(b"accept");
        all.update((n_pins as u64).to_le_bytes());
        all.update((n_waves as u64).to_le_bytes());
    }
    let dg: [u8; 32] = all.finalize().into();
    println!("[UPERF3-NN] X1 HEAD-PROVE DIGEST {}", hex_full(&dg));
}

/// [UPERF3-NN] rung 4b — `uperf-x head-battery [seed] [t]`: the
/// AT-O8/O9-class tamper legs on the PER-HEAD proven chains (the X-S1
/// leg set at its pre-registered gates, driven on layer-derived s8;
/// legs alternate heads; the two chain-shape-dependent legs run on the
/// head whose block supports them — asserted, not skipped).
fn uperf_x_head_battery(seed: u64, t: usize) {
    use ring::attn_entries::{derive_layer, TOY_H};
    use ring::attn_softmax::{F_E, HEAD_DIM};
    use sha2::{Digest, Sha256};
    let t0 = Instant::now();
    let lay = derive_layer(seed, t);
    let chain_dig = x1_chain_digest(&lay);
    let tab_wrong = ring::attn_softmax::exp_table_generate(lay.meta.e_s - 1, HEAD_DIM, F_E);
    println!(
        "[UPERF3-NN] head-battery seed {seed} t {t} eS {} (ZK_THREADS {})",
        lay.meta.e_s,
        ring::eval_proof::threads(),
    );
    // leg support probes on the layer-derived blocks.
    let supports_mu = |s8: &[i64]| -> bool {
        let ch = ring::attn_softmax::derive_chain(t, s8, &lay.exp_tab);
        (1..t).rev().any(|r| {
            let mx = ch.m[r];
            mx > -127 && (0..=r).any(|c| s8[r * t + c] == mx - 1)
        })
    };
    let supports_tie = |s8: &[i64]| -> bool {
        let ch = ring::attn_softmax::derive_chain(t, s8, &lay.exp_tab);
        (1..t).rev().any(|r| (0..=r).filter(|&c| s8[r * t + c] == ch.m[r]).count() >= 2)
    };
    let head_for = |pred: &dyn Fn(&[i64]) -> bool, name: &str| -> usize {
        (0..TOY_H)
            .find(|&h| pred(&lay.s8_head(h)))
            .unwrap_or_else(|| panic!("no head supports the {name} leg at this seed/T"))
    };
    let legs: Vec<(XsTamper, usize, &str)> = vec![
        (XsTamper::MOverstate, 0, "G2 F-hit"),
        (XsTamper::MUnderstate, head_for(&supports_mu, "m-understate"), "rng-d-w8 root cross-check"),
        (XsTamper::ZselTwoHot, head_for(&supports_tie, "zsel-two-hot"), "G1 F-one"),
        (XsTamper::ZselOffsupport, 1, "G2 F-hit"),
        (XsTamper::OffsupportP, 1, "G6 off-support batch zero-check"),
        (XsTamper::ShiftedMask, 0, "G3 Sum (masked row sum, PW-3 weight check)"),
        (XsTamper::WrongExpMember, 1, "masked-claims sum gate"),
    ];
    let mut all = Sha256::new();
    all.update(chain_dig);
    let mut n_ok = 0usize;
    for (tamper, h, expect) in &legs {
        let s8h = lay.s8_head(*h);
        let wit_tag = format!("uperf3-nn-wit-h{h}");
        let session_tag = format!("uperf3-nn-session-h{h}");
        let mut extra = Vec::new();
        let cfg = x1_head_cfg(&lay, &tab_wrong, &chain_dig, *h, &wit_tag, &session_tag, &mut extra);
        let (verdict, _, _, _) = xs1_run_core(seed, t, &s8h, &cfg, *tamper, true);
        let insts = xs_instances(t, lay.meta.e_s);
        let gate = verdict.first_failed_gate(&insts);
        let ok = !verdict.accept() && gate.starts_with(expect);
        println!(
            "  leg {:?} head {h}: {} at '{}' (pre-registered '{}')",
            tamper,
            if verdict.accept() { "ACCEPT(!)" } else { "REJECT" },
            gate,
            expect
        );
        assert!(ok, "leg {tamper:?} did not reject at its pre-registered gate");
        n_ok += 1;
        all.update(format!("{tamper:?}|h{h}|{gate}").as_bytes());
    }
    let dg: [u8; 32] = all.finalize().into();
    println!(
        "[UPERF3-NN] head-battery: {n_ok}/{} legs at their pre-registered gates in {:.1}s [WSL-BOX NOISY-SHARED]",
        legs.len(),
        t0.elapsed().as_secs_f64()
    );
    println!("[UPERF3-NN] X1 HEAD BATTERY DIGEST {}", hex_full(&dg));
}
